  ui_story_5070_50700101_11_dialog_content = "정말... 내가 콜로서스 자금 운용은 늘 주의하라고 했잖아.\n내가 항상 콜로서스에 있을 순 없으니까.",
  ui_story_5070_50700101_12_dialog_content = "그래도... 다행히 운명은 아직 우릴 버리지 않은 것 같아... 이걸 봐!",
  ui_story_5070_50700101_13_dialog_content = "린 가문 상회에서 온 긴급 편지야. 방금 쿠리어가 주고 갔어.",
  ui_story_5070_50700101_14_dialog_content = "「상회의 미래가 달린 일입니다. 부디 PlayerName 님께서...」",
  ui_story_5070_50700101_15_dialog_content = "「콜로서스 조종사, 그리고 마음을 감응하는 힘의 주인으로서 도움을 주셨으면 합니다.」",
  ui_story_5070_50700101_16_dialog_content = "린 가문 상회한테는 우리도 그동안 신세를 많이 졌잖아.\n마침 이번엔 우리 도움이 필요하고, 보수도 두둑하게 준다고 해!",
  ui_story_5070_50700101_17_dialog_content = "그럼 린 가문 사람들도 도우면서 돈도 벌 수 있다는 거야?",
  ui_story_5070_50700101_18_dialog_content = "진짜 잘됐네! 지금 당장 움브라톤으로 가자!",
  ui_story_5070_50700101_19_dialog_content = "잠깐만, 의뢰 장소는 움브라톤이 아냐.",
