  ui_story_5070_50700101_21_dialog_content = "린 가문 상회의 미래가 달린 의뢰인데, 본부로 안 가도 된단 말이야?",
  ui_story_5070_50700101_22_dialog_content = "...린 가문에게 쌍사성은 움브라톤만큼이나 중요한 의미를 가지고 있는 곳이거든.",
