  ui_story_5070_50700101_24_dialog_content = "아직 휴가도 남았으니까 너희랑 같이 지낼 수 있어.\n게다가 여기서 쌍사성에 대해 아는 건 나뿐이잖아.",
  ui_story_5070_50700101_25_dialog_content = "백야성 입장에서도 쌍사성과 움브라톤의 무역 흐름은 매우 중요한 경제적 요인이거든.",
  ui_story_5070_50700101_26_dialog_content = "아득한 바다 건너에 있는 용주 대륙은 물자도 풍부하고 생산량도 많아.",
  ui_story_5070_50700101_27_dialog_content = "게다가 많은 산물과 기술이 아스트라에서는 만들 수 없는 양질의 것들이야.",
