  ui_story_5070_50700101_29_dialog_content = "그리고 저들이 바다를 넘어 아스트라에 온 뒤로 처음 정착한 곳이 바로 쌍사성이야.",
  ui_story_5070_50700101_30_dialog_content = "쌍사성은 지금도 용주 상선이 오가는 유일한 항구고,\n린 가문의 무역에 있어 기반이 되는 곳이야.",
  ui_story_5070_50700101_31_dialog_content = "이렇게 급하게 널 부르는 걸 보면 편지에서 말한 <color=#FFB400>「상회의 미래가 달린 일」</color>이라는 게\n아마 과장은 아닐 거야.",
  ui_story_5070_50700101_32_dialog_content = "그럼 아무래도 서두르는 게 좋겠어.",
