  ui_story_5070_50700101_34_dialog_content = "내가 안내해 줄 수 있어.",
  ui_story_5070_50700101_35_dialog_content = "골드리버를 따라 하류로 가면 금방이야.",
  ui_story_5070_50700101_36_dialog_content = "여기가 쌍사성이야? 진짜 신기하네. 아스트라의 분위기랑은 완전 달라!",
  ui_story_5070_50700101_37_dialog_content = "마치 다른 세계의 경치를 오려서 붙인 것 같은 느낌이야.",
  ui_story_5070_50700101_38_dialog_content = "나도 책에서 관련 자료를 본 게 전부고, 실제로 보는 건 처음이네.",
  ui_story_5070_50700101_39_dialog_content = "이 땅의 발전은 린 가문이 이끌었다고 해.\n게다가 린 가문이 항로를 개척하면서 바다를 건너오는 사람들이 늘었고...",
  ui_story_5070_50700101_40_dialog_content = "이곳에 정착하는 용주인들도 점차 늘어났어.",
  ui_story_5070_50700101_41_dialog_content = "그 결과 아스트라에 이런 용주 분위기의 도시가 세워진 거야.",
  ui_story_5070_50700101_42_dialog_content = "...확실히 책에서 읽은 것보다 훨씬 특색 있는 곳이네.",
  ui_story_5070_50700101_43_dialog_content = "고기만두 나왔습니다! 갓 만든 따끈따끈 고기만두 사세요! 손님, 하나 어때요?",
  ui_story_5070_50700101_44_dialog_content = "관광 오셨습니까? 그럼 제가 파는 차를 한잔 드셔보시죠.",
  ui_story_5070_50700101_45_dialog_content = "우전의 용정차, 운몽호의 은아차, 무량의 대엽차, 단산의 암차까지,\n명차라고 불리는 것이라면 뭐든지 있습니다!",
  ui_story_5070_50700101_46_dialog_content = "향이 좋은데?",
  ui_story_5070_50700101_47_dialog_content = "전부 다 처음 보는 물건들이야. 의뢰만 끝내면 꼭 제대로 한번 둘러봐야겠어.",
  ui_story_5070_50700101_48_dialog_content = "아, 참. 그러고 보니까 상회 사람들은 어디 가서 찾아야 하려나?",
  ui_story_5070_50700101_49_dialog_content = "<color=#e8d9bb>그 순간, 갑자기 바람이 불었다.</color>",
  ui_story_5070_50700101_50_dialog_content = "으앗! 내 편지──!",
  ui_story_5070_50700101_51_dialog_content = "어어어? 금색 잠자리가 물었잖아?!",
