  ui_story_5070_50700101_55_dialog_content = "별일 아닌걸~",
  ui_story_5070_50700101_56_dialog_content = "...저것도 용주 특산품인가?",
  ui_story_5070_50700101_57_dialog_content = "드디어 찾았네요! PlayerName 님 되시나요?",
  ui_story_5070_50700101_58_dialog_content = "네, 맞아요. 저예요. 린 가문을 도우러 왔어요!",
  ui_story_5070_50700101_59_dialog_content = "제가 바로 린 가문 상회 사람이에요. 이렇게 먼 길 와 주셔서 정말 감사합니다.\n그럼 자세한 이야기는 가면서 하실까요?",
  ui_story_5070_50700101_60_dialog_content = "린 가문 상회에 대해서는 아마 여러분도 어느 정도는 알고 계시겠죠.",
  ui_story_5070_50700101_61_dialog_content = "저희는 아스트라엔 없는 용주의 기술이나 산물을 가져와 이 대륙 각지에서 팔고 있어요.",
  ui_story_5070_50700101_62_dialog_content = "하지만 용주와 아스트라는 큰 바다를 사이에 두고 있어서 무척 위험해요.",
  ui_story_5070_50700101_63_dialog_content = "그래서 지금까지도 겨우 린 가문의 배만 선조가 개척한 항로를 따라\n철마다 왕래하면서 물자를 운반하고 있는 정도예요.",
  ui_story_5070_50700101_64_dialog_content = "그런데 그 운반을 맡은 중요한 상선 신풍호가 어찌 된 영문인지\n반년째 모습을 보이지 않고 있어요.",
  ui_story_5070_50700101_65_dialog_content = "반년이나요? 설마 용주 쪽에서 무슨 일이 생긴 건가요?",
  ui_story_5070_50700101_66_dialog_content = "그건... 저희도 모르겠어요.",
  ui_story_5070_50700101_67_dialog_content = "지금 두 대륙 간의 유일한 연락 수단은 린 가문의 상선뿐이야.",
  ui_story_5070_50700101_68_dialog_content = "아마 린 가문 상회에서도 당장은 용주의 본가와 연락을 취할 다른 방법이 없는 거겠지.",
