  ui_story_5070_50700101_70_dialog_content = "아스트라나 용주의 어떤 설비로도 대양을 뛰어넘는 통신은 불가능해요.",
  ui_story_5070_50700101_71_dialog_content = "그나마 다행이라면, 저흰 이틀 전 해상에서 린 가문 내부 연락용 신호를 수신했어요!",
  ui_story_5070_50700101_72_dialog_content = "분명히 이번 분기의 상선이 온 거겠죠!",
  ui_story_5070_50700101_73_dialog_content = "그런데 저희가 응답하기 전에 신호가 다시 사라지더니, 지금까지 다시 나타나질 않았어요.",
  ui_story_5070_50700101_74_dialog_content = "알겠어요. 그럼 제가 콜로서스로 그 배를 찾아달라는 얘기죠?",
  ui_story_5070_50700101_75_dialog_content = "맞아요! 지금 상황에서 저희에겐 당신이 유일한 희망이에요.",
  ui_story_5070_50700101_76_dialog_content = "알겠어요. 최선을 다해서 찾을게요.",
  ui_story_5070_50700101_77_dialog_content = "(그 후 며칠 동안, 우리는 콜로서스로 해상을 샅샅이 수색했다.)",
  ui_story_5070_50700101_78_dialog_content = "항구 앞 바다는 샅샅이 찾았지만 배는커녕 나무판자 하나 못 봤어.",
  ui_story_5070_50700101_79_dialog_content = "적어도 근처에서 사고를 당한 건 아니라는 뜻이니까, 그나마 다행인 셈 아닐까?",
