  ui_story_5070_50700101_83_dialog_content = "지금의 스카이워커는 아직 먼바다의 폭풍엔 대응할 수 없어...",
  ui_story_5070_50700101_84_dialog_content = "그리고 나도 해상 비행은 경험이 부족해. 가장 멀리 간 것도 기껏해야 운도 근처였으니까...",
  ui_story_5070_50700101_85_dialog_content = "만약 그 배가 더 먼 바다에서 조난당한 거라면, 구조가 힘들지도 몰라.",
  ui_story_5070_50700101_86_dialog_content = "......",
  ui_story_5070_50700101_87_dialog_content = "...왜 다들 말도 안 하고 나만 쳐다보고 있어?",
  ui_story_5070_50700101_88_dialog_content = "그거야 평소 PlayerName 너라면...",
  ui_story_5070_50700101_89_dialog_content = "그런 약한 말 뒤엔 꼭 「그치만」이 따라붙을 테니까, 안 그래?",
  ui_story_5070_50700101_90_dialog_content = "둘 다 날 너무 고집쟁이로 보는 거 아냐? 그치만... 역시 맞아.",
