  ui_story_5070_50700101_92_dialog_content = "그럼 지금부터 이쪽 해역에서 최대한 넓은 범위를 감응해 볼게.\n뭔가 단서를 찾을 수 있었으면 좋겠는데...",
  ui_story_5070_50700101_93_option_content = "(강제 감응!)",
  ui_story_5070_50700101_94_dialog_content = "풍향을 따라서... 찾았어! 저쪽 방향에 오로리안이 여러 명 있는 게 느껴져!",
  ui_story_5070_50700101_95_dialog_content = "다행이야! 드디어 단서를 찾았네!",
  ui_story_5070_50700101_96_dialog_content = "잠깐만, 하늘이 변했어. 뒤쪽 바다는 거울처럼 잔잔한데...",
  ui_story_5070_50700101_97_dialog_content = "앞쪽 해역은 풍랑이 심해!",
  ui_story_5070_50700101_98_dialog_content = "배가 보여! 엄청 큰 배야!",
  ui_story_5070_50700101_99_dialog_content = "린 가문의 상선이 맞아.",
  ui_story_5070_50700101_100_dialog_content = "얼른 구하러 가자! 콜로서스가 어디까지 버틸 수 있을지 모르겠지만...",
  ui_story_5070_50700101_101_dialog_content = "PlayerName, 잠깐만.",
  ui_story_5070_50700101_102_dialog_content = "자세히 봐.",
  ui_story_5070_50700101_103_dialog_content = "으음... 배 위에 있는 사람들... 조금 긴장한 것 같긴 해도, 허둥지둥하진 않는데?",
  ui_story_5070_50700101_104_dialog_content = "갑판 위의 사라들이 다들 명확한 목표를 가지고 움직이고 있어.\n누군가 정확하게 지시를 내리고 있는 것처럼 말이야.",
  ui_story_5070_50700101_105_dialog_content = "서, 선장님! 하늘에 뭔가가 있는 것 같아요...",
  ui_story_5070_50700101_106_dialog_content = "일단 집중해. 타를 꽉 잡고 타각을 유지해.",
  ui_story_5070_50700101_107_dialog_content = "바다에서 눈을 떼지 마.",
  ui_story_5070_50700101_108_dialog_content = "단숨에 뚫고 나가는 거야!",
  ui_story_5070_50700101_109_dialog_content = "예!",
  ui_story_5070_50700101_110_dialog_content = "<color=#e8d9bb>몰아치는 파도, 거칠게 밀려오는 조수... 물보라는 고막을 찢을 듯한 굉음을 내고 있다.</color>",
  ui_story_5070_50700101_111_dialog_content = "<color=#e8d9bb>소용돌이치던 바닷물이 서서히 모여들어 더욱 무서운 기세로 덮쳐오는 순간,\n배는 거센 파도를 무사히 헤쳐 나올 수 있었다.</color>",
  ui_story_5070_50700101_112_dialog_content = "다행이야! 배가 무사히 나왔어!",
  ui_story_5070_50700101_113_dialog_content = "휴...",
  ui_story_5070_50700101_114_dialog_content = "조마조마했어... 심장이 멈추는 줄 알았다니까.",
  ui_story_5070_50700101_115_dialog_content = "저 배의 선장, 분명히 대단한 사람이야.",
  ui_story_5070_50700101_116_dialog_content = "선체에 파손된 흔적이 많았어. 아마 오는 동안 거센 파도에 시달려 왔겠지.",
  ui_story_5070_50700101_117_dialog_content = "그런데도 저렇게 안정적으로 운항할 수 있다니... 저 배도 정말 고생했겠네.",
  ui_story_5070_50700101_118_dialog_content = "남은 항로는 바다도 잔잔하니까, 사고가 날 걱정은 안 해도 될 것 같아.",
  ui_story_5070_50700101_119_dialog_content = "정박할 때까지 콜로서스에서 지켜보자.",
  ui_story_5070_50700101_120_dialog_content = "신풍이다! 신풍호가 왔다!",
  ui_story_5070_50700101_121_dialog_content = "어째 전이랑 생김새가 달라진 것 같은데?!",
  ui_story_5070_50700101_122_dialog_content = "잘 모르나 본데, 저건 이제 예전의 그 신풍호가 아냐.",
  ui_story_5070_50700101_123_dialog_content = "몇 년 전부터 소문이 있었잖아.\n업나라 장인들이 제나라 배에 새로운 핵심 기관 부품을 만들어 주고 있다고 말이야...",
  ui_story_5070_50700101_124_dialog_content = "저 배는 분명히 그걸로 개선된 새 배일 거라고!",
  ui_story_5070_50700101_125_dialog_content = "더 빠르고, 더 안정적이고, 더 튼튼한! 천하에 하나뿐인 새 신풍호라 이 말이야!",
  ui_story_5070_50700101_126_dialog_content = "사, 사람이 엄청 많은데?",
  ui_story_5070_50700101_127_dialog_content = "상선이 항구에 도착하면 마을 사람들이 저절로 모여들기 마련이야.\n일종의 소소한 의식이라 할 수 있겠지.",
  ui_story_5070_50700101_128_dialog_content = "아하하... 근데 다들 신나게 환영하고 있어서 우리한텐 배도 안 보이잖아.",
  ui_story_5070_50700101_129_dialog_content = "PlayerName 님! PlayerName 님! 드디어 찾았네요!",
  ui_story_5070_50700101_130_dialog_content = "아, 린 가문 상회의...",
  ui_story_5070_50700101_131_dialog_content = "네! 보시다시피 신풍호가 무사히 입항했어요!",
  ui_story_5070_50700101_132_dialog_content = "지금 선장님이 여러분을 만나고 싶다고 하셔요. 이쪽으로 오세요.",
  ui_story_5070_50700101_133_dialog_content = "선장님? 근데 저희는 아무것도 안 했는데요...",
  ui_story_5070_50700101_134_dialog_content = "그렇지 않아.",
  ui_story_5070_50700101_135_dialog_content = "신풍호 선장, 목월백이라고 해.",
  ui_story_5070_50700101_136_dialog_content = "전설의 아이테르에겐 아무것도 아니었을지도 모르지만, 신풍호에겐 큰 도움이 됐어.",
  ui_story_5070_50700101_137_dialog_content = "실은 반년 전에 린 가문의 한 상선이 바다에서 사고를 당해 실종되고 말았어.",
  ui_story_5070_50700101_138_dialog_content = "우리가 해상에서 방위를 살피고 항로를 결정하는 데 사용하던\n천측 기구 「혼천의」도 그때 함께 사라져 버렸지.",
  ui_story_5070_50700101_139_dialog_content = "그래서 우린 해도와 경험만을 믿고 다시 항로를 개척하던 참이었어.",
  ui_story_5070_50700101_140_dialog_content = "비록 폭풍과 암귀의 습격은 이겨냈지만, 소용돌이치는 조수에 삼켜졌을 땐 정말 위험했어.",
  ui_story_5070_50700101_141_dialog_content = "만약 PlayerName 씨 당신의 인도가 없었다면...",
  ui_story_5070_50700101_142_dialog_content = "그 조수에서 빠져나왔더라도 항구까지 가는 길을 찾는 데는 시간이 꽤 걸렸을 거야.",
  ui_story_5070_50700101_143_dialog_content = "그래서 당신 자신은 아무것도 안 했다고 생각하겠지만,\n난 배를 인도하고 지켜봐 준 은혜에 감사해야 마땅해.",
  ui_story_5070_50700101_144_dialog_content = "린 가문에 은혜를 베푼 이에게는 배로 보답하고 문객으로 모시는 것,\n그게 우리 린 가문 상회의 규율이야.",
  ui_story_5070_50700101_145_dialog_content = "만약 쌍사성 지부에서 추가분의 보수를 지급하지 않는다면, 내가 선장으로서 대신 지급할게.",
  ui_story_5070_50700101_146_dialog_content = "크, 크흠! 모, 목 선장님, 그렇게 말씀하실 것까지야...",
  ui_story_5070_50700101_147_dialog_content = "저흰 그저 아스트라의 계약 문화에 따라 일을 진행했을 뿐인걸요.\n게다가 이분도 특정 세력에 몸을 담으실 분은 아니라서요...",
  ui_story_5070_50700101_148_dialog_content = "그럼 직접 답을 줬으면 좋겠어, PlayerName 씨.\n린 가문과 형제가 될 의향이 있을까?",
  ui_story_5070_50700101_149_dialog_content = "(하아? 내가 잘못 이해한 건 아니겠지? 나보고 린 가문의 일원이 되라는 얘긴가?)",
  ui_story_5070_50700101_150_dialog_content = "저기... 솔직히 말해서 고액의 보수라면 받고 싶긴 한데요...",
  ui_story_5070_50700101_151_dialog_content = "제가 그냥 지켜보기만 했을 뿐인 건 사실이잖아요.\n게다가 아스트라에서는 계약을 중요하게 생각해요.",
  ui_story_5070_50700101_152_dialog_content = "은혜라면 저도 린 가문에 신세를 진 게 있으니까 피차일반이고요.",
  ui_story_5070_50700101_153_dialog_content = "그러니까 전 그렇게 많은 보수는 받을 수 없고, 린 가문의 일원도 될 수 없어요.",
  ui_story_5070_50700101_154_dialog_content = "......",
  ui_story_5070_50700101_155_dialog_content = "후훗, 목 선장은 은혜와 위엄을 두루 보여 교섭에 능하다고 내 일찍이 들었거늘...",
  ui_story_5070_50700101_156_dialog_content = "이런 날도 오게 될 줄이야, 참으로 재미있구나.",
  ui_story_5070_50700101_157_dialog_content = "하면 내가 중재를 맡는 것은 어떠한가.",
  ui_story_5070_50700101_158_dialog_content = "이쪽의 공자가 이 땅에서 납득할 수 있는 방식으로 선장과 친교를 맺게 하는 게야.",
  ui_story_5070_50700101_159_dialog_content = "좋아요, 전 딱히 무슨 맹약이나 특별한 신분 같은 건 필요 없어요.\n그저 린 가문 여러분과 친구가 되고 싶을 뿐이에요.",
  ui_story_5070_50700101_160_dialog_content = "앞으로 선장님은 제 콜로서스를 보러 오셔도 좋아요.\n그리고 저도 신풍호를 둘러볼 수 있으면 그걸로 충분할 것 같아요.",
  ui_story_5070_50700101_161_dialog_content = "...신풍호는 대규모 수리가 필요해. 지금 상태로는 손님을 맞이하기 곤란해.",
  ui_story_5070_50700101_162_dialog_content = "공주 전하께서 그렇게까지 말씀하신다면 그리하겠습니다.",
  ui_story_5070_50700101_163_dialog_content = "PlayerName 씨, 방금 전 범한 결례를 사과하고 싶어.",
  ui_story_5070_50700101_164_dialog_content = "괜찮아요! 그리고 다들 편하게 이름으로 불러주시면 돼요.",
  ui_story_5070_50700101_165_dialog_content = "신풍호는 여기 보름 정도 정박할 예정이야.\n필요한 게 많을 테니까, 또 뭔가 부탁할 기회가 있을지도 몰라.",
  ui_story_5070_50700101_166_dialog_content = "물론 보수는 충분히 준비할게.",
  ui_story_5070_50700101_167_dialog_content = "알겠어요! 그럼 오늘은 먼저 실례할게요.\n전 지금 저 기다리는 사람이 있거든요. 다음에 또 봐요!",
  ui_story_5070_50700101_168_dialog_content = "잠깐만요, 목 선장님. 신풍호가 보름이나 정박한다는 얘기는 처음 듣는데요...",
  ui_story_5070_50700101_169_dialog_content = "그리고 필요한 게 많을 거라니...",
  ui_story_5070_50700101_170_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5070_50700101_171_dialog_content = "<color=#e8d9bb>갑자기 머리 위에서 큰 소리가 나더니, 선체의 판자 하나가 부러져 바닷속으로 빠져버렸다.</color>",
  ui_story_5070_50700101_172_dialog_content = "저게 그 「필요」야.",
  ui_story_5070_50700101_173_dialog_content = "이, 이해했어요... 확실히 수리가 필요하겠네요.\n이따가 가서 선박공 이 씨랑 기술자 손 씨를 불러올게요.",
  ui_story_5070_50700101_174_dialog_content = "걱정 마세요. 모두 솜씨가 좋은 사람들이니까요.\n쌍사성의 선박 정비는 항상 두 사람이 맡고 있어요.",
  ui_story_5070_50700101_175_dialog_content = "내가 보기엔 힘들 것 같은데.",
  ui_story_5070_50700101_176_dialog_content = "PlayerName 얘는 왜 아직도 안 오는 거야...?\n설마 누구한테 붙잡힌 건 아니겠지?",
  ui_story_5070_50700101_177_dialog_content = "안 되겠어, 내가 좀 보고 올게!",
  ui_story_5070_50700101_178_dialog_content = "이곳이 바로 쌍사성인 게냐.",
  ui_story_5070_50700101_179_dialog_content = "대체로 용주의 건축 양식이나, 세세한 부분에서는 이역의 풍모를 지니고 있구나.\n과연 색다른 의취가 있는지고.",
  ui_story_5070_50700101_180_dialog_content = "구야, 한번 둘러보자꾸나.",
  ui_story_5070_50700101_181_dialog_content = "내 알기로 업나라의 한 거물도 이곳에 꽤 오래 머무르고 있느니라.",
  ui_story_5070_50700101_182_dialog_content = "혹여 흥미를 돋울 만한 곳을 소개해 줄는지 누가 알겠느냐.",
  ui_story_5070_50700101_183_dialog_content = "긴 여행으로 피곤하실 텐데 잠시 쉬시는 것은 어떠신지요, 전하.",
  ui_story_5070_50700101_184_dialog_content = "아이고, 구 소저는 어찌 그리도 풍류를 모르신답니까?",
  ui_story_5070_50700101_185_dialog_content = "산수 간을 노닐고 거리의 구경을 즐기는 것 모두 마음이 가는 대로 좇는 것이 중요하지요.",
  ui_story_5070_50700101_186_dialog_content = "하여 소생이 두 분과 동행하면서 전하와 기연이 있는 곳을 점쳐 드릴 수도 있는데, 어떠십니까?",
  ui_story_5070_50700101_187_dialog_content = "하아, 피곤하구나.",
  ui_story_5070_50700101_188_dialog_content = "구 말이 맞아. 내 월백에게 돌아가서 좀 쉬어야겠다.",
  ui_story_5070_50700101_189_dialog_content = "아이고, 전하... 잠시만요!",
  ui_story_5070_50700101_190_dialog_content = "미안하지만 나는 벗, 의인, 심지어 적조차 곁에 둘 수 있으나...",
  ui_story_5070_50700101_191_dialog_content = "오직 강호의 사기꾼만은 곁에 설 자리가 없느니라.",
  ui_story_5070_50700101_192_dialog_content = "아니, 긴 항해를 함께한 사이끼리 무슨 말씀을 그리 섭하게 하십니까...",
  ui_story_5070_50700101_193_dialog_content = "(우와... 저 사람... 정말 예쁘네... 근데 방금 전하라고 불린 것 같은데...?)",
  ui_story_5070_50700101_194_dialog_content = "바이스, 바이스! 뭐 보고 있어?",
  ui_story_5070_50700101_195_dialog_content = "앗! 드디어 왔구나!",
  ui_story_5070_50700101_196_dialog_content = "아무것도 안 봤어~ 그냥 저 신풍호 말인데, 물건만 잔뜩 가져온 게 아니라...",
  ui_story_5070_50700101_197_dialog_content = "다양한 사람들도 함께 온 것 같아. 우리랑 새로운 친구가 될 사람들도 있으려나?",
  ui_story_5070_50700101_198_dialog_content = "이거 곤란한데요... 기존의 신풍호라면 어떻게든 해 볼 만했겠지만...",
  ui_story_5070_50700101_199_dialog_content = "이 새로워진 신풍호는 화로니 산열 장치, 방수... 전부 우리가 모르는 기술들뿐입니다.",
  ui_story_5070_50700101_200_dialog_content = "업나라 공방에서 만든 기관 부품은 더 말할 것도 없고요.",
  ui_story_5070_50700101_201_dialog_content = "내 말대로지?",
  ui_story_5070_50700101_202_dialog_content = "......",
  ui_story_5070_50700101_203_dialog_content = "다들 무얼 그리 걱정하고 있는 게냐, 내게도 들려줄 수 있겠느냐.",
  ui_story_5070_50700101_204_dialog_content = "공주 전하...",
  ui_story_5070_50700101_205_dialog_content = "전하께서는 사명을 받으신 몸입니다. 하찮은 일로 전하께 폐를 끼칠 순 없습니다.",
  ui_story_5070_50700101_206_dialog_content = "휴, 설마 아까 중재하여 판을 깨트린 일로 아직도 화가 나 있는가.",
  ui_story_5070_50700101_207_dialog_content = "그대도 알다시피 용주의 8대 제후국은 복잡한 은원으로 서로 얽혀 있지...",
  ui_story_5070_50700101_208_dialog_content = "내 비록 이번 걸음은 제나라를 대표하는 사절로 온 것이나,\n어디까지나 업나라에서 보낸 볼모의 몸임은 변함이 없네.",
  ui_story_5070_50700101_209_dialog_content = "볼모의 신분으로 제나라의 진정한 신임을 받기는 어려운 일이지...",
  ui_story_5070_50700101_210_dialog_content = "하여 내 스스로 청하여 바다를 건너 이 대륙에 온 것이야.",
  ui_story_5070_50700101_211_dialog_content = "나는 행동으로 나의 성의를 증명하고자 한다.",
  ui_story_5070_50700101_212_dialog_content = "내 하는 일은 모두 제와 업 두 나라 무역의 번영과 백성의 안녕을 위해서일세.",
  ui_story_5070_50700101_213_dialog_content = "그 점에 있어 신풍호는 중요한 매개가 되니, 신풍호의 일이 어찌 내게 중요하지 않겠는가.",
  ui_story_5070_50700101_214_dialog_content = "그러니 내 신풍호를 위해 힘쓰는 것도 당연지사인 게지.",
  ui_story_5070_50700101_215_dialog_content = "...신풍호 수리 문제로 이야기를 나누고 있었습니다.",
  ui_story_5070_50700101_216_dialog_content = "이 새로운 배에 쓰인 기관은 업나라에서 심혈을 기울여 만들어 낸 첨단 기술의 산물로,\n지금까지의 것들과는 확연히 다릅니다.",
  ui_story_5070_50700101_217_dialog_content = "이 종류의 기술을 다루는 기교사가 아니라면 아마 수리는 어렵겠지요.",
  ui_story_5070_50700101_218_dialog_content = "재료라면 쌍사성에 얼마든지 있고, 목수도 충분히 있습니다만,\n신풍호의 기관을 고칠 수 있는 기교사만은...",
  ui_story_5070_50700101_219_dialog_content = "휴~",
  ui_story_5070_50700101_220_dialog_content = "...전하?",
  ui_story_5070_50700101_221_dialog_content = "다른 일이었다면 내 도움을 줄 방도가 없었을 게야.",
  ui_story_5070_50700101_222_dialog_content = "허나 우리 업나라 기관술에 능통한 기교사라면 마침 적합한 자를 알고 있지.",
  ui_story_5070_50700101_223_dialog_content = "월백, 신풍호 수리에 시일을 얼마나 쓸 생각인가.",
  ui_story_5070_50700101_224_dialog_content = "보름 내에 마쳐야 합니다.",
  ui_story_5070_50700101_225_dialog_content = "충분하구나.",
  ui_story_5070_50700101_226_dialog_content = "안심하게, 업나라 최고의 기교사가 바로 이 쌍사성에 있으니 말이야.",
  ui_story_5070_50700101_227_dialog_content = "그자가 만든 전음조를 이용하면... 금방 그자를 찾아낼 수 있겠지.",
  ui_story_5070_50700101_228_dialog_content = "신풍호도 무사히 입항했고, 우리 임무도 이걸로 끝났네... 휴...",
  ui_story_5070_50700101_229_dialog_content = "그런데 왜 그런 울상을 하고 있을까?",
  ui_story_5070_50700101_230_dialog_content = "알 것 같아, PlayerName 너 그땐 그렇게 딱 잘라 거절해놓고...",
  ui_story_5070_50700101_231_dialog_content = "지금은 추가 보수 거절한 거 후회하는 거지~?",
  ui_story_5070_50700101_232_dialog_content = "지금 그렇게 아쉬워할 거면 그때 솔직하게 받지 그랬어.",
  ui_story_5070_50700101_233_dialog_content = "...안 돼.",
  ui_story_5070_50700101_234_dialog_content = "확실히 요즘 콜로서스 수리니 평소 지출이니 어려운 상황이고...",
  ui_story_5070_50700101_235_dialog_content = "다음 의뢰가 또 언제 올지도 모르지만...",
  ui_story_5070_50700101_236_dialog_content = "그렇다고 아무것도 안 해 놓고 돈을 받는 건 역시 안 될 일이야.",
  ui_story_5070_50700101_237_dialog_content = "그리고 아직 한창 젊은 나이에 린 가문 상회의 직원이 되는 것도 좀...",
  ui_story_5070_50700101_238_dialog_content = "아니, 잘못 짚었어. 상회에 들어오라는 저쪽 제안은 네가 직원이 되라는 의미가 아냐.",
  ui_story_5070_50700101_239_dialog_content = "잠깐만, 지금 그게 문제가 아니지 않아?",
  ui_story_5070_50700101_240_dialog_content = "쌍사성 주민 여러분──!",
  ui_story_5070_50700101_241_dialog_content = "으앗! 엄청 큰 목소린데?! 누가 어디서 말하는 거지?",
  ui_story_5070_50700101_242_dialog_content = "누가 일루미나 군용 확성기라도 갖다 쓰는 건가?",
  ui_story_5070_50700101_243_dialog_content = "용주의 원양선 신풍호가 입항했습니다! 신풍호는 항구에 보름 정도 정박하면서──",
  ui_story_5070_50700101_244_dialog_content = "대대적인 수리를 진행할 예정입니다!",
  ui_story_5070_50700101_245_dialog_content = "그래서 온 쌍사성에 계신 인부와 기술자를 모집하는 바입니다──",
  ui_story_5070_50700101_246_dialog_content = "많이들 참가해서 여러분의 땀과 지혜로 신풍호를 도와주세요──",
  ui_story_5070_50700101_247_dialog_content = "그러면 바다를 건너온 풍요를 여러분도 함께 누리게 될 겁니다!",
  ui_story_5070_50700101_248_dialog_content = "하아... 하아... 사장님! 어, 얼른 사람 모으죠!",
  ui_story_5070_50700101_249_dialog_content = "임시로 일할 일꾼들을 얼른 모집해야겠어. 지금 바로 벽보를 붙이자고.",
  ui_story_5070_50700101_250_dialog_content = "벽보도 필요 없어요! 이미 다들 들었으니까요!",
  ui_story_5070_50700101_251_dialog_content = "대체 뭘 어떻게 한 거야? 쌍사성에 저런 설비는 없었을 텐데...",
  ui_story_5070_50700101_252_dialog_content = "설마 저게 바로 목 선장님이 얘기한 「필요」인 건가...",
  ui_story_5070_50700101_253_dialog_content = "그럼 잘됐네, 우리도 뭔가 할 만한 일이 없는지 보러 가자~",
  ui_story_5070_50700101_254_dialog_content = "어쩌면 여기서 큰돈을 벌 수 있을지도 모르잖아?",
  ui_story_5070_50700201_1_dialog_content = "(이렇게 해서 나는 쌍사성에서 2주간 꽤 충실한 시간을 보냈다.)",
  ui_story_5070_50700201_2_dialog_content = "(신풍호에 관련된 각종 의뢰를 수행했고, 그 외에도 다양한 일을 할 수 있었다...)",
  ui_story_5070_50700201_3_dialog_content = "(카렌과 함께 수리 중인 신풍호를 견학했고...)",
  ui_story_5070_50700201_4_dialog_content = "(수상한 점쟁이가 시키는 대로 이상한 제비를 많이 뽑았다...)",
  ui_story_5070_50700201_5_dialog_content = "(그리고 바이스와 함께 복을 빌고 화를 몰아내는 「용녀진해무」를 준비하기도 했다.)",
  ui_story_5070_50700201_6_dialog_content = "(그때 나와 바이스는 전에 날 도와주었던 단당 공주와 다시 한번 이야기를 나눌 수 있었다.)",
  ui_story_5070_50700201_7_dialog_content = "(처음에는 이국의 귀족이라 다가가기 어려운 사람일까 걱정했지만,\n예상외로 무척 지혜롭고 친화력 있는 사람이었다.)",
  ui_story_5070_50700201_8_dialog_content = "(단당 씨와 검은 옷을 입은 호위무사는 우리를 데리고\n용주의 문화와 풍습을 소개해 주었다.)",
  ui_story_5070_50700201_9_dialog_content = "(아쉬웠던 건 바이스와 카렌 모두 도중에 급한 연락이 와서,\n각자 일루미나 연방과 백야성으로 돌아갈 수밖에 없었다는 점이다.)",
  ui_story_5070_50700201_10_dialog_content = "(하지만 난 절대 이 절호의 기회를 놓치지 않고,\n두 사람 몫까지 열심히 돈을 벌 생각이다!)",
  ui_story_5070_50700201_11_dialog_content = "...공자, PlayerName 공자?",
  ui_story_5070_50700201_12_dialog_content = "...음? 앗! 미, 미안해요... 공주님, 잠깐 다른 생각을 좀 하고 있었어요.",
  ui_story_5070_50700201_13_dialog_content = "괜찮다. 중요한 얘기는 지금부터 하려던 참이었으니.",
  ui_story_5070_50700201_14_dialog_content = "허나 내 이르지 않았느냐, 단당이라 부르면 되느니라.",
  ui_story_5070_50700201_15_dialog_content = "아, 그랬죠. 미안해요, 단당 고... 아니, 단당 씨.",
  ui_story_5070_50700201_16_dialog_content = "휴, 되었다. 내 그대의 사과를 들으러 온 것이 아니거늘.",
  ui_story_5070_50700201_17_dialog_content = "일전에 내 월백에게 뛰어난 기교사를 찾아주지 않았더냐.",
  ui_story_5070_50700201_18_dialog_content = "그자 덕에 신풍호의 수리 작업은 순조롭게 이루어지고 있고, 벌써 마무리 단계에 들어섰다.",
  ui_story_5070_50700201_19_dialog_content = "하여 수리가 완료되는 날 축하 기념식을 거행하고자 우리도 준비를 시작했다.",
  ui_story_5070_50700201_20_dialog_content = "내가 맡은 임무 또한 그사이에 여러모로 성과가 있었고 말이야.",
  ui_story_5070_50700201_21_dialog_content = "그 카렌 공주 덕분에 백야성의 사절이 마침내 답을 보내왔다.",
  ui_story_5070_50700201_22_dialog_content = "무역 협상과 암귀 대응 문제를 두고 우리 용주의 손님들과 이야기하고 싶다 하였지.",
  ui_story_5070_50700201_23_dialog_content = "게다가 그 사절도 기념식에 참석하고, 함께 신풍호를 타고 용주로 가서\n제나라를 방문하겠다더구나.",
  ui_story_5070_50700201_24_dialog_content = "임무를 무사히 완수하셨네요, 축하해요, 단당 씨!",
  ui_story_5070_50700201_25_dialog_content = "후훗, PlayerName 그대에게 감사하마.",
  ui_story_5070_50700201_26_dialog_content = "하여 내 오늘은 그대를 기념식에 초대하고 싶어 온 게야.",
  ui_story_5070_50700201_27_dialog_content = "제가 가도 되나요? 그럼 얼마든지 가야죠!",
  ui_story_5070_50700201_28_dialog_content = "물론이다. 꼭 자리에 와 주거라.",
  ui_story_5070_50700201_29_dialog_content = "다만 바이스와 카렌 공주가 함께하지 못하는 것은 아쉽구나.\n두 사람의 도움에도 내 직접 감사의 말을 하고 싶었는데 말이야.",
  ui_story_5070_50700201_30_dialog_content = "그러니 내 PlayerName 공자를 더 잘 환대해야 하지 않겠느냐.",
  ui_story_5070_50700201_31_dialog_content = "알겠어요. 그럼 남은 일만 얼른 끝내고 기념식 날만 기다리고 있을게요!",
  ui_story_5070_50700201_32_dialog_content = "(어디 보자...)",
  ui_story_5070_50700201_33_dialog_content = "(동쪽에 있는 가게에 줄 영수증은... 이걸로 됐고.\n장인들이 빌린 도구도 다 모아서 반납했고.)",
  ui_story_5070_50700201_34_dialog_content = "(남은 화물들은 춘석가 끝에 있는 창고에 갖다주면... 되는데, 아직 안 끝났어...)",
  ui_story_5070_50700201_35_dialog_content = "(휴...)",
  ui_story_5070_50700201_36_dialog_content = "(아침부터 열심히 물건을 다 가지고 왔는데, 아무도 받으러 오질 않잖아.)",
  ui_story_5070_50700201_37_dialog_content = "(남는 시간에 다른 일까지 끝내고 왔는데 왜 아직도 사람이 안 오는 거야?)",
  ui_story_5070_50700201_38_dialog_content = "(오늘은 신풍호 축하 기념식 날인데... 더 안 왔다간 기념식에 늦겠어.)",
  ui_story_5070_50700201_39_dialog_content = "(그나저나 이 상자들은 어째 모양이 다 특이한데?)",
  ui_story_5070_50700201_40_dialog_content = "(배 수리에 쓰는 재료는 원래 이런 상자에 넣어야 하는 건가?)",
  ui_story_5070_50700201_41_dialog_content = "(...어?)",
  ui_story_5070_50700201_42_dialog_content = "(방금 왠지 상자가 움직인 것 같은데...?)",
  ui_story_5070_50700201_43_dialog_content = "<color=#e8d9bb>끼릭── 끼릭──</color>",
  ui_story_5070_50700201_44_dialog_content = "무슨 소리지?!",
  ui_story_5070_50700201_45_dialog_content = "<color=#e8d9bb>콰직!</color>",
  ui_story_5070_50700201_46_dialog_content = "이, 이게 뭐야...?! 게 괴물?! 가, 가까이 오지 마!",
  ui_story_5070_50700201_47_dialog_content = "그나마 도망치는 게 빨라서 망정이지... 안 그랬으면 저 녀석 집게에...",
  ui_story_5070_50700201_48_dialog_content = "끼이익!",
  ui_story_5070_50700201_49_dialog_content = "불도 뿜어?! 으아아앗!",
  ui_story_5070_50700201_50_dialog_content = "<color=#e8d9bb>괴물의 입에서는 타오르는 화염이 뿜어져 나오고 있었다.</color>",
  ui_story_5070_50700201_51_dialog_content = "<color=#e8d9bb>그러나 그 순간, 갑자기 커다란 우산이 눈앞에 나타났다.</color>",
  ui_story_5070_50700201_52_dialog_content = "<color=#e8d9bb>그리고 눈부신 금속의 반짝임과 함께, 펼쳐진 우산이 회전하면서\n매섭게 덮쳐오는 불꽃을 흩어버렸다.</color>",
  ui_story_5070_50700201_53_dialog_content = "날씨도 물건도 건조한데, 불조심해야지~",
  ui_story_5070_50700201_54_dialog_content = "<color=#e8d9bb>괴물의 몸에서는 불꽃이 끝없이 뿜어져 나왔지만,\n모두 우산에 막혀 그저 희미한 열만이 느껴질 뿐이었다.</color>",
  ui_story_5070_50700201_55_dialog_content = "어디서 들어본 목소리인데... 아! 생각났다! 저번에 잠자리로 편지 잡아 준 사람!",
  ui_story_5070_50700201_56_dialog_content = "그 우산은...?",
  ui_story_5070_50700201_57_dialog_content = "야, 위험해. 지금은 막 만지면 안 돼. 다쳐도 책임 못 져.",
  ui_story_5070_50700201_58_dialog_content = "일단 눈앞의 저 녀석부터 먼저 처리해야지.",
  ui_story_5070_50700202_1_dialog_content = "지, 진짜 대단하네!",
  ui_story_5070_50700202_2_dialog_content = "(그냥 우산처럼 보이지만, 그 어떤 명검보다도 날카로운 것 같아...)",
  ui_story_5070_50700202_3_dialog_content = "(열리면 물도 불도 막아내는 방패가 되고...)",
  ui_story_5070_50700202_4_dialog_content = "(닫으면 절대 부러지지 않는 칼날이 되잖아.)",
  ui_story_5070_50700202_5_dialog_content = "(움직임도 전혀 보이질 않아.)",
  ui_story_5070_50700202_6_dialog_content = "(가볍게 손을 움직여서 우산을 돌리기만 한 것 같은데,\n저 튼튼해 보이는 괴물을 고철로 만들고 있어.)",
  ui_story_5070_50700202_7_dialog_content = "끼이익──",
  ui_story_5070_50700202_8_dialog_content = "(어? 잠깐만... 고철? 그 말은... 이 괴물들, 사람이 만든 기계란 말이야?)",
  ui_story_5070_50700202_9_dialog_content = "이렇게 무서운 기계 게를... 대체 누가 무슨 목적으로 만든 거야...?",
  ui_story_5070_50700202_10_dialog_content = "이건 불게라고 해. 업나라 공방에서 흔히 쓰는 기관수야.",
  ui_story_5070_50700202_11_dialog_content = "장인의 일을 돕게 하려고 만든 거야.\n녀석들이 있으면 조립이나 용접 작업이 훨씬 더 편해지거든.",
  ui_story_5070_50700202_12_dialog_content = "빠르고 정확하게 필요한 크기의 불꽃을 낼 수 있고, 집게도 있으니까 아주 유용해~",
  ui_story_5070_50700202_13_dialog_content = "조립? 용접? 그럼 설마 이 녀석들... 날 무슨 기계 재료로 착각한 건 아니겠지?",
  ui_story_5070_50700202_14_dialog_content = "음... 재료로 본다면 당신은... 강성으로나 강도로나, 어떻게 봐도 재료로 전혀 맞질 않는걸.",
  ui_story_5070_50700202_15_dialog_content = "불게가 이런 초보적인 실수를 할 리가 없는데...",
  ui_story_5070_50700202_16_dialog_content = "...그걸 기뻐해야 하나 어째야 하나 모르겠네.",
  ui_story_5070_50700202_17_dialog_content = "게다가 업나라엔 기관수의 유통과 사용에 관한 규정이 있어.",
  ui_story_5070_50700202_18_dialog_content = "불게가 이런 데 나타난 것도 이상하고, 심지어 사람을 해치려고 하다니...",
  ui_story_5070_50700202_19_dialog_content = "분명히 누군가 수작을 부린 게 틀림없어.",
  ui_story_5070_50700202_20_dialog_content = "거기, 직접 나올래? 아니면 내가 꺼내줄까?",
  ui_story_5070_50700202_21_dialog_content = "(창고 안에 누가 있었어?!)",
  ui_story_5070_50700202_22_dialog_content = "<color=#e8d9bb>그 순간, 그늘 속에서 갑자기 검은 그림자가 튀어나와 입구 쪽으로 달려갔다.</color>",
  ui_story_5070_50700202_23_dialog_content = "거기 서!",
  ui_story_5070_50700202_24_dialog_content = "(공격이 빗나갔어... 어떻게든 막아야 해!)",
  ui_story_5070_50700202_25_dialog_content = "(강제 감응!)",
  ui_story_5070_50700202_26_dialog_content = "걱정 말라고. 이런 일이라면 움브라톤에서 오랫동안 해 왔으니까, 규칙은 알고 있다.",
  ui_story_5070_50700202_27_dialog_content = "돈을 받았으면 물론 요청대로 확실하게 일해야지.",
  ui_story_5070_50700202_28_dialog_content = "게다가 사용법도 배워야 하잖아... 이거 이름이 뭐랬더라?",
  ui_story_5070_50700202_29_dialog_content = "아, 그래. 화로 게라고 했었지.",
  ui_story_5070_50700202_30_dialog_content = "조금 귀찮긴 하군.",
  ui_story_5070_50700202_31_dialog_content = "허나 린 가문과 신풍호에 쓴맛을 보여줄 수 있다면 그 정도 귀찮음은 감수해야겠지.",
  ui_story_5070_50700202_32_dialog_content = "(...신풍호를 노린 건가? 하지만 왜...?)",
  ui_story_5070_50700202_33_dialog_content = "저리 비켜!",
  ui_story_5070_50700202_34_dialog_content = "으악!",
  ui_story_5070_50700202_35_dialog_content = "조심해.",
  ui_story_5070_50700202_36_dialog_content = "아... 고마워, 그냥 넘어졌으면 다쳤을 거야.\n그치만 저 사람을 놓쳐버렸잖아...",
  ui_story_5070_50700202_37_dialog_content = "됐어, 궁지에 몰린 쥐는 쫓지 않는 법이야.",
  ui_story_5070_50700202_38_dialog_content = "어차피 보잘것없는 졸개일 뿐이고.",
  ui_story_5070_50700202_39_dialog_content = "중요한 건 녀석의 윗선이야. 누구인지는 이미 예상하고 있어.",
  ui_story_5070_50700202_40_dialog_content = "졸개 정도야 쌍사성 주민들한테 부탁하면 돼.",
  ui_story_5070_50700202_41_dialog_content = "...어라? 그래! 이 목소리!",
  ui_story_5070_50700202_42_dialog_content = "어쩐지 익숙하더라니까.\n그럼 저번에 쌍사성 사람들한테 확성기로 말했던 사람도 당신이지?",
  ui_story_5070_50700202_43_dialog_content = "당신 대체 누구야?",
  ui_story_5070_50700202_44_dialog_content = "응? 당신 나 모르고 있었어?",
  ui_story_5070_50700202_45_dialog_content = "어... 미안하다고 해야 하나?",
  ui_story_5070_50700202_46_dialog_content = "아하하, 농담이야. 아무리 나라도 바다 건너까지\n이름이 알려져 있을 거라 자부하진 않으니까.",
  ui_story_5070_50700202_47_dialog_content = "그런데 단당 님이 내 얘기를 안 하셨을 줄은 몰랐네.\n난 단당 님한테 당신 얘기 많이 들었는데.",
  ui_story_5070_50700202_48_dialog_content = "이래서야 좀 불공평하잖아.",
  ui_story_5070_50700202_49_dialog_content = "뭐, 지금부터 알아가면 되겠지?",
  ui_story_5070_50700202_50_dialog_content = "난 선극이라고 해. 기교사야.",
  ui_story_5070_50700202_51_dialog_content = "단당 님이랑 마찬가지로 장인의 나라라고 불리는 업나라 출신이야.",
  ui_story_5070_50700202_52_dialog_content = "지금은 쌍사성에서 분실물 찾는 의뢰 같은 걸 받으면서 지내고 있어.",
  ui_story_5070_50700202_53_dialog_content = "최근엔 영광스럽게도 단당 님의 총애를 받아 임시로 신풍호의 기술자도 겸하고 있고.",
  ui_story_5070_50700202_54_dialog_content = "신풍호의 기관 수리랑 린 가문 상회에 빌려준 전음 기관조의 성능 시험도 하고 있어.",
  ui_story_5070_50700202_55_dialog_content = "그럼 그때 그건 기관조를 써서 한 거야...?",
  ui_story_5070_50700202_56_dialog_content = "응, 하늘을 나는 확성기라고 생각하면 돼.",
  ui_story_5070_50700202_57_dialog_content = "그래도 설계할 땐 입이나 깃털이나 세심하게 신경 써서 한 건데 말이야.",
  ui_story_5070_50700202_58_dialog_content = "...단당 씨가 말했던 「최고의 기교사」가 바로 선극 씨였구나.",
  ui_story_5070_50700202_59_dialog_content = "대단하네!",
  ui_story_5070_50700202_60_dialog_content = "내친김에 말하자면...",
  ui_story_5070_50700202_61_dialog_content = "저 바닥의 「크고 무서운 게」도 내가 설계한 거야.",
  ui_story_5070_50700202_62_dialog_content = "?",
  ui_story_5070_50700301_1_dialog_content = "이어서 목월백 선장님의 축사가 있겠습니다──",
  ui_story_5070_50700301_2_dialog_content = "이번에 신풍호가 무사히 수리를 마칠 수 있었던 것은 모두 여기에 모인 여러분 덕분입니다.",
  ui_story_5070_50700301_3_dialog_content = "따라서 오늘의 기념식은 여러분을 위해 준비된 것입니다.",
  ui_story_5070_50700301_4_dialog_content = "린 가문은 항상 노력과 근면의 가치를 중시해 왔습니다.\n이 자리를 빌어 기쁜 마음으로 여러분의 노고에 보답하고자 합니다.",
  ui_story_5070_50700301_5_dialog_content = "부디 부담 갖지 마시고 마음껏 즐겨 주세요.",
  ui_story_5070_50700301_6_dialog_content = "오오!",
  ui_story_5070_50700301_7_dialog_content = "선상에서 이렇게 성대한 식전을 열 수 있을 줄은 정말 몰랐습니다.",
  ui_story_5070_50700301_8_dialog_content = "왕림에 감사하네, 백야성의 텔마 공.",
  ui_story_5070_50700301_9_dialog_content = "아마 용주에 가면 더 많은 놀라움이 기다리고 있겠지요. 무척 기대가 됩니다.",
  ui_story_5070_50700301_10_dialog_content = "물론일세.",
  ui_story_5070_50700301_11_dialog_content = "용주는 먼 곳에서 손님을 환대하는 풍습이 있지.\n하물며 공은 백야성을 대표하는 빈객이 아닌가.",
  ui_story_5070_50700301_12_dialog_content = "성심을 다하여 대접함이 마땅하지.",
  ui_story_5070_50700301_13_dialog_content = "그 말씀을 들으니 정말 지금 당장 바다 건너로 날아가고 싶은 마음입니다.",
  ui_story_5070_50700301_14_dialog_content = "하지만 용주는 머나먼 곳이지요.\n전 먼저 신풍호에 사용된 용주의 그 기술을 좀 참관할 수 있었으면 좋겠군요.",
  ui_story_5070_50700301_15_dialog_content = "쌍사성에 온 뒤로 저는 용주의 기술에 대한 흥미로운 이야기를 많이 들었습니다.",
  ui_story_5070_50700301_16_dialog_content = "그 기술로 만들어진 물건들은 모두 작고 정교하며,\n성능도 다양해서 마치 예술품 같다고 하더군요.",
  ui_story_5070_50700301_17_dialog_content = "일루미나의 거추장스러운 기계나 사막의 차마 봐줄 수도 없는 그 물건들에 비하면\n훨씬 사랑스럽고 친근하다고 들었습니다.",
  ui_story_5070_50700301_18_dialog_content = "저마다 가진 기술에는 각자의 특성이 있지 않겠나, 물론 장단점도 가지고 있겠지.",
  ui_story_5070_50700301_19_dialog_content = "하면 내 지금 바로 공을 안내할 이를 데려오도록 하겠네.",
  ui_story_5070_50700301_20_dialog_content = "(선극은... 자리에 없는 것인가.)",
  ui_story_5070_50700301_21_dialog_content = "아, 손 씨라고 했던가, 마침 잘 왔네.",
  ui_story_5070_50700301_22_dialog_content = "고, 공주 전하?! 무, 무슨 일이십니까?",
  ui_story_5070_50700301_23_dialog_content = "여기 백야성의 사절에게 신풍호의 기관을 소개해 줄 수 있겠는가.",
  ui_story_5070_50700301_24_dialog_content = "아, 물론입죠!",
  ui_story_5070_50700301_25_dialog_content = "소인은 기관들을 다룬 지 벌써 수십 년이 되었습니다.\n이 일에 저보다 더 익숙한 사람은 없을 겁니다요.",
  ui_story_5070_50700301_26_dialog_content = "하면 내 부탁하겠네.",
  ui_story_5070_50700301_27_dialog_content = "그럼 나중에 뵙도록 하지요, 공주님.",
  ui_story_5070_50700301_28_dialog_content = "후...",
  ui_story_5070_50700301_29_dialog_content = "전하, 조금 쉬시겠습니까?",
  ui_story_5070_50700301_30_dialog_content = "아니, 되었다. 아직 그럴 정도는 아니니 말이다.",
  ui_story_5070_50700301_31_dialog_content = "허나... PlayerName 공자는 왜 아직도 보이지 않는 것일꼬.",
  ui_story_5070_50700301_32_dialog_content = "혹여 일이 너무 바빠 오지 못하는 것은 아닐지...",
  ui_story_5070_50700301_33_dialog_content = "그럼 제가 상황을 한번...",
  ui_story_5070_50700301_34_dialog_content = "...전하!",
  ui_story_5070_50700301_35_dialog_content = "으음? 왜 그러느냐.",
  ui_story_5070_50700301_36_dialog_content = "주변을 주의해 주십시오.",
  ui_story_5070_50700301_37_dialog_content = "......",
  ui_story_5070_50700301_38_dialog_content = "...아무래도 신풍호 승선 시 주의 사항 안내는 잠시 뒤로 미뤄야겠군요.",
  ui_story_5070_50700301_39_dialog_content = "뭐지? 무슨 일이 생겼나?",
  ui_story_5070_50700301_40_dialog_content = "이런 이런, 간만에 오는 연회 자리인데 이런 일을 당하다니...",
  ui_story_5070_50700301_41_dialog_content = "참으로 불길하군요.",
  ui_story_5070_50700301_42_dialog_content = "전원 경계 태세를 갖추도록!",
  ui_story_5070_50700301_43_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5070_50700301_44_dialog_content = "으악! 배가 흔들렸다!",
  ui_story_5070_50700301_45_dialog_content = "선장님! 큰일입니다! 기관수가 나타나 신풍호의 용골을 공격하고 있습니다!",
  ui_story_5070_50700301_46_dialog_content = "만물은 백야 아래에... 식전이 한창인데... 대체 이게 무슨 일입니까?!",
  ui_story_5070_50700301_47_dialog_content = "왜 아무도 말이 없죠? 이 배에 대체 무슨 일이 벌어진 겁니까!",
  ui_story_5070_50700301_48_dialog_content = "......",
  ui_story_5070_50700301_49_dialog_content = "전하께서는 여기서 기다려 주십시오. 제가 다녀오겠습니다.",
  ui_story_5070_50700301_50_dialog_content = "구야, 조심하거라.",
  ui_story_5070_50700302_1_dialog_content = "전하, 처리했습니다.",
  ui_story_5070_50700302_2_dialog_content = "다행이로구나.",
  ui_story_5070_50700302_3_dialog_content = "전하... 어찌 안색이 안 좋으신지요. 혹시 방금 전 소동으로 몸을 상하신 건...",
  ui_story_5070_50700302_4_dialog_content = "나는 괜찮다.",
  ui_story_5070_50700302_5_dialog_content = "문제는 조금 전 기관수의 소동으로 린 가문 상회는 지금\n신풍호의 출항을 늦추려고 논의하는 중이다.",
  ui_story_5070_50700302_6_dialog_content = "저희가 겁이 많아서 그런 게 아닙니다.",
  ui_story_5070_50700302_7_dialog_content = "바다는 애초에 위험으로 가득한 곳입니다. 암귀나 폭풍만으로도 힘든데...",
  ui_story_5070_50700302_8_dialog_content = "이번엔 이유를 알 수 없는 기관수의 습격까지 받고 있습니다.",
  ui_story_5070_50700302_9_dialog_content = "이대로는 너무 위험합니다. 아무래도 잠시 상황을 지켜보는 게 좋겠습니다.",
  ui_story_5070_50700302_10_dialog_content = "지금 우리에겐 지켜보고 있을 시간이 없다.",
  ui_story_5070_50700302_11_dialog_content = "제위도 알고 있겠지. 내 이곳에 사절로 온 것은 두 가지 임무가 있어서다.",
  ui_story_5070_50700302_12_dialog_content = "하나는 아스트라와의 통상을 한층 더 발전시켜, 보다 정식적인 무역 체계를 확립하는 것이다.",
  ui_story_5070_50700302_13_dialog_content = "그리고 다른 하나는 암귀에 맞서기 위한 전략과 기술을 교류하는 것이지.",
  ui_story_5070_50700302_14_dialog_content = "허나 이 두 가지 일이 무에 그리 중요한지, 제위는 알고 있는가?",
  ui_story_5070_50700302_15_dialog_content = "최근 용주 연해 지대는 암귀의 습격이 빈번하게 발생하고 있고,\n때문에 상선 출항도 큰 영향을 받고 있다.",
  ui_story_5070_50700302_16_dialog_content = "내가 있는 제나라는 8대 제후국 중에서도 가장 통상이 발달한 나라이고,\n수로와 해운이 근간이 되는 나라라 하여도 과언이 아니다.",
  ui_story_5070_50700302_17_dialog_content = "이에 따라 각 상회는 일찌감치 연명으로 상서를 올려 국군께 해결을 청했다.",
  ui_story_5070_50700302_18_dialog_content = "허나 우리는 지금까지 근본적인 해결책을 찾지 못했고, 암귀는 물러났다 오길 반복하니,\n백성들은 하는 수 없이 해변의 땅을 버렸고, 해적들은 기세를 되찾았다...",
  ui_story_5070_50700302_19_dialog_content = "상인은 근심이 가득하고, 백성들의 삶은 안녕을 잃으니, 해운 산업의 인심이 흉흉한 상황이다.",
  ui_story_5070_50700302_20_dialog_content = "하여 국군께서는 귀족을 사절로 명하여 아스트라 대륙에 가르침을 청하고자 했던 것이다.",
  ui_story_5070_50700302_21_dialog_content = "가까스로 백야성 사절을 초청하여 함께 용주로 향해 교류하겠다는 승낙을 얻었거늘...",
  ui_story_5070_50700302_22_dialog_content = "끝내...",
  ui_story_5070_50700302_23_dialog_content = "전 내립니다. 지금 당장 배에서 내릴 겁니다.",
  ui_story_5070_50700302_24_dialog_content = "이 배는 무조건 안전하다고 하지 않았습니까? 그런데 아직 출항도 안 했는데 습격이라니요.",
  ui_story_5070_50700302_25_dialog_content = "이게 당신들이 말하는 안전입니까?",
  ui_story_5070_50700302_26_dialog_content = "저 기계 괴물들이 사람을 습격할 수 있다는 말은 아무도 해준 적이 없단 말입니다!",
  ui_story_5070_50700302_27_dialog_content = "당신도 말하지 않았잖아요!",
  ui_story_5070_50700302_28_dialog_content = "그...그게...",
  ui_story_5070_50700302_29_dialog_content = "...나로서는 사절을 잠시나마 만류하는 일밖에 할 수 없었지.",
  ui_story_5070_50700302_30_dialog_content = "서둘러 배를 복구하여 출항하지 못하면 사태가 어떻게 바뀔지 모른다.\n그리된다면 나의 사명 또한...",
  ui_story_5070_50700302_31_dialog_content = "아...",
  ui_story_5070_50700302_32_dialog_content = "전하의 말씀은 물론 이해합니다. 하지만 아무리 급해도 이대로 무모하게 출항할 순 없습니다.",
  ui_story_5070_50700302_33_dialog_content = "이는 전하의 목숨까지 위험에 빠트리는 일입니다...",
  ui_story_5070_50700302_34_dialog_content = "전하, 역시 조금만 기다려 주시지요.",
  ui_story_5070_50700302_35_dialog_content = "사절이 정 동행을 원치 않거든, 제가 방법을 찾아 「모시고」 가겠습니다.",
  ui_story_5070_50700302_36_dialog_content = "무슨 일이 있어도 전하께서 무릅쓰신 위험을 결코 헛되이 만들 순 없습니다.",
  ui_story_5070_50700302_37_dialog_content = "크흠... 선장님 의견은요?",
  ui_story_5070_50700302_38_dialog_content = "......",
  ui_story_5070_50700302_39_dialog_content = "이번 항해는 매우 중대한 사명을 지고 있어. 공주 전하와 화물만 달린 문제가 아냐.",
  ui_story_5070_50700302_40_dialog_content = "린 가문의 미래도 달려 있어.",
  ui_story_5070_50700302_41_dialog_content = "우리도 이 이상의 손실은 감당할 수 없어... 더 큰 타격을 입는 것만은 막아야 해.",
  ui_story_5070_50700302_42_dialog_content = "맞아요. 그러니까 더 신중하게...",
  ui_story_5070_50700302_43_dialog_content = "배를 수리할게.",
  ui_story_5070_50700302_44_dialog_content = "귀항을 서두를 거야.",
  ui_story_5070_50700302_45_dialog_content = "케헥, 콜록콜록!",
  ui_story_5070_50700302_46_dialog_content = "목 선장님, 어떻게 선장님까지...",
  ui_story_5070_50700302_47_dialog_content = "저기, 선장님? 잠시만요... 선장님!",
  ui_story_5070_50700302_48_dialog_content = "휴... 요즘 사람들은 정말 성격이 급해서 곤란하다니까요.",
  ui_story_5070_50700302_49_dialog_content = "그러게나 말입니다. 옛말에도 급할수록 돌아가라 했는데 말이지요.",
  ui_story_5070_50700302_50_dialog_content = "뭐, 확실히 지금 상황에서는 서두르지 않는 것도 어렵겠지만 말입니다.",
  ui_story_5070_50700302_51_dialog_content = "음? 누구신지...?",
  ui_story_5070_50700302_52_dialog_content = "기념식에 강호의 사기꾼을 초대한 기억은 없다만.",
  ui_story_5070_50700302_53_dialog_content = "어이쿠, 무슨 말씀을 그리 섭섭하게 하십니까.",
  ui_story_5070_50700302_54_dialog_content = "뜻밖의 일이 생긴 탓에 여러분 모두 입맛도 없지 않으십니까?",
  ui_story_5070_50700302_55_dialog_content = "한 배 가득 진수성찬을 차렸는데, 낭비해서야 되겠습니까.\n제가 여러분 몫까지 거들어 드려야지요.",
  ui_story_5070_50700302_56_dialog_content = "음, 하나같이 별미들입니다만... 이 참외는 조금 아쉽군요.",
  ui_story_5070_50700302_57_dialog_content = "급하게 팔려고 빨리 수확한 모양인데, 억지로 딴 참외는 달지 않는 법입니다.",
  ui_story_5070_50700302_58_dialog_content = "이, 이런 시기에 잘도 떠드는구나...",
  ui_story_5070_50700302_59_dialog_content = "그냥 한번 해 본 이야기입니다. 기다릴지 말지는 전하에게 달렸지요.",
  ui_story_5070_50700302_60_dialog_content = "허나 쓴 참외를 억지로 입에 넣느니, 자연의 섭리대로 참외가 익기를\n기다리는 것이 정도 아니겠습니까?",
  ui_story_5070_50700302_61_dialog_content = "안 그렇습니까?",
  ui_story_5070_50700401_1_dialog_content = "음... 당신한테 기관술을 어떻게 설명하면 이해하기 쉬우려나?",
  ui_story_5070_50700401_2_dialog_content = "...그래! 아스트라에서는 사상의 힘에 대한 연구 수준이 높다고 들었어...",
  ui_story_5070_50700401_3_dialog_content = "사상의 힘?",
  ui_story_5070_50700401_4_dialog_content = "각 속성의 광력을 말하는 거야. 너흰 루미나라고 부르는 것 같던데.",
  ui_story_5070_50700401_5_dialog_content = "그러니까 기관술은 결국 각종 재료를 어떻게 합리적으로 사용해서...",
  ui_story_5070_50700401_6_dialog_content = "우리 광령이나 환수들처럼 광력을 사용하는 무생물을 만들 수 있는지 연구하는 기술이야.",
  ui_story_5070_50700401_7_dialog_content = "이렇게 말하면 대강 이해할 수 있으려나?",
  ui_story_5070_50700401_8_dialog_content = "음... 광령은 오로리안을 말하는 것 같고, 그럼 아스트라의 루미나 기계 기술 같은 건가?\n근데 느낌이 많이 다른걸.",
  ui_story_5070_50700401_9_dialog_content = "당연하지. 두 기술의 목적은 같아도 세상을 보는 방식은 다르니까.",
  ui_story_5070_50700401_10_dialog_content = "용주 사람들은 이 세상 만물에 광력이 깃들어 있다고 믿어.",
  ui_story_5070_50700401_11_dialog_content = "초목, 벌레, 짐승... 그 모든 게 광력의 순환 체계라고 볼 수 있는 거야.",
  ui_story_5070_50700401_12_dialog_content = "기관술은 그런 광력을 기관 재료 속에 깃들게 해서,\n특정한 규칙성을 바탕으로 다양한 효과를 만들어 낼 수 있어.",
  ui_story_5070_50700401_13_dialog_content = "그러니까 적절한 재료와 정확한 구조만 있다면,\n심지어는 또 다른 세계까지도 만들어 낼 수도 있는 거야.",
  ui_story_5070_50700401_14_dialog_content = "으음, 이번엔 왠지 무슨 창조의 철학 같은 느낌이네!",
  ui_story_5070_50700401_15_dialog_content = "아하하, 그것도 틀린 말은 아니야.",
  ui_story_5070_50700401_16_dialog_content = "아까 그 불게도, 내가 데리고 다니는 구리잠자리도 그런 철학의 구현이라고 할 수 있어.",
  ui_story_5070_50700401_17_dialog_content = "널 구해준 이 기천열산도 마찬가지고.",
  ui_story_5070_50700401_18_dialog_content = "이 안에는 다양한 기관이 숨겨져 있어서, 공격과 방어에 모두 활용할 수 있어.",
  ui_story_5070_50700401_19_dialog_content = "그리고 원리만 통달하면 기관술은 기관수뿐만 아니라 여러 분야에 응용할 수 있어.",
  ui_story_5070_50700401_20_dialog_content = "아무래도 기관술은 진짜로 단순한 기계공학 같은 건 아닌 모양이네...\n그렇게 대단한 건 줄은 몰랐어.",
  ui_story_5070_50700401_21_dialog_content = "한 나라의 근간이 되고, 린 가문의 항로 개척에도 기여하는 기술이라면\n물론 그렇게 간단할 리가 없겠지.",
  ui_story_5070_50700401_22_dialog_content = "업나라에서는 기관조가 하늘을 날아 서신을 전하고,\n땅에는 목우유마가 지상을 오가며 짐을 나르고 있어.",
  ui_story_5070_50700401_23_dialog_content = "심지어 세수나 옷 입기, 요리하는 게 귀찮으면 기관한테 대신 해달라고 할 수도 있어.",
  ui_story_5070_50700401_24_dialog_content = "당신이 용주에 놀러 올 일이 생기면, 내가 진정한 「기관」이 뭔지 보여줄게.",
  ui_story_5070_50700401_25_dialog_content = "좋아!",
  ui_story_5070_50700401_26_dialog_content = "근데...",
  ui_story_5070_50700401_27_dialog_content = "그래서 우린 지금 대체 뭐 하고 있는 건데?",
  ui_story_5070_50700401_28_dialog_content = "보면 모르겠어? 최근에 쓰인 적 있는 창고를 찾고 있잖아.",
  ui_story_5070_50700401_29_dialog_content = "그건 나도 당연히 알지. 아까부터 벌써 몇 군데나 돌았잖아.",
  ui_story_5070_50700401_30_dialog_content = "(선극 씨가 억지로 문을 따고 들어간 곳들도 많았지만, 전혀 막을 수 없었다고...)",
  ui_story_5070_50700401_31_dialog_content = "근데 지금은 적을 쫓는 게 우선 아냐?",
  ui_story_5070_50700401_32_dialog_content = "난 기교사야. 사람 찾는 일은 내가 성에 심어 둔 밀정한테 맡기면 돼.\n내 전문 분야는 어디까지나 기관이니까.",
  ui_story_5070_50700401_33_dialog_content = "몰래 숨어든 악당들이 어떻게 한 건지는 몰라도 내 설계도를 입수하고...",
  ui_story_5070_50700401_34_dialog_content = "불게를 개조해서 사람들을 해치게 만들어 신풍호의 창고에 들여보냈어.",
  ui_story_5070_50700401_35_dialog_content = "아까 그 무의미한 매복은 분명히 진짜 목적이 아니야.",
  ui_story_5070_50700401_36_dialog_content = "저들은 쌍사성 어딘가에 더 많은 비장의 수를 숨기고 있겠지.",
  ui_story_5070_50700401_37_dialog_content = "...신풍호는 괜찮을까?",
  ui_story_5070_50700401_38_dialog_content = "아까 그 불게의 위력이라면... 보통 사람이 습격을 당한다면 절대 맞설 수 없을 거야.",
  ui_story_5070_50700401_39_dialog_content = "「강자는 약자를 붙잡지 말고, 많은 무리는 적은 무리를 겁박하지 말며,\n부유한 자는 가난한 자를 업신여기지 말지어다...」",
  ui_story_5070_50700401_40_dialog_content = "기관술의 힘은 막강해. 따라서 그 힘을 지닌 자는 결코 그걸로 다른 이를 해쳐선 안 돼.",
  ui_story_5070_50700401_41_dialog_content = "그건 모든 기교사들이 함께 정했고, 반드시 지켜야 할 수칙이야.",
  ui_story_5070_50700401_42_dialog_content = "그러니까 내 설계도를 훔친 벌레 놈들을 찾는다면...",
  ui_story_5070_50700401_43_dialog_content = "(갑자기 엄청 냉정해졌어...)",
  ui_story_5070_50700401_44_dialog_content = "...참!",
  ui_story_5070_50700401_45_dialog_content = "아까 선극 씨 말대로라면 기관수는 자연계 생물의 루미나 흐름을 모방한 거잖아?",
  ui_story_5070_50700401_46_dialog_content = "그럼 내 감응 능력으로 다른 불게의 위치를 알아낼 수 있을지도 몰라!",
  ui_story_5070_50700401_47_dialog_content = "어? 그거 꽤 재미있는 발상이네.",
  ui_story_5070_50700401_48_dialog_content = "(감응 개시!)",
  ui_story_5070_50700401_49_dialog_content = "(아까 불게랑 비슷한 루미나가... 어디 보자... 있어!)",
  ui_story_5070_50700401_50_dialog_content = "루미나 자체는 미미하지만, 방향은 확실해. 이쪽이야!",
  ui_story_5070_50700401_51_dialog_content = "이런 외딴곳에 창고가 또 있었다니...",
  ui_story_5070_50700401_52_dialog_content = "고마워, PlayerName. 아무래도 당신을 만난 건 행운 같아~",
  ui_story_5070_50700401_53_dialog_content = "<color=#e8d9bb>언뜻 보기에 허름한 창고 안에는 특이한 모양의 상자들이 가득 쌓여 있었다.\n그리고 그 상자들 안에는...</color>",
  ui_story_5070_50700401_54_dialog_content = "불게, 부유조, 전갈... 흐음, 아주 다 모여 있잖아...\n심지어 사용한 재료도 모두 상등품이야.",
  ui_story_5070_50700401_55_dialog_content = "이 창고 주인, 씀씀이가 꽤 호탕하네.",
  ui_story_5070_50700401_56_dialog_content = "이렇게 많은 기관을 모아서 대체 뭘 하려는 걸까?",
  ui_story_5070_50700401_57_dialog_content = "PlayerName, 하나만 더 도와줄 수 있을까?",
  ui_story_5070_50700401_58_dialog_content = "상자를 모두 열고, 표식이 남아 있는 기관수가 있는지 조사하고 싶어.",
  ui_story_5070_50700401_59_dialog_content = "아, 그러고 보니 아까 처치한 불게도 선극 씨는 다 조사했었지?",
  ui_story_5070_50700401_60_dialog_content = "근데... 이 두 창고에 있는 기관수엔 아무 표시도 없는 것 같아.",
  ui_story_5070_50700401_61_dialog_content = "업나라는 기관을 엄정하게 관리하고 있어. 설계도나 유통 경로도 포함해서 말이야.",
  ui_story_5070_50700401_62_dialog_content = "공방에서 양산된 것이든, 기교사 개인이 만든 것이든...",
  ui_story_5070_50700401_63_dialog_content = "모든 기관은 조립을 마친 다음에 반드시 그 위에 고유의 표식을 남겨야 해.",
  ui_story_5070_50700401_64_dialog_content = "뭔가 문제가 생겼을 때 책임 소재를 명확히 할 수 있도록 말이야.",
  ui_story_5070_50700401_65_dialog_content = "근데 이 기관들은 표식이 없어... 그럼 단서가 끊긴 거 아냐?",
  ui_story_5070_50700401_66_dialog_content = "아니.",
  ui_story_5070_50700401_67_dialog_content = "적어도 업나라 공방에서 만들어진 건 아니라는 뜻이야.",
  ui_story_5070_50700401_68_dialog_content = "부품 상태로 밀수돼서 이쪽에서 조립됐을 가능성이 커.",
  ui_story_5070_50700401_69_dialog_content = "게다가 여긴 다른 것들도 있어.",
  ui_story_5070_50700401_70_dialog_content = "다른 화물인가?",
  ui_story_5070_50700401_71_dialog_content = "어라? 잠깐만... 이 도장... 린 가문 상회 거 아냐?",
  ui_story_5070_50700401_72_dialog_content = "맞아.",
  ui_story_5070_50700401_73_dialog_content = "열흘 전쯤 신풍호가 입항했을 때 하선한 승객들 사이에서 비밀스러운 소문을 들었어.",
  ui_story_5070_50700401_74_dialog_content = "용주의 린 가문 본가가 밀수 사건에 연루되어, 가주가 시박사로 연행되었다는 내용이었어...\n시박사는 용주의 해상 무역을 관장하는 관청이야.",
  ui_story_5070_50700401_75_dialog_content = "그래서 말인데, 부탁할 일이 하나 더 있어.",
  ui_story_5070_50700401_76_dialog_content = "나 대신 목 선장한테 가서...",
  ui_story_5070_50700401_77_dialog_content = "린 가문이 정말 밀수에 관여했는지 확인해 줄 수 있을까?",
  ui_story_5070_50700401_78_dialog_content = "(불게한테 습격을 당하고, 계속 창고를 뒤지느라 정신이 하나도 없었어.)",
  ui_story_5070_50700401_79_dialog_content = "(신풍호의 축하 기념식은 벌써 끝났으려나...)",
  ui_story_5070_50700401_80_dialog_content = "(...어라? 신풍호에 무슨 일이 있는 건가?)",
  ui_story_5070_50700401_81_dialog_content = "텔마 공, 이번 교류는 우리 모두에게 이로운 일임은 공도 알고 있으리라 생각하네.",
  ui_story_5070_50700401_82_dialog_content = "물론 알고 있지요. 제 지능을 의심하실 필요는 없습니다.",
  ui_story_5070_50700401_83_dialog_content = "하지만 용주가 아무리 좋은 곳이고, 사명이 얼마나 중대하든,\n무사히 도착할 수 없다면 무슨 의미가 있겠습니까?",
  ui_story_5070_50700401_84_dialog_content = "대책에 만전을 기하고, 제위의 안전을 지키기 위해 모든 힘을 다하겠네.",
  ui_story_5070_50700401_85_dialog_content = "영광스러운 백야성의 사절로서 전 진심으로 당신을 믿고 싶습니다.",
  ui_story_5070_50700401_86_dialog_content = "하지만... 지금 같은 상황에서는 재고해 볼 수밖에 없을 것 같군요.",
  ui_story_5070_50700401_87_dialog_content = "텔마 공...",
  ui_story_5070_50700401_88_dialog_content = "(이 사람... 단당 씨가 중요하다고 했던 백야성 사절 아냐?\n왜 갑자기 마음이 바뀐 거지?)",
  ui_story_5070_50700401_89_dialog_content = "(아직 알아보지 않은 건물은 이 약방뿐이야.)",
  ui_story_5070_50700401_90_dialog_content = "(이 느낌... 안에 화능술의 대가가 있어.)",
  ui_story_5070_50700401_91_dialog_content = "(대체 얼마나 대단한 사람인가 어디 한번 보실까.)",
  ui_story_5070_50700401_92_dialog_content = "<size=45>똑똑똑.</size>",
  ui_story_5070_50700401_93_dialog_content = "누구세요?",
  ui_story_5070_50700401_94_dialog_content = "실례합니다. 말씀 좀 여쭙겠습니다.",
  ui_story_5070_50700401_95_dialog_content = "혹시 근처에 있는 저 창고의 주인이 누구인지 아십니까?",
  ui_story_5070_50700401_96_dialog_content = "그리고 혹시 린 가문에 대해 아시는지...",
  ui_story_5070_50700401_97_dialog_content = "......",
  ui_story_5070_50700401_98_dialog_content = "(문이 열렸어? 천기...)",
  ui_story_5070_50700401_99_dialog_content = "......",
  ui_story_5070_50700401_100_dialog_content = "?",
  ui_story_5070_50700401_101_dialog_content = "어? 웬 꼬맹이가 나왔어? 이 집 어른은?",
  ui_story_5070_50700401_102_dialog_content = "누가 꼬맹이야?!",
  ui_story_5070_50700401_103_dialog_content = "당연히...",
  ui_story_5070_50700401_104_dialog_content = "<color=#e8d9bb>챙──!</color>",
  ui_story_5070_50700401_105_dialog_content = "빠르군.",
  ui_story_5070_50700401_106_dialog_content = "역시 오늘 운세를 보고 나올 걸 그랬어. 갑자기 손님을 공격하는 가게라니.",
  ui_story_5070_50700401_107_dialog_content = "<size=45>크오오──</size>",
  ui_story_5070_50700401_108_dialog_content = "호오? 이런 대접은 또 예상 밖인데?",
  ui_story_5070_50700402_1_dialog_content = "이 녀석들 정말 끈질기네!",
  ui_story_5070_50700402_2_dialog_content = "암귀를 다 쓰러트리고 나니까 이번엔 또 이상한 손님이 오질 않나...",
  ui_story_5070_50700402_3_dialog_content = "어라? 종서 형님, 왜 안 싸워요?",
  ui_story_5070_50700402_4_dialog_content = "천기의 우산, 구리잠자리, 정교한 기관들.",
  ui_story_5070_50700402_5_dialog_content = "소저는... 선기경인가?",
  ui_story_5070_50700402_6_dialog_content = "아는 사람이에요?",
  ui_story_5070_50700402_7_dialog_content = "만난 적은 없으나, 소문은 들었다.",
  ui_story_5070_50700402_8_dialog_content = "업나라 기관술의 거대 유파, 건운종의 천재 제자.",
  ui_story_5070_50700402_9_dialog_content = "열다섯의 나이에 진짜와 분간이 어려울 만큼 정교한 동인형을 만들어 전국에 명성을 떨쳤지.",
  ui_story_5070_50700402_10_dialog_content = "그 후 업왕의 휘하로 들어가 뛰어난 지모로 계책을 바쳤다.",
  ui_story_5070_50700402_11_dialog_content = "업나라는 저명한 기관의 이름으로 요인의 칭호를 정하는 풍습이 있다 들었소.\n소저가 「선기」라 불린 것은, 그만큼 세인들이 소저의 재주를 인정한 것이겠지.",
  ui_story_5070_50700402_12_dialog_content = "그렇게 대단한 사람도 아닌걸요. 조정 일은 진작에 그만뒀고,\n지금은 그냥 평범한 기교사예요.",
  ui_story_5070_50700402_13_dialog_content = "그것보다... 붉은 머리카락에 뛰어난 검술, 게다가 절 알고 계신 걸 보면...",
  ui_story_5070_50700402_14_dialog_content = "린 가문의 큰손님이자 제나라 상회에서 누구나 공경하는 종 공 아니신지요.",
  ui_story_5070_50700402_15_dialog_content = "벗들이 배려하여 허명으로 추켜세워 주었을 뿐이오.",
  ui_story_5070_50700402_16_dialog_content = "리청.",
  ui_story_5070_50700402_17_dialog_content = "이 소저는 적이 아니다.",
  ui_story_5070_50700402_18_dialog_content = "그건 아직 모르는 일이죠.",
  ui_story_5070_50700402_19_dialog_content = "야! 그쪽 너무 무례한 거 아냐?",
  ui_story_5070_50700402_20_dialog_content = "어른들 얘기하시는데 꼬맹이는 끼어들면 안 되지.",
  ui_story_5070_50700402_21_dialog_content = "내가 꼬맹이 아니라고 했지?!",
  ui_story_5070_50700402_22_dialog_content = "반년 전, 제나라에서 어느 밀수품을 추적한 적이 있었습니다.",
  ui_story_5070_50700402_23_dialog_content = "그 시기에 출항했던 배는 린 가문의 상선뿐이었죠.",
  ui_story_5070_50700402_24_dialog_content = "린 가문 상회도 결백을 증명할 증거를 제시하지 못했습니다.",
  ui_story_5070_50700402_25_dialog_content = "뭐? 그런 우연을 가지고 죄를 뒤집어씌우겠다는 거야?",
  ui_story_5070_50700402_26_dialog_content = "그 말이 맞아.",
  ui_story_5070_50700402_27_dialog_content = "비록 혐의는 린 가문에게만 있었지만, 여전히 많은 사람들이 그 사실에 의문을 품고 있어.",
  ui_story_5070_50700402_28_dialog_content = "근데 내가 방금 근처의 창고를 조사해 봤더니...",
  ui_story_5070_50700402_29_dialog_content = "마찬가지로 밀수해 들여온 걸로 보이는 업나라의 기관수 부품이 있었어.",
  ui_story_5070_50700402_30_dialog_content = "그 안에는 린 가문 상회의 표식이 찍힌 화물도 있었고.",
  ui_story_5070_50700402_31_dialog_content = "종 공께서는 린 가문의 큰손님이시니, 이 일을 모르시진 않으리라 생각합니다만.",
  ui_story_5070_50700402_32_dialog_content = "해명해 주실 수 있겠습니까?",
  ui_story_5070_50700402_33_dialog_content = "......",
  ui_story_5070_50700402_34_dialog_content = "린 가문의 상선은 확실히 밀수품을 실은 적이 있소.",
  ui_story_5070_50700402_35_dialog_content = "(이 텔마라는 사람, 정말 고집이 세네... 무슨 말을 해도 생각해 보겠다고만 하잖아.)",
  ui_story_5070_50700402_36_dialog_content = "(이러다간 단당 씨 임무가 어떻게 될지 모르겠는데...)",
  ui_story_5070_50700402_37_dialog_content = "...알겠네.",
  ui_story_5070_50700402_38_dialog_content = "나는 공의 뜻을 존중하네.",
  ui_story_5070_50700402_39_dialog_content = "휴... 감사합니다.",
  ui_story_5070_50700402_40_dialog_content = "당신처럼 아름답고 고귀하신 분이라면 분명히 제 입장도 이해해 주실 거라 생각했습니다.",
  ui_story_5070_50700402_41_dialog_content = "그렇다면 텔마 공도 마찬가지로 나의 입장을 이해해 주었으면 하네.",
  ui_story_5070_50700402_42_dialog_content = "아?",
  ui_story_5070_50700402_43_dialog_content = "PlayerName 공자.",
  ui_story_5070_50700402_44_dialog_content = "공자는 텔마 공 대신 아스트라 대륙의 사절로서 나와 함께 용주로 갈 의향이 있느냐.",
  ui_story_5070_50700402_45_dialog_content = "...제가요?!",
  ui_story_5070_50700501_1_dialog_content = "아, 안 돼요! 제가 어떻게 사절이 될 수 있겠어요?",
  ui_story_5070_50700501_2_dialog_content = "어찌 안 된다는 게냐.",
  ui_story_5070_50700501_3_dialog_content = "전 일루미나 연방이나 백야성처럼 한 세력을 대표하는 사람도 아닌걸요.",
  ui_story_5070_50700501_4_dialog_content = "어느 세력에도 속하지 않는 중립적인 자야말로 아스트라 대륙을 대표하기에\n적합한 자가 아니더냐.",
  ui_story_5070_50700501_5_dialog_content = "하물며 PlayerName 공자는 인맥도 넓고 경험도 풍부하지.",
  ui_story_5070_50700501_6_dialog_content = "대륙 각지의 상황이나 암귀에 맞서는 책략에도 해박하고 말이야.",
  ui_story_5070_50700501_7_dialog_content = "이는 두 대륙의 가교를 만들고자 하는 이번 사명에도 마침 부합하는 바다.",
  ui_story_5070_50700501_8_dialog_content = "아니, 그치만...",
  ui_story_5070_50700501_9_dialog_content = "저는 찬성합니다!",
  ui_story_5070_50700501_10_dialog_content = "PlayerName 씨는 아스트라에서도 명성이 높아서,\n이미 전부터 그 공적에 대해 들은 적 있습니다.",
  ui_story_5070_50700501_11_dialog_content = "따라서 백야성을 대표하는 사절로서, 용주로 가는 중임을 당신에게 위임하고자 합니다!",
  ui_story_5070_50700501_12_dialog_content = "잠깐만요... 생각할 시간을 좀 주세요.",
  ui_story_5070_50700501_13_dialog_content = "(백야성이라... 카렌은 줄곧 대륙 간의 교류를 지지해 왔어.\n만약 이번 일이 틀어진다면 카렌도 실망할 거야.)",
  ui_story_5070_50700501_14_dialog_content = "(단당 씨 일행도 아스트라에 도착한 뒤로 줄곧 사방을 다니면서 고생했고...)",
  ui_story_5070_50700501_15_dialog_content = "(이번 교류에는 많은 사람들의 기대가 달려 있어... 게다가 두 대륙의 미래가 달린 일이야.\n만약 지금 다른 마땅한 사람이 없다면...)",
  ui_story_5070_50700501_16_dialog_content = "...노력해 볼게요.",
  ui_story_5070_50700501_17_dialog_content = "PlayerName 공자... 참으로 고마운지고!",
  ui_story_5070_50700501_18_dialog_content = "결정한 거야?",
  ui_story_5070_50700501_19_dialog_content = "선장님도 들었어요?",
  ui_story_5070_50700501_20_dialog_content = "월백이라고 불러 줘.",
  ui_story_5070_50700501_21_dialog_content = "결심이 섰다면, 나도 신풍호의 선장으로서...",
  ui_story_5070_50700501_22_dialog_content = "PlayerName 당신이 아스트라의 전권 사절로서 신풍호에 승선하는 걸 승인할게.",
  ui_story_5070_50700501_23_dialog_content = "대신 항해는 위험하니까, 마음의 준비를 해 둬.",
  ui_story_5070_50700501_24_dialog_content = "네, 알겠어요.",
  ui_story_5070_50700501_25_dialog_content = "참, 선장... 아니, 월백 씨, 잠깐 시간 좀 괜찮을까요?",
  ui_story_5070_50700501_26_dialog_content = "음... 어느 친구가 린 가문에 대해 좀 물어봐 달라고 부탁했거든요.",
  ui_story_5070_50700501_27_dialog_content = "린 가문의 상선은 확실히 밀수품을 실은 적이 있소.",
  ui_story_5070_50700501_28_dialog_content = "종서 형님! 지금 그게 무슨 말씀이세요?",
  ui_story_5070_50700501_29_dialog_content = "저 사람 뭐 어디서 이상한 소문을 듣고 다짜고짜 따지는 건진 모르겠지만,\n형님도 상대 안 하고 그냥 대충 둘러대서 쫓아내면 되잖아요!",
  ui_story_5070_50700501_30_dialog_content = "다 듣고 있거든~",
  ui_story_5070_50700501_31_dialog_content = "하지만... 갑자기 그런 충격적인 발언이라니,\n설마 종 공께선 저와 계속 겨뤄보고 싶으신 건 아니겠죠?",
  ui_story_5070_50700501_32_dialog_content = "그런 뜻은 없소.",
  ui_story_5070_50700501_33_dialog_content = "다만 선기경이 고작 그 한마디에 마음이 흔들렸다면...",
  ui_story_5070_50700501_34_dialog_content = "이 종 모가 전할 진상을 들어줄 뜻은 없는 것으로 보이는구려.",
  ui_story_5070_50700501_35_dialog_content = "네?",
  ui_story_5070_50700501_36_dialog_content = "알아들을 수 있으면 듣고, 못 알아듣거나 듣기 싫으면 듣지 마라... 뭐 그런 뜻인가요?",
  ui_story_5070_50700501_37_dialog_content = "그런 게 아니오.",
  ui_story_5070_50700501_38_dialog_content = "그저 종 모가 아직 몸이 성치 않은 탓에, 이야기를 되도록 짧게 끝내고 싶을 뿐이오.",
  ui_story_5070_50700501_39_dialog_content = "좋아요, 그럼 짧게 하세요.",
  ui_story_5070_50700501_40_dialog_content = "종 공께서 그렇게까지 솔직하게 말씀해 주시겠다는데,\n짧은 말도 안 듣겠다면 제가 너무 편협하지 않겠어요?",
  ui_story_5070_50700501_41_dialog_content = "뭐야, 그래도 말이 통하는 사람이었잖아?",
  ui_story_5070_50700501_42_dialog_content = "그거야 어른이니까 그렇지, 꼬맹아.",
  ui_story_5070_50700501_43_dialog_content = "내가 꼬맹이 아니라고 했잖아! 왜 그 말은 안 통하는 건데?!",
  ui_story_5070_50700501_44_dialog_content = "그래서... 반년 전 바다에서 린 가문 상선에 대체 무슨 일이 있었던 거죠?",
  ui_story_5070_50700501_45_dialog_content = "해적이오.",
  ui_story_5070_50700501_46_dialog_content = "본디 린 가문의 배는 풍습에 따라 계절마다 제나라의 항구에서 출항해 왔소.",
  ui_story_5070_50700501_47_dialog_content = "허나 아스트라의 근해에 들어설 무렵, 선원들이 화물창에서 기록에 없는 화물을 발견했소.",
  ui_story_5070_50700501_48_dialog_content = "그와 함께 승객 속에 해적이 숨어들어 있다는 것도 알게 되었지.",
  ui_story_5070_50700501_49_dialog_content = "린 가문의 배로 밀수품을 옮기려고 했던 건가요?",
  ui_story_5070_50700501_50_dialog_content = "그렇소.",
  ui_story_5070_50700501_51_dialog_content = "그러나 그 속셈이 중도에 드러나자, 해적들은 폭거에 나서 사람들을 해치고 상선을 빼앗았소.",
  ui_story_5070_50700501_52_dialog_content = "끝내 살아남은 것은 종 모와, 배에 의원으로 승선한 리청뿐이었소.",
  ui_story_5070_50700501_53_dialog_content = "종서 형님은 그때 물에 빠져 중상을 입으셨고, 목숨까지 위태로웠다고.",
  ui_story_5070_50700501_54_dialog_content = "목숨은 겨우 건졌지만, 다리는 보전할 수가 없어서... 지금처럼 돼버린 거야...",
  ui_story_5070_50700501_55_dialog_content = "리청 아우가 자책할 일이 아니다. 목숨을 부지한 것만으로도 내 감사할 일이지.",
  ui_story_5070_50700501_56_dialog_content = "진짜 그렇게 생각하시는 거면 잘 좀 쉬시라구요.",
  ui_story_5070_50700501_57_dialog_content = "불청객이 올 때마다 바로 뛰쳐나가시니까...",
  ui_story_5070_50700501_58_dialog_content = "불청객?",
  ui_story_5070_50700501_59_dialog_content = "끼이익──!",
  ui_story_5070_50700501_60_dialog_content = "으아아! 또 왔다!",
  ui_story_5070_50700501_61_dialog_content = "조금만 방심하면 이렇게 튀어나온다니까!\n밥 먹을 때도, 잘 때도 좀 편하게 있을 수가 없어!",
  ui_story_5070_50700501_62_dialog_content = "「천기...」",
  ui_story_5070_50700501_63_dialog_content = "「단멸의 불길!」",
  ui_story_5070_50700501_64_dialog_content = "......",
  ui_story_5070_50700501_65_dialog_content = "종서 형님! 제가 지금 막 말했잖아요! 그러니까 형님 몸이 안 낫는 거라구요!",
  ui_story_5070_50700501_66_dialog_content = "내 남은 여생은 대수롭지 않은 일이다.",
  ui_story_5070_50700501_67_dialog_content = "허나 린 가문의 가주는...",
  ui_story_5070_50700501_68_dialog_content = "내 일찍이 그와 약조하였거늘, 어찌 가주가 누명을 쓰고 옥살이를 하게 둘 수 있겠는가.",
  ui_story_5070_50700501_69_dialog_content = "그러니 여기서 쓰러질 수는 없다.",
  ui_story_5070_50700501_70_dialog_content = "어떻게든 용주로 돌아가서 린 가문의 누명을 씻어 주어야지.",
  ui_story_5070_50700501_71_dialog_content = "그래서 제가 왔을 때도 그렇게 경계하셨던 거군요.",
  ui_story_5070_50700501_72_dialog_content = "두 분은 계속 저 기관수들과 싸우고 계셨나요?",
  ui_story_5070_50700501_73_dialog_content = "바다를 건너온 용병들도 상대해야 했소.",
  ui_story_5070_50700501_74_dialog_content = "어쩌면 다른 세력이 그 해적들의 배후에 있을지도 모르오.",
  ui_story_5070_50700501_75_dialog_content = "하여 줄곧 자객을 보내 우리 두 사람을 이 객지에서 진상과 함께 묻어버리려는 것이겠지.",
  ui_story_5070_50700501_76_dialog_content = "그리하여 린 가문이 영원히 오명을 벗을 수 없게 하려는 것이오.",
  ui_story_5070_50700501_77_dialog_content = "종서 형님은 이럴 때까지 린 가문 생각뿐이시네요...\n정말 좋다고 해야 하나 나쁘다고 해야 하나 모르겠다니까요.",
  ui_story_5070_50700501_78_dialog_content = "끼이익──!",
  ui_story_5070_50700501_79_dialog_content = "으아앗! 또 왔어!",
  ui_story_5070_50700501_80_dialog_content = "조금 전에는 선기경을 알아보지 못하고 실례를 범했소.",
  ui_story_5070_50700501_81_dialog_content = "허나 지금은 물러가시오. 종 모가 초래한 화에 휘말리지 않도록 말이오.",
  ui_story_5070_50700501_82_dialog_content = "휘말린다는 말은 조금 맞지 않네요.",
  ui_story_5070_50700501_83_dialog_content = "그렇게 말씀하시면 제가 화근이 돼버리는걸요.",
  ui_story_5070_50700501_84_dialog_content = "제가 이 기관수들을 설계한 건...",
  ui_story_5070_50700501_85_dialog_content = "주제도 모르는 모방꾼 놈들이 사람을 해치는 기관을 만들라고 한 건 아니거든요!",
  ui_story_5070_50700501_86_dialog_content = "마침 단서가 끊겨서 곤란했던 참인데, 저쪽에서 알아서 와줄 줄은 몰랐네요!",
  ui_story_5070_50700501_87_dialog_content = "그러니 오히려 제가 감사드릴 일인 거죠.",
  ui_story_5070_50700501_88_dialog_content = "아무래도 종 공과 전 공동의 적을 가진 모양이네요.",
  ui_story_5070_50700501_89_dialog_content = "...한참 용썼는데 결국 같은 편이었잖아!",
  ui_story_5070_50700501_90_dialog_content = "괜히 서로 경계한다고 힘만 뺐네. 적이 보고 있었으면 얼마나 웃었겠냐구.",
  ui_story_5070_50700501_91_dialog_content = "그렇게 화낼 거 없어, 꼬맹아. 이 녀석들 쓰러트리고 나면 내가 재미있는 장난감 줄게.",
  ui_story_5070_50700501_92_dialog_content = "털실공 어때?",
  ui_story_5070_50700501_93_dialog_content = "내친김에 종 공 이륜거도 수리해 드릴까요? 새로운 기능을 추가하는 건 어때요?",
  ui_story_5070_50700501_94_dialog_content = "호의는 고맙네.",
  ui_story_5070_50700501_95_dialog_content = "허나 이륜거는 그저 걸음을 대신할 도구일 뿐, 다른 불편한 물건을 더할 필요는 없소.",
  ui_story_5070_50700501_96_dialog_content = "아하하, 종 공께선 기교사도 아니신데 기관술의 진정한 의미를 알고 계시는군요.",
  ui_story_5070_50700501_97_dialog_content = "쥐새끼처럼 숨어서 남의 설계나 모방하는 녀석들보다는 100배는 더 훌륭하십니다.",
  ui_story_5070_50700502_1_dialog_content = "...이게 지금 린 가문의 상황이야.",
  ui_story_5070_50700502_2_dialog_content = "반년 전 밀수 파동으로 린 가문 상회의 기세가 크게 상했다고는 들었으나,\n내 이러한 사정이 있었음은 처음 들었구나.",
  ui_story_5070_50700502_3_dialog_content = "월백의 말대로라면 이번 판결은 확실히 지나친 독단이다.",
  ui_story_5070_50700502_4_dialog_content = "린 가문이 밀수를 했다는 증거는 없으나, 정황은 모두 린 가문을 가리키고 있었다.",
  ui_story_5070_50700502_5_dialog_content = "또한 린 가문은 결백을 증명할 방법도 없었으니, 죄를 뒤집어쓸 수밖에 없었다는 말인가.",
  ui_story_5070_50700502_6_dialog_content = "혼천의가 없는 상황에서도 위험을 무릅쓰고 출항한 이유가 있었구나.",
  ui_story_5070_50700502_7_dialog_content = "그렇게 해서라도 항로를 유지하고 상회를 부흥시키겠다는 생각이겠지.",
  ui_story_5070_50700502_8_dialog_content = "휴, 이 신풍호의 승객들은 실로 저마다의 어려움이 있는지고.",
  ui_story_5070_50700502_9_dialog_content = "그래서 어떻게든 예정대로 신풍호를 귀항시키고 싶었던 거군요.",
  ui_story_5070_50700502_10_dialog_content = "PlayerName 공자.",
  ui_story_5070_50700502_11_dialog_content = "...왜요? 단당 씨, 갑자기 그런 진지한 표정으로...",
  ui_story_5070_50700502_12_dialog_content = "바다는 헤아릴 수 없는 곳이다.\n자고로 먼 여정을 떠나 평온무사하게 돌아온 사자는 열에 하나도 채 되지 않았지.",
  ui_story_5070_50700502_13_dialog_content = "지금은 항로도 순탄치 않은 데다가, 습격까지 당해 앞길을 알 수 없는 상황이다.",
  ui_story_5070_50700502_14_dialog_content = "그럼에도 신풍호를 타려는 자들 앞에는 미증유의 위기가 기다리고 있을 게다.",
  ui_story_5070_50700502_15_dialog_content = "월백은 린 가문 상회를 다시 일으켜야 하고, 나 역시 무거운 책임을 지고 있다.",
  ui_story_5070_50700502_16_dialog_content = "하여 우리는 저마다 위험을 무릅써야 할 이유가 있고,\n그 결과를 받아들일 각오도 되어 있다.",
  ui_story_5070_50700502_17_dialog_content = "허나 PlayerName 공자 그대는 다르다.",
  ui_story_5070_50700502_18_dialog_content = "...작화군주로서 말하자면, 그대를 끌어들인 것은 당시 내가\n생각해 낼 수 있는 유일한 방법이었다.",
  ui_story_5070_50700502_19_dialog_content = "허나 PlayerName 공자의 친우 단당으로서 말하자면...\n나는 그대의 안위를 염려하고 있다...",
  ui_story_5070_50700502_20_dialog_content = "그러니 여기서 그만두겠다고 하여도 나는 이해할 수 있다.",
  ui_story_5070_50700502_21_dialog_content = "...전 또 무슨 말을 하려는 건가 했네요.",
  ui_story_5070_50700502_22_dialog_content = "응?",
  ui_story_5070_50700502_23_dialog_content = "단당 씨는 자기가 절 끌어들였다고 하지만...",
  ui_story_5070_50700502_24_dialog_content = "아스트라의 사절이든, 아이테르로서든, PlayerName 개인으로서든...",
  ui_story_5070_50700502_25_dialog_content = "이 사명을 받은 건 모두 제가 깊이 생각해서 내린 결정이에요.",
  ui_story_5070_50700502_26_dialog_content = "그리고 저도 친구로서 단당 씨한테 힘이 되고 싶어요.",
  ui_story_5070_50700502_27_dialog_content = "PlayerName 공자... 하면 내 전력을 다해 그대의 평안을 지키마.",
  ui_story_5070_50700502_28_dialog_content = "부디 더는 곡절이 없었으면 좋으련만...",
  ui_story_5070_50700502_29_dialog_content = "아이참, 아직 출항도 안 했는데 왜 다들 푹 쳐져서 울상인 걸까?",
  ui_story_5070_50700502_30_dialog_content = "......",
  ui_story_5070_50700502_31_dialog_content = "내가 백전연마의 용사와 만병을 고치는 명의를 데려왔으니까, 만일의 상황이 벌어져도 괜찮아.",
  ui_story_5070_50700502_32_dialog_content = "정 안 되면 나도 있잖아!",
  ui_story_5070_50700502_33_dialog_content = "비록 이제 더는 업나라의 막료가 아니지만, 난 단당 님의 명이라면\n칼산과 불바다도 뛰어들 수 있다고.",
  ui_story_5070_50700502_34_dialog_content = "전하, 선극 님께서 돌아오셨습니다!",
  ui_story_5070_50700502_35_dialog_content = "이 말소리만 들어도 알겠구나.",
  ui_story_5070_50700502_36_dialog_content = "선기경은 늘 얼토당토않는 말만 하니 말이다.",
  ui_story_5070_50700502_37_dialog_content = "내 이번엔 정말로 칼산이나 불바다로 가달라고 해야 쓰겠구나.",
  ui_story_5070_50700502_38_dialog_content = "아하하, 자, 그럼 농담은 이 정도로 하죠!",
  ui_story_5070_50700502_39_dialog_content = "방금 신풍호가 습격을 당했다고 들었어요. 가서 선체를 좀 더 살펴봐야겠어요.",
  ui_story_5070_50700502_40_dialog_content = "설마 불게의 습격에 대비해야 할 날이 올 줄은 몰랐네요.",
  ui_story_5070_50700502_41_dialog_content = "동력 공급과 항로 안내 기능도 개조나 강화를 해야할 것 같아요.",
  ui_story_5070_50700502_42_dialog_content = "아무튼 걱정 마세요. 안전하게 항해할 수 있도록 제가 최선을 다해 배를 고칠 테니까요.",
  ui_story_5070_50700601_1_dialog_content = "「바이스, 카렌에게.」",
  ui_story_5070_50700601_2_dialog_content = "「답장이 늦어서 미안해. 눈 깜짝할 사이에 출항하는 날이 되었지 뭐야.」",
  ui_story_5070_50700601_3_dialog_content = "「그동안 배에서 마지막 준비를 하고 있었거든. 다들 눈코 뜰 새 없이 바빴어.」",
  ui_story_5070_50700601_4_dialog_content = "이 씨는 사람들 데리고 가서 선체의 주요 부위에 방화 도료를 발라 줘.",
  ui_story_5070_50700601_5_dialog_content = "그럼 불게의 습격뿐만 아니라, 화로에서 사고가 났을 때도 대응할 수 있어.",
  ui_story_5070_50700601_6_dialog_content = "난 가서 수밀 성능을 검사하고 올게.",
  ui_story_5070_50700601_7_dialog_content = "그리고 누구 선장 어딨는지 아는 사람?\n아스트라의 동력 저장 장치를 예비로 좀 사뒀으면 좋겠는데.",
  ui_story_5070_50700601_8_dialog_content = "바다 위에서는 어떤 일이라도 일어날 수 있어. 혹시 모르니까 여분의 자원이 있어야 해.",
  ui_story_5070_50700601_9_dialog_content = "종 대인.",
  ui_story_5070_50700601_10_dialog_content = "며칠간 업무로 바빠서 인사가 늦었습니다...",
  ui_story_5070_50700601_11_dialog_content = "밀수 사건의 진상을 말씀해 주셔서 감사합니다.\n린 가문도 이제 곧 누명을 벗을 수 있을 거예요.",
  ui_story_5070_50700601_12_dialog_content = "종 대인께서 무사히 돌아오신 것을 가주께서 아시면 분명히 기운을 얻으실 겁니다.\n그럼 어떤 어려움도 극복할 수 있겠죠.",
  ui_story_5070_50700601_13_dialog_content = "모두 종 모가 마땅히 해야 할 일이었고, 가주를 지키지 못한 것은 종 모의 과실이오.",
  ui_story_5070_50700601_14_dialog_content = "게다가 해적들이 다시 습격해 올지도 모르오.",
  ui_story_5070_50700601_15_dialog_content = "반년 전 사고 때 그들의 움직임은 대부분 파악했소.",
  ui_story_5070_50700601_16_dialog_content = "이를 바탕으로 미리 대응책을 마련해 두는 것이 좋겠소.",
  ui_story_5070_50700601_17_dialog_content = "단향, 분초, 박하, 갈근...",
  ui_story_5070_50700601_18_dialog_content = "사장님, 이 약재들, 있는 만큼 다 줘!",
  ui_story_5070_50700601_19_dialog_content = "어이쿠, 우리 도련님 통이 크시군그래.",
  ui_story_5070_50700601_20_dialog_content = "휴, 배에 타고 있는 사람들을 전부 나 혼자 챙겨야 하거든.",
  ui_story_5070_50700601_21_dialog_content = "멀미라든지 감기라든지 자주 쓰는 약은 많을수록 안심이니까.",
  ui_story_5070_50700601_22_dialog_content = "죄다 뭘 했다 하면 죽어라 하는 사람들뿐이니까, 나라도 잘 준비해 놔야지!",
  ui_story_5070_50700601_23_dialog_content = "약은 다 샀고... 남은 건 음식인가? 바다에서도 건강을 챙겨줄 식재료를 좀 사야겠어.",
  ui_story_5070_50700601_24_dialog_content = "구야, 작별 서신은 다 썼느냐.",
  ui_story_5070_50700601_25_dialog_content = "예, 제가 인사해야 할 사람은 그리 많지 않습니다.",
  ui_story_5070_50700601_26_dialog_content = "오히려 전하께서는 서신을 많이 쓰셨군요.",
  ui_story_5070_50700601_27_dialog_content = "내 이번 여정에서 많은 벗을 사귀지 않았느냐.\n아스트라의 요인들과도 적지 않은 인연이 있었고 말이야.",
  ui_story_5070_50700601_28_dialog_content = "앞으로의 교류를 위해서는 이 인연을 잘 이어가야겠지.",
  ui_story_5070_50700601_29_dialog_content = "아, 쌍사성의 상회 연맹에도 서신을 남겨야겠구나.",
  ui_story_5070_50700601_30_dialog_content = "쌍사성에도 해적과 손을 잡은 도적들이 있는 이상, 반드시 색출하여 벌해야만 한다.",
  ui_story_5070_50700601_31_dialog_content = "「나도 물건 사러 움브라톤을 몇 번이나 왕복하고, 아스트라 대륙의 물자를 조달했어.」",
  ui_story_5070_50700601_32_dialog_content = "「이러다 보니까 아스트라 대륙의 사절이라는 역할도 서서히 실감이 나더라고.」",
  ui_story_5070_50700601_33_dialog_content = "「이 편지를 부치고 나면 신풍호는 곧 출항할 거야.」",
  ui_story_5070_50700601_34_dialog_content = "「부디 이번 여정이 모두의 노력을 저버리지 않고, 순조롭게 끝났으면 좋겠어.」",
  ui_story_5070_50700601_35_dialog_content = "「나도 용주에서 겪게 될 재미있는 이야기를 돌아가서 너희한테 잔뜩 들려줄 테니까.」",
  ui_story_5070_50700601_36_dialog_content = "오, PlayerName 공 아니십니까.",
  ui_story_5070_50700601_37_dialog_content = "어? 저번에 그 점쟁이 씨?",
  ui_story_5070_50700601_38_dialog_content = "잠깐, 소생이 점부터 쳐 보도록 하죠... 어디 보자, 보낼 서신이 있으신 모양이로군요.",
  ui_story_5070_50700601_39_dialog_content = "......",
  ui_story_5070_50700601_40_dialog_content = "바로 뒤에 쿠리어 길드 건물이 있고, 지금 막 저기서 나왔잖아요...",
  ui_story_5070_50700601_41_dialog_content = "하하하, 농담입니다.",
  ui_story_5070_50700601_42_dialog_content = "소생은 이천간이라 합니다. 공과 마찬가지로 신풍호의 승객이지요.",
  ui_story_5070_50700601_43_dialog_content = "마침 행선지도 같은데, 함께 배로 돌아가시겠습니까?",
  ui_story_5070_50700601_44_dialog_content = "그래요, 그나저나 천간 씨도 편지 부치러 온 건가요?",
  ui_story_5070_50700601_45_dialog_content = "휴, 말도 마십시오.",
  ui_story_5070_50700601_46_dialog_content = "출항 전에 아스트라의 진수성찬을 마지막으로 한 번 더 먹고 싶어서 나왔는데,\n오늘은 운이 따르지 않는 모양입니다.",
  ui_story_5070_50700601_47_dialog_content = "여기서 한참을 기다려 봐도 인연이 닿는 귀인이 나타나질 않더군요.",
  ui_story_5070_50700601_48_dialog_content = "참으로 유감스럽습니다.",
  ui_story_5070_50700601_49_dialog_content = "귀인이랑 식사랑 무슨 상관인데요?",
  ui_story_5070_50700601_50_dialog_content = "역시 모르시는군요. 사실 소생이 겉보기엔 가난해 보이지만...",
  ui_story_5070_50700601_51_dialog_content = "사실 정말로 빈털터리입니다.",
  ui_story_5070_50700601_52_dialog_content = "...그러고도 여행을 다녀요?",
  ui_story_5070_50700601_53_dialog_content = "소생은 다른 승객들과는 다릅니다. 딱히 특별한 목적이 없지요.",
  ui_story_5070_50700601_54_dialog_content = "그저 아득히 먼 곳의 바람이 궁금하여 보러 나왔다가 곳곳을 누비며 즐거움을 찾을 뿐입니다.",
  ui_story_5070_50700601_55_dialog_content = "미지의 대륙이나, 집 문 앞의 연못이나 제겐 큰 차이도 없지요.",
  ui_story_5070_50700601_56_dialog_content = "...아, 그러시군요.",
  ui_story_5070_50700601_57_dialog_content = "(무슨 말인지 잘 모르겠지만, 왠지 무슨 깊은 뜻이 담긴 것 같네.)",
  ui_story_5070_50700601_58_dialog_content = "소생의 이야기에 꽤 이치가 있다고 생각되지 않으십니까?",
  ui_story_5070_50700601_59_dialog_content = "아니면 이참에 제대로 점을 한번 쳐 보는 건 어떠하신지요.",
  ui_story_5070_50700601_60_dialog_content = "소생의 「만류천두괘」에는 열두 동물을 뜻하는 「십이지」가 있고,\n각각 음과 양으로 나뉘어 있습니다.",
  ui_story_5070_50700601_61_dialog_content = "이것으로 하늘의 뜻을 헤아리거나, 미래를 점칠 수도 있지요.\n이번 기회를 놓치면 다음은 없습니다.",
  ui_story_5070_50700601_62_dialog_content = "동물이요? 동물로 뭘 알 수 있는데요?",
  ui_story_5070_50700601_63_dialog_content = "그건 아주 심오하고 깊은 문제입니다.",
  ui_story_5070_50700601_64_dialog_content = "자, 이렇게 하지요. 슬슬 신풍호가 저 앞에 보이니,\n가는 동안 저 배를 예시로 삼아서 이야기해 드리도록 하지요.",
  ui_story_5070_50700601_65_dialog_content = "저 배에는 쥐와 소뿐만 아니라 열두 마리의 동물이 다 있는데, 알고 계신지요.",
  ui_story_5070_50700601_66_dialog_content = "배에 쥐는 있을지도 모르지만, 소가 있을 리는 없잖아요.",
  ui_story_5070_50700601_67_dialog_content = "용주 사람들은 심상을 중요시합니다.\n모양이 비슷한 것의 이름을 따서 다른 물건에 이름을 붙이는 것이지요.",
  ui_story_5070_50700601_68_dialog_content = "자, 저기 저 돛대를 고정하는 쐐기는 「서교」라고 합니다. 즉 쥐 다리라는 뜻이지요.",
  ui_story_5070_50700601_69_dialog_content = "좌우현 위쪽의 난간은 「우책」, 소 우리입니다.",
  ui_story_5070_50700601_70_dialog_content = "선창 위 갑판은 말의 얼굴을 뜻하는 「마면」이라 부르고,\n배의 뼈대에서 가장 중요한 부분이 「용골」인 것은 공도 이제 아시겠지요.",
  ui_story_5070_50700601_71_dialog_content = "그런 호칭들이 있었을 줄은 몰랐네요.",
  ui_story_5070_50700601_72_dialog_content = "그렇습니다. 따라서 이 배처럼 소생의 점괘는 만물과 호응하여\n만사를 헤아릴 수 있는 것입니다.",
  ui_story_5070_50700601_73_dialog_content = "그럼 이번 출항의 미래도 점칠 수 있나요?",
  ui_story_5070_50700601_74_dialog_content = "그건... 솔직히 말씀드리자면 얼마 전 신풍호가 습격당했을 때도 점을 쳐 보았습니다만.",
  ui_story_5070_50700601_75_dialog_content = "결과는 음의 소와 음의 말이 나왔습니다.",
  ui_story_5070_50700601_X75_dialog_content = "죽은 소는 움직이지 않고, 나무 말은 울지 않지요.\n따라서 배는 움직이지 않을 것이라는 뜻이었습니다만...",
  ui_story_5070_50700601_76_dialog_content = "근데 신풍호는 곧 출항할 거잖아요.",
  ui_story_5070_50700601_77_dialog_content = "그렇습니다. 아무래도 그 점괘에는 제가 아직 헤아리지 못한 뜻이 더 있는 모양입니다.\n어쩌면 「마면」이나 「우책」 근처에서 뭔가 영감을 얻을 수 있을지도 모르지요.",
  ui_story_5070_50700601_78_dialog_content = "PlayerName 공자, 강호의 사기꾼이 하는 말 따위를 믿어서는 아니 된다.",
  ui_story_5070_50700601_79_dialog_content = "허어, 공주 전하, 소생은 그저 제 기술로 먹고살고 있을 뿐입니다.",
  ui_story_5070_50700601_80_dialog_content = "다른 승객들은 이미 거의 다 탔을 것이다.\n그자는 상관하지 말고 승선하거라, PlayerName 공자.",
  ui_story_5070_50700601_81_dialog_content = "...그럼 마지막에 탑승하신 승객분들의 명단을 확인해 보겠습니다.",
  ui_story_5070_50700601_82_dialog_content = "종 대인, 리청 의원, 공주 전하, 구, 그리고 PlayerName.",
  ui_story_5070_50700601_83_dialog_content = "이 씨와 손 씨, 선극 소저는 수행장인으로서 함께 용주로 갈 겁니다.",
  ui_story_5070_50700601_84_dialog_content = "이걸로 승객 전원이 승선했군요.",
  ui_story_5070_50700601_85_dialog_content = "......",
  ui_story_5070_50700601_86_dialog_content = "본래 출항 전 승객의 염려를 더하는 일은 선장으로서 삼가야 마땅한 일이겠지요.",
  ui_story_5070_50700601_87_dialog_content = "하지만 이번 항해는 특별합니다. 여러분께도 마지막으로 한 번 더 강조하겠습니다.",
  ui_story_5070_50700601_88_dialog_content = "지금 이 신풍호에는 해상에서 위치를 헤아리는 혼천의가 없습니다.",
  ui_story_5070_50700601_89_dialog_content = "배가 나아갈 방향은 모두 우리 스스로 파악해야 합니다.",
  ui_story_5070_50700601_90_dialog_content = "게다가 바다 위에서는 언제 폭풍이 일어나고 암귀가 나타날지 알 수 없습니다.\n심지어 미지의 적이 매복해 있을 가능성도 있지요...",
  ui_story_5070_50700601_91_dialog_content = "지금 우리를 기다리고 있는 위험은 지금까지의 어떤 항해보다도 크다 할 수 있습니다.",
  ui_story_5070_50700601_92_dialog_content = "여러분 중에도 여정을 포기하고 싶으신 분이 있으시다면, 지금 말씀해 주세요.",
  ui_story_5070_50700601_93_dialog_content = "(아무도 포기하질 않잖아. 역시 다들 각오한 거구나.)",
  ui_story_5070_50700601_94_dialog_content = "신풍호를 믿어주셔서 감사합니다. 그리고 선장으로서 여러분께 약속하겠습니다.\n반드시 최선을 다해 이 항해를 무사히 마칠 겁니다.",
  ui_story_5070_50700601_95_dialog_content = "자, 그럼... 신풍호, 출항!",
  ui_story_5070_50700701_1_dialog_content = "<color=#e8d9bb>첨벙... 첨벙...</color>",
  ui_story_5070_50700701_2_dialog_content = "(출항한 지 벌써 며칠이 지났다. 배로 아스트라 대륙을 떠나는 건 나도 이번이 처음이다.)",
  ui_story_5070_50700701_3_dialog_content = "(푸른 하늘, 파도, 상쾌한 바닷바람, 바다 건너편 미지에 대한 기대...\n그리고 조금의 고독감이 느껴진다.)",
  ui_story_5070_50700701_4_dialog_content = "뭘 그렇게 푹 빠져 있어? 무슨 고민이라도 있는 거야?",
  ui_story_5070_50700701_5_dialog_content = "아, 선극 씨!",
  ui_story_5070_50700701_6_dialog_content = "그냥 그런 생각이 들었거든.\n배를 타고 바다를 건너는 느낌은 콜로서스를 타는 거랑은 전혀 다른 것 같아.",
  ui_story_5070_50700701_7_dialog_content = "그래? 그럼 콜로서스는 어떤 느낌인데?",
  ui_story_5070_50700701_8_dialog_content = "당신이 먼저 그런 얘길 하니까 신기하네. 콜로서스도 넓은 의미로 보면 일종의 기관이잖아?",
  ui_story_5070_50700701_9_dialog_content = "그건 좀 너무 많이 넓은 거 아닌가...",
  ui_story_5070_50700701_10_dialog_content = "뭐, 그게 중요한 건 아니잖아.",
  ui_story_5070_50700701_11_dialog_content = "그것보다, 정말 너 혼자만으로도 신풍호보다 복잡하고 큰 그런 물건을 조종할 수 있는 거야?",
  ui_story_5070_50700701_12_dialog_content = "속도는 얼마나 나와? 연비는? 계절에 따른 변화는 어떤데?",
  ui_story_5070_50700701_13_dialog_content = "비행 기관이라면 동력원 외에도 형체에 따라 표면 유속도, 양력도 달라지잖아?",
  ui_story_5070_50700701_14_dialog_content = "저번엔 제대로 대답을 안 해 줬으니까 오늘은 대답해 줘.",
  ui_story_5070_50700701_15_dialog_content = "자, 잠깐만... 아무래도 내가 또 시작해선 안 될 대화 주제를 꺼낸 것 같은데...",
  ui_story_5070_50700701_16_dialog_content = "아하하, 만약 기밀이라면 억지로 안 물어볼게~",
  ui_story_5070_50700701_17_dialog_content = "기밀은 아니지만, 어떤 문제는 나도 잘 대답할 수가 없거든.",
  ui_story_5070_50700701_18_dialog_content = "생각해 봐. 신풍호에서는 뱃전도, 타륜도, 돛대도...",
  ui_story_5070_50700701_19_dialog_content = "선상의 모든 일을 월백 씨랑 사람들이 직접 조종하고 있어.",
  ui_story_5070_50700701_20_dialog_content = "풍향이나 풍력이 바뀔 때도 반드시 사람들이 항해 방식을 어떻게 변경할지 판단해야 해.",
  ui_story_5070_50700701_21_dialog_content = "근데 콜로서스는 그런 걸 스카이워커가 가진 자료를 토대로 스스로 결정하거든.",
  ui_story_5070_50700701_22_dialog_content = "난 그냥 중요한 순간에 말이나 선율로 인도만 해 주면 돼.",
  ui_story_5070_50700701_23_dialog_content = "단순히 조종하는 게 아니라, 합리적인 행동 수행을 위임하고, 당신은 지휘만 하는 거구나.",
  ui_story_5070_50700701_24_dialog_content = "그거 마치 신화가 그대로 재현된 것 같잖아.",
  ui_story_5070_50700701_25_dialog_content = "신화? 용주 신화 말이야?",
  ui_story_5070_50700701_26_dialog_content = "그래, 고서에 따르면 태고의 시대에 하늘을 삼키고 달을 먹는\n커다란 몸집의 「거령」이 있었다고 해.",
  ui_story_5070_50700701_27_dialog_content = "그리고 하늘의 사람이 거령을 조종해 사방을 정벌했는데, 「거령의 시종」이라고 불렸어.",
  ui_story_5070_50700701_28_dialog_content = "와... 그거 굉장하네... 스카이워커는 하늘을 삼키고 달을 먹을 순 없는걸.",
  ui_story_5070_50700701_29_dialog_content = "아무리 높이 날아도 하늘과 달은 훨씬 먼 곳에 있으니까...",
  ui_story_5070_50700701_30_dialog_content = "그거야 알 수 없지.",
  ui_story_5070_50700701_31_dialog_content = "뭐?",
  ui_story_5070_50700701_32_dialog_content = "내가 갑판에 나온 건 태양의 고도를 측정하기 위해서야.",
  ui_story_5070_50700701_33_dialog_content = "그건 비유가 아니지? 진짜 우리 머리 위에 있는 저 태양 말이야?",
  ui_story_5070_50700701_34_dialog_content = "용주엔 오래된 천측술이 전해지고 있어.",
  ui_story_5070_50700701_35_dialog_content = "별자리판 하나만 있으면 해나 달, 심지어 별자리까지의 거리를 잴 수 있어.",
  ui_story_5070_50700701_36_dialog_content = "고도도 측정할 수 있고, 궤도도 알 수 있다면...",
  ui_story_5070_50700701_37_dialog_content = "네 콜로서스도 조금만 개조하면 하늘을 삼키고 달을 잡아먹는\n기관수가 되는 것도 어렵진 않을걸~",
  ui_story_5070_50700701_38_dialog_content = "누가 봐도 과장인데, 어째 선극 씨가 말하면 농담 같지가 않단 말이지...",
  ui_story_5070_50700701_39_dialog_content = "그럼 날 믿어준 PlayerName 당신한테 고마워해야겠는걸, 아하하.",
  ui_story_5070_50700701_40_dialog_content = "그래도 길은 한 발씩 나아가고, 기관은 한 조각씩 만드는 게 중요해.\n그 정도 이치는 나도 알고 있어.",
  ui_story_5070_50700701_41_dialog_content = "비록 지금은 하늘이나 달에 닿을 수도 없지만...",
  ui_story_5070_50700701_42_dialog_content = "태양의 고도나 각도 같은 수치가 있는 것만으로도 이미 다양한 일을 할 수 있어.",
  ui_story_5070_50700701_43_dialog_content = "예를 들어 린 가문의 해도와 합치면 신풍호의 현재 위치도 알아낼 수 있고 말이야.",
  ui_story_5070_50700701_44_dialog_content = "그럼 항상 위치를 확인하고 있으면 해상에서도 길을 안 잃겠네!",
  ui_story_5070_50700701_45_dialog_content = "말은 쉽지만, 바다는 천변만화하는 곳이야. 인력으로 하는 측량은 정확성을 보장하기 어려워.",
  ui_story_5070_50700701_46_dialog_content = "그렇기 때문에 성상을 토대로 정확하게 위치를 가늠할 수 있는 혼천의가\n린 가문의 보물로 여겨져 왔던 거야.",
  ui_story_5070_50700701_47_dialog_content = "거기에 그걸 잘 다룰 수 있는 천측사만 있다면, 항로를 벗어나는 게 더 어려울 정도야.",
  ui_story_5070_50700701_48_dialog_content = "정말 아까운 일이지...",
  ui_story_5070_50700701_49_dialog_content = "혼천의는 해적한테 습격당한 린 가문의 배랑 같이 사라졌다고 들었어.",
  ui_story_5070_50700701_50_dialog_content = "맞아, 그래서 지금 내가 그 자리를 대신하고 있는 거야.",
  ui_story_5070_50700701_51_dialog_content = "지금까진 기관이 사람을 대신해서 일을 해 왔는데,\n기교사가 기관을 대신할 날이 올 줄은 정말 몰랐다니까.",
  ui_story_5070_50700701_52_dialog_content = "근데 그렇게 보면 선극 씨는 신풍호의 항법사인 셈이잖아?",
  ui_story_5070_50700701_53_dialog_content = "어디까지나 임시일 뿐인걸.",
  ui_story_5070_50700701_54_dialog_content = "선기경, 그리 겸손을 보일 필요는 없을 터.",
  ui_story_5070_50700701_55_dialog_content = "「선극」이란 이름은 본디 「선기」, 즉 혼천의를 달리 부르는 이름과 뜻이 통하지 않더냐.",
  ui_story_5070_50700701_56_dialog_content = "마침 「선기경」은 그대의 칭호이고 말이야.",
  ui_story_5070_50700701_57_dialog_content = "그대가 혼천의의 역할을 하는 것은 이제야 비로소 제 임무를 다하는 셈이 아니겠느냐.",
  ui_story_5070_50700701_58_dialog_content = "...제 착각인가요?\n그 얘기 왠지 선극 씨가 그동안은 자기 임무를 잘 못했다는 것처럼 들리는데요?",
  ui_story_5070_50700701_59_dialog_content = "업나라의 요직을 맡은 모사가 서신 한 통만을 남기고 독단적으로 사직하여 떠났으니 말이다.",
  ui_story_5070_50700701_60_dialog_content = "명성이 드높은 당대 최고의 기교사가 공방과 많은 기관들을 버리고,\n우산 한 자루만 지닌 채 홀로 방랑길을 떠났지.",
  ui_story_5070_50700701_61_dialog_content = "임무를 논할 셈이라면, 내 먼저 그 행동의 연유부터 듣고 싶다만, 선기경.",
  ui_story_5070_50700701_62_dialog_content = "공주님...",
  ui_story_5070_50700701_63_dialog_content = "전하, 선극 님께서도 분명히 그만한 연고가 있으셨을 것입니다.",
  ui_story_5070_50700701_64_dialog_content = "......",
  ui_story_5070_50700701_65_dialog_content = "휴~ 뭐 어디 그런 대단한 연고가 있었겠어요?",
  ui_story_5070_50700701_66_dialog_content = "그저 설계도를 도난당한 이유도 있고, 마침 종문에서도 아스트라 대륙에 가서\n보물을 하나 되찾아 오라고 시켜서 말이죠.",
  ui_story_5070_50700701_67_dialog_content = "그땐 상황이 급하다 보니 미처 인사를 못 드렸을 뿐이에요.",
  ui_story_5070_50700701_68_dialog_content = "그렇게까지 신경 쓰시는 걸 보면, 설마 공주님께선 예전에 제가 기관술을\n가르쳐 드리지 않은 것을 아직도 마음에 두고 계신 건 아니겠죠?",
  ui_story_5070_50700701_69_dialog_content = "그땐 저도 아직 어려서 철이 없었어요. 공주님께서 부디 넓은 마음으로 용서해 주세요.",
  ui_story_5070_50700701_70_dialog_content = "무에 어려서 철이 없었다는 게냐. 지금도 하등 변함이 없거늘...",
  ui_story_5070_50700701_71_dialog_content = "푸훕── 아, 미안해요.",
  ui_story_5070_50700701_72_dialog_content = "단당 씨가 그런 표정을 짓다니, 왠지 평소랑 다른 면을 보게 된 것 같아서요.",
  ui_story_5070_50700701_73_dialog_content = "아이참, 어찌 공자까지...!",
  ui_story_5070_50700701_74_dialog_content = "그, 그저 잠시 추태를 보였을 뿐이니 마음에 두지 않았으면 좋겠구나.",
  ui_story_5070_50700701_75_dialog_content = "가만 보니 내 여기서 한담이나 나누고 있어선 안 될 노릇 아니더냐.",
  ui_story_5070_50700701_76_dialog_content = "선기경에겐 항법사의 임무가 있고...",
  ui_story_5070_50700701_77_dialog_content = "PlayerName 공자는 손님의 신분임에도 스스로 나서 바다를 살피는 임무를 맡고 있다.",
  ui_story_5070_50700701_78_dialog_content = "그러니 내 부끄러움을 느껴야 마땅하거늘... 그대들을 방해해서야 쓰겠느냐.",
  ui_story_5070_50700701_79_dialog_content = "신경 쓰지 마세요.\n전 암귀가 다가오는 걸 미리 감지할 수 있으니까, 이 임무를 맡는 게...",
  ui_story_5070_50700701_80_dialog_content = "잠깐만요!",
  ui_story_5070_50700701_81_dialog_content = "휴, 공주님은 방해하고 싶지 않으시겠지만...",
  ui_story_5070_50700701_82_dialog_content = "어떤 놈들은 그런 예의를 모르거든요.",
  ui_story_5070_50700701_83_dialog_content = "보세요, 저렇게 뻔뻔하게 우릴 방해하러 오잖아요.",
  ui_story_5070_50700702_1_dialog_content = "휴... 드디어 끝났네. 갑자기 암귀가 이렇게 잔뜩 나타날 줄이야...",
  ui_story_5070_50700702_2_dialog_content = "그래도 사실 이건 좋은 소식이야.",
  ui_story_5070_50700702_3_dialog_content = "암귀가 활발하게 움직이는 게?!",
  ui_story_5070_50700702_4_dialog_content = "그건 배가 아스트라 근해의 암귀 활동 구역으로 들어섰다는 뜻이거든.",
  ui_story_5070_50700702_5_dialog_content = "육분의나 별자리판은 거짓말을 하지 않지만, 사람의 눈은 그리 정확하지 않아.",
  ui_story_5070_50700702_6_dialog_content = "계산해 보면 이 부근에 왔다는 걸 알 수 있겠지만,\n망망대해 위에서는 수치를 확인하기가 어려워.",
  ui_story_5070_50700702_7_dialog_content = "마침 근거가 될 만한 게 필요하던 참에 암귀가 나타난 거야.",
  ui_story_5070_50700702_8_dialog_content = "기꺼이 희생해서 내 검증을 도와준 셈이지.",
  ui_story_5070_50700702_9_dialog_content = "그래서 난 무척 감사하면서 녀석들을 처리했어.",
  ui_story_5070_50700702_10_dialog_content = "지금 그 말을 암귀가 들으면 어떤 기분일까...",
  ui_story_5070_50700702_11_dialog_content = "어쨌든 계산이 틀리지 않았다는 건, 신풍호의 항해가 무척 순조롭다는 거야.",
  ui_story_5070_50700702_12_dialog_content = "풍향도 딱 좋은 각도로 배를 밀어주고 있어. 이러면 연료도 절약할 수 있겠어.",
  ui_story_5070_50700702_13_dialog_content = "손 씨! 이제 일할 시간이야~",
  ui_story_5070_50700702_14_dialog_content = "...선극 님께서는 저렇게 말씀하셨지만,\n저 요마들은 매우 집요하니 경계를 늦춰서는 안 됩니다.",
  ui_story_5070_50700702_15_dialog_content = "전하께서는 되도록 제 곁을 떠나지 마십시오.",
  ui_story_5070_50700702_16_dialog_content = "이 아스트라 대륙 부근에는 용주보다 더 많은 요마가 있습니다.",
  ui_story_5070_50700702_17_dialog_content = "요마? 전에도 얼핏 들은 것 같은데, 용주에선 암귀를 그렇게 부르는 거야?",
  ui_story_5070_50700702_18_dialog_content = "그렇소, 용주에서는 아스트라인들이 소위 말하는 암귀를 요마라고 일컫고 있소.",
  ui_story_5070_50700702_19_dialog_content = "종서 씨...",
  ui_story_5070_50700702_20_dialog_content = "안에서 안 쉬어도 괜찮으세요? 아까 리청이 약 드셔야 한다면서 한참을 찾던데요...",
  ui_story_5070_50700702_21_dialog_content = "리청 아우는 늘 환자에게 치성을 다하고 있지.",
  ui_story_5070_50700702_22_dialog_content = "허나 비록 종 모가 불편한 몸이 되었다 하여도,\n여전히 검을 들 수 있고, 큰 어려움도 없소.",
  ui_story_5070_50700702_23_dialog_content = "......",
  ui_story_5070_50700702_24_dialog_content = "종 공...",
  ui_story_5070_50700702_25_dialog_content = "작화군주는 일개 낭인을 그리 공대할 필요는 없소. 제위 또한 마찬가지이오.",
  ui_story_5070_50700702_26_dialog_content = "귀공도 감시 일은 잠시 종 모에게 맡기고 쉬도록 하게.",
  ui_story_5070_50700702_27_dialog_content = "아, 전 괜찮아요. 이 근처는 위험하다고 하니까,\n역시 여러 사람이 감시하는 게 좋을 것 같아요.",
  ui_story_5070_50700702_28_dialog_content = "그렇다면 귀공도 함께 수고해 주게. 용주 근해에 들어서면 다소 편해질 걸세.",
  ui_story_5070_50700702_29_dialog_content = "용주에서는 저 어둠의 요마들이 아스트라처럼 활개 치진 않으니 말이오.",
  ui_story_5070_50700702_30_dialog_content = "조정에서는 정기적으로 요마를 억누르는 의식을 거행하고, 제후국들도 저마다의 대응책이 있소.",
  ui_story_5070_50700702_31_dialog_content = "요마는 주로 깊은 산에 숨어 있다가 생존이 위태로울 때에만 모습을 드러내어,\n홀로 산을 오르는 이를 덮치고 있소.",
  ui_story_5070_50700702_32_dialog_content = "종 공께서는 모르실 수도 있겠군요.\n최근 반년 동안, 용주 각지에서 요마가 소란을 피웠습니다.",
  ui_story_5070_50700702_33_dialog_content = "백성들이 습격당하는 일도 빈번해졌고,\n심지어 성안에 숨어들어 살생을 범하는 일도 있었지요.",
  ui_story_5070_50700702_34_dialog_content = "지금까지 각 나라가 취해 온 대책으로는 이미 벅차게 되어,\n그리 주효하지 못한 상황입니다.",
  ui_story_5070_50700702_35_dialog_content = "이에 민심이 동요하고 있어요.\n이 변고가 수요령의 짓인지, 또 다른 까닭이 있는 것인지는...",
  ui_story_5070_50700702_36_dialog_content = "작화군주는 수요령을 꺼리는 것이오?",
  ui_story_5070_50700702_37_dialog_content = "아, 꺼리는 것이 아니라, 그저 걱정이 될 뿐이어요.",
  ui_story_5070_50700702_38_dialog_content = "잠깐만요, 수요령은 또 뭔데요?",
  ui_story_5070_50700702_39_dialog_content = "귀공은 아스트라 대륙에서 나고 자랐으니, 그곳의 아인족을 떠올리면 이해가 쉬울 것이오.",
  ui_story_5070_50700702_40_dialog_content = "양자의 차이라면, 아인족은 날 때부터 동물의 특징을 가진 사람이나...",
  ui_story_5070_50700702_41_dialog_content = "수요령은 수행으로 요술을 익혀 사람의 모습으로 둔갑할 수도 있는 생령인 것이오.",
  ui_story_5070_50700702_42_dialog_content = "어떤 수요령은 사람들이 싫어하나, 그 능력이나 상징하는 의미로 인해\n사람들이 좋아하는 수요령도 있소.",
  ui_story_5070_50700702_43_dialog_content = "온순한 물고기 유형의 수요령은 뱃일을 하는 자들이 저마다 앞다투어 거둬들이려 하지.",
  ui_story_5070_50700702_44_dialog_content = "...종종 바다에서 위험에 처하고, 물고기와는 상극인 종 모와는 인연이 없지만 말이오.",
  ui_story_5070_50700702_45_dialog_content = "게다가 큰 물고기는 매우 위험한 존재이니 마주치지 않길 바랄 수밖에 없소.",
  ui_story_5070_50700702_46_dialog_content = "이해했어요.",
  ui_story_5070_50700702_47_dialog_content = "아스트라에서도 행운이나 재앙을 가져온다고 여겨지는 동물이 있거든요.",
  ui_story_5070_50700702_48_dialog_content = "그렇소. 허나 수요령이 가호를 가져온다는 말은 결코 터무니없는 것이 아니오.",
  ui_story_5070_50700702_49_dialog_content = "일찍이 수행을 거듭하여 사람의 모습이 된 후 스스로 그 땅의 평화를 지킨 수요령이 있었소.",
  ui_story_5070_50700702_50_dialog_content = "조정에서조차 그 수요령을 인정하고 벼슬을 내려,\n백성들이 사당을 지어 모시는 것을 허락했을 정도였소.",
  ui_story_5070_50700702_51_dialog_content = "와... 그건 진짜 대단하네요. 저도 그런 수요령을 만날 기회가 있을지 모르겠네요.",
  ui_story_5070_50700702_52_dialog_content = "그나저나 종서 씨는 정말 해박하시네요.",
  ui_story_5070_50700702_53_dialog_content = "요마 퇴치나, 사당이나...",
  ui_story_5070_50700702_54_dialog_content = "이 배에서 그러한 분야의 경험과 지식에 있어 종 공에 비견할 수 있는 자는 결코 없을 게다.",
  ui_story_5070_50700702_55_dialog_content = "PlayerName 공자가 궁금한 것이 더 있거든, 얼마든지 종 공에게 물어보거라.",
  ui_story_5070_50700702_56_dialog_content = "다만 저 바다의 요마들이 얌전히 우리가 담소를 나눌 시간을 주거든 말이다.",
  ui_story_5070_50700702_57_dialog_content = "(아니나 다를까, 암귀들이 얌전할 리는 없는 법이었다.\n우리는 몇 번의 전투를 더 거친 후에야 아스트라 근해를 빠져나올 수 있었다.)",
  ui_story_5070_50700702_58_dialog_content = "(그러나 그때까지 나는 아직 깨닫지 못했다.)",
  ui_story_5070_50700702_59_dialog_content = "(바다의 위협은 결코 암귀뿐만이 아니라는 것을.)",
  ui_story_5070_50700801_1_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_5070_50700801_2_dialog_content = "<color=#e8d9bb>후두두두둑...</color>",
  ui_story_5070_50700801_3_dialog_content = "PlayerName! PlayerName! 얼른 일어나!",
  ui_story_5070_50700801_4_dialog_content = "으음...? 선극 씨?",
  ui_story_5070_50700801_5_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5070_50700801_6_dialog_content = "으앗! 무슨 일이야?",
  ui_story_5070_50700801_7_dialog_content = "불이 번진다! 얼른 물주머니 가져 와!",
  ui_story_5070_50700801_8_dialog_content = "으악! 아직 대피가 안 끝났어! 선실로 몰리지 말고 흩어져!",
  ui_story_5070_50700801_9_dialog_content = "떠들지 마! 연료 창고부터 지켜! 여기까지 타면 끝장이야!",
  ui_story_5070_50700801_10_dialog_content = "이게 무슨 난리야?! 대체 뭐가 어떻게 된 거냐고...",
  ui_story_5070_50700801_11_dialog_content = "이제 원양 수역에 들어섰거든. 여긴 날씨가 무척 불안정해.",
  ui_story_5070_50700801_12_dialog_content = "게다가 운이 나빠서 들어서자마자 최악의 경우에 걸렸지 뭐야.",
  ui_story_5070_50700801_13_dialog_content = "...뇌우를 만났어.",
  ui_story_5070_50700801_14_dialog_content = "보통의 폭풍이라면 우리도 충분히 대처할 수 있었겠지만,\n방금 벼락이 친 뒤에 배에 갑자기 폭발이 발생했어.",
  ui_story_5070_50700801_15_dialog_content = "그래서 지금 다들 밖에서 대피와 진화 작업을 하고 있는 거야.",
  ui_story_5070_50700801_16_dialog_content = "벼락... 폭발?",
  ui_story_5070_50700801_17_dialog_content = "우리가 출발 전에 피뢰 설비랑 방화 설비도 확인했잖아? 근데 어떻게...",
  ui_story_5070_50700801_18_dialog_content = "설비로 막을 수 있는 건 자연적인 것들뿐이야.",
  ui_story_5070_50700801_19_dialog_content = "아무래도 이 소동이 벌어진 건 그것만이 원인이 아닐 거야.",
  ui_story_5070_50700801_20_dialog_content = "뭐?",
  ui_story_5070_50700801_21_dialog_content = "어쨌든 지금 그런 얘기를 할 때가 아냐.\n나도 아직 이 화재의 원인을 파악하진 못했으니까.",
  ui_story_5070_50700801_22_dialog_content = "내가 도와줄 수 있는 건 없을까?",
  ui_story_5070_50700801_23_dialog_content = "휴, 원래 당신을 안전한 곳으로 대피시키려고 온 거지만, 지금은 역시 일손이 부족해.",
  ui_story_5070_50700801_24_dialog_content = "그럼 사양 안 할게.",
  ui_story_5070_50700801_25_dialog_content = "따라 와.",
  ui_story_5070_50700801_26_dialog_content = "왜 불길이 안 잡히는 거야?! 다들 뭐 하고 있어!",
  ui_story_5070_50700801_27_dialog_content = "네가 해 봐! 지금은 불이 밖으로 안 번지게 하는 것만으로도 벅차다고!",
  ui_story_5070_50700801_28_dialog_content = "젠장, 왜 하필 밑에서 불이 난 거야?! 선창 쪽은 전부 목제라 못 버텨!",
  ui_story_5070_50700801_29_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5070_50700801_30_dialog_content = "<color=#e8d9bb>그 순간, 근처에서 굉음과 함께 화염에 휩싸인 선창의 문이 날아왔다.</color>",
  ui_story_5070_50700801_31_dialog_content = "<color=#e8d9bb>휘이익──!</color>",
  ui_story_5070_50700801_32_dialog_content = "<color=#e8d9bb>타오르는 나무판은 선원의 코앞에서 여러 조각으로 부서졌다.</color>",
  ui_story_5070_50700801_33_dialog_content = "자연의 위협은 무정하다. 변고 앞일수록 먼저 자신을 다스려야 하는 법이다.",
  ui_story_5070_50700801_34_dialog_content = "겁이 나는 것은 당연지사이나, 그 겁에 스스로 발이 묶여서는 아니 될 것이다.",
  ui_story_5070_50700801_35_dialog_content = "조...종 대인! 감사합니다!",
  ui_story_5070_50700801_36_dialog_content = "솔직히 말씀드리자면, 저 혼자서는 이 배의 문제를 감당할 수가 없습니다...\n하여 종 대인께 도움을 청하고 싶습니다.",
  ui_story_5070_50700801_37_dialog_content = "지금 상황에서 어떻게 하면 좋겠습니까?",
  ui_story_5070_50700801_38_dialog_content = "선상에서 들어야 할 것은 종 모가 아니라 선장의 지시가 아니던가.",
  ui_story_5070_50700801_39_dialog_content = "종 대인, 도움을 주셔서 감사합니다.",
  ui_story_5070_50700801_40_dialog_content = "선장님... 조타에 전념하셔야 할 때인데 저희까지 염려하시게 만들다니... 죄송합니다.",
  ui_story_5070_50700801_41_dialog_content = "사과할 필요 없어. 선상의 모든 책임을 지는 게 선장이야.\n그렇지 못하면 선장 노릇은 할 수 없어.",
  ui_story_5070_50700801_42_dialog_content = "배 상태는 이미 확인했어. 지금부터 움직인다면 불길을 잡을 수 있을 거야.",
  ui_story_5070_50700801_43_dialog_content = "알겠습니다!",
  ui_story_5070_50700801_44_dialog_content = "아직 풍랑이 강해... 리청, 사람들을 데리고 더 멀리 대피해 줘.",
  ui_story_5070_50700801_45_dialog_content = "나머지 사람들은 소화포를 챙기고, 불갈퀴로 불씨를 차단해.",
  ui_story_5070_50700801_46_dialog_content = "곧 지원이 올 테니까.",
  ui_story_5070_50700801_47_dialog_content = "콜록콜록... 공기가 점점 더 뜨거워지고 있어... 이쪽도 오래 있긴 힘들겠어.",
  ui_story_5070_50700801_48_dialog_content = "선극 씨, 이것저것 또 챙겨와 봤는데, 쓸 만한 게 있을까?",
  ui_story_5070_50700801_49_dialog_content = "<size=28>...선창에 쓰인 목재는 뒤틀림에 약해. 수압을 고려하면...</size>",
  ui_story_5070_50700801_50_dialog_content = "선극 씨?",
  ui_story_5070_50700801_51_dialog_content = "아, PlayerName, 금방 가져왔네?",
  ui_story_5070_50700801_52_dialog_content = "사실 꽤 오래 걸렸는데, 선극 씨가 집중해서 못 느낀 것 같아.",
  ui_story_5070_50700801_53_dialog_content = "근데 시킨 대로 쓸만한 걸 찾아봤지만...",
  ui_story_5070_50700801_54_dialog_content = "이 주변엔 빈 상자랑 못 쓰는 부품밖에 없었어.",
  ui_story_5070_50700801_55_dialog_content = "이걸로 진짜 진화용 기관을 만들 수 있을까?",
  ui_story_5070_50700801_56_dialog_content = "어쩔 수 없어. 화물창 쪽 통로는 불로 막혀서 못 지나가니까,\n여기 있는 것만으로 어떻게든 해 봐야지.",
  ui_story_5070_50700801_57_dialog_content = "유능한 기교사라면 기존에 정해진 설계나 좋은 재료에 의존하지 않아도\n기관을 만들 수 있어야 해.",
  ui_story_5070_50700801_58_dialog_content = "목재는 경도가 부족하면 도료로 보강하고, 못이 없으면 줄로 연결하면 돼.\n전체 강도는 구조 변경으로 강화하면 되고.",
  ui_story_5070_50700801_59_dialog_content = "그렇게 경험과 지식을 융합하고 응용해서, 자신이 딱 원하는 걸 만들어 내는 거야.",
  ui_story_5070_50700801_60_dialog_content = "그런 자유로운 변환이야말로 기관술의 정수인 거지.",
  ui_story_5070_50700801_61_dialog_content = "자! 다 됐어! 이제 올라가서 도와주자.",
  ui_story_5070_50700801_62_dialog_content = "선장님! 위쪽의 불은 잡았지만, 선창 쪽은 여전히...",
  ui_story_5070_50700801_63_dialog_content = "괜찮아.",
  ui_story_5070_50700801_64_dialog_content = "오래 기다리셨습니다──!",
  ui_story_5070_50700801_65_dialog_content = "임시방편으로 만든다고 시간이 좀 걸렸지만, 그래도 효과는 보장할 수 있어!",
  ui_story_5070_50700801_66_dialog_content = "서, 선극 님... 그게 뭡니까?",
  ui_story_5070_50700801_67_dialog_content = "PlayerName, 기관을 켜 줘.",
  ui_story_5070_50700801_68_dialog_content = "응!",
  ui_story_5070_50700801_69_dialog_content = "<color=#e8d9bb>철컥── 철컥──</color>",
  ui_story_5070_50700801_70_dialog_content = "<color=#e8d9bb>제각각 흩어져 있던 목재가 금속판과 함께 스스로 회전하면서\n서로 합쳐지고 맞물리기 시작했다.</color>",
  ui_story_5070_50700801_71_dialog_content = "<color=#e8d9bb>한쪽은 뱃전에서 해수면으로 뻗어나갔고, 다른쪽은 배 위에 일어선 그 모습은\n마치 기관 용 한 마리가 바다에서 고개를 들어 올린 듯했다.</color>",
  ui_story_5070_50700801_72_dialog_content = "재료는 빈 상자랑 버려진 부품뿐이었지만, 불길을 잡기엔 충분해.",
  ui_story_5070_50700801_73_dialog_content = "그럼 이름은... 「기관 수룡」이라 하자고~",
  ui_story_5070_50700801_74_dialog_content = "<color=#e8d9bb>용의 입에서 힘차게 물줄기가 뿜어져 나오자, 선창 안은 하얀 연기로 가득 찼고,\n기승을 부리던 불길도 어느새 자취를 감추었다.</color>",
  ui_story_5070_50700801_75_dialog_content = "자, 멍하니 보고만 있지 말고 다들 수습하자.",
  ui_story_5070_50700801_76_dialog_content = "선극 소저, 그럼 이쪽을 부탁할게.",
  ui_story_5070_50700801_77_dialog_content = "분부대로~",
  ui_story_5070_50700801_78_dialog_content = "마침 PlayerName도 있고... 어라? PlayerName?",
  ui_story_5070_50700801_79_dialog_content = "...뭔가 이상해.",
  ui_story_5070_50700801_80_dialog_content = "<color=#e8d9bb>콰아앙──</color>",
  ui_story_5070_50700801_81_dialog_content = "<color=#e8d9bb>방금 제압되었던 불길이 굉음과 함께 갑자기 다시 타오르기 시작했다.</color>",
  ui_story_5070_50700801_82_dialog_content = "이런... 이대로는 끝이 안 나겠어!",
  ui_story_5070_50700801_83_dialog_content = "감응 능력으로 폭발의 근원지를 확인해 볼게. 뭔가 해결책을 찾을 수 있을지도 몰라.",
  ui_story_5070_50700801_84_dialog_content = "(강제 감응!)",
  ui_story_5070_50700801_85_dialog_content = "(여기가 아니야... 더 밑이야.)",
  ui_story_5070_50700801_86_dialog_content = "(여긴... 화물창? 화물창에 대체 뭐가 있길래...)",
  ui_story_5070_50700801_87_dialog_content = "위험해!",
  ui_story_5070_50700801_88_dialog_content = "<size=45>끼이익──!</size>",
  ui_story_5070_50700801_89_dialog_content = "<color=#e8d9bb>발밑의 갑판을 부수며 기관수가 모습을 드러냈고, 갑판 아래는 온통 불바다였다.</color>",
  ui_story_5070_50700801_90_dialog_content = "PlayerName!",
  ui_story_5070_50700801_91_dialog_content = "떨어진다아아!",
  ui_story_5070_50700801_92_dialog_content = "「단멸의 불길!」",
  ui_story_5070_50700801_93_dialog_content = "!",
  ui_story_5070_50700801_94_dialog_content = "(으윽... 등이 아프잖아... 근데...)",
  ui_story_5070_50700801_95_dialog_content = "(불 속에 떨어졌을 텐데 왜 하나도 안 뜨겁지?)",
  ui_story_5070_50700801_96_dialog_content = "다친 곳은 없는가.",
  ui_story_5070_50700801_97_dialog_content = "종서 씨?! 왜 같이 내려오신 거예요?! 위험하잖아요... 괜찮으세요...?",
  ui_story_5070_50700801_98_dialog_content = "선기경이 종 모의 이륜거를 개조해 준 덕에 이 정도 충격은 무방하오.",
  ui_story_5070_50700801_99_dialog_content = "아니, 지금 그게 문제가 아니잖아요...",
  ui_story_5070_50700801_100_dialog_content = "게다가 종 모는 화능술에 자못 재주가 있소. 이 배를 덮은 불처럼 말이오.",
  ui_story_5070_50700801_101_dialog_content = "하여 불길이 귀공을 해하지 못하도록 억누르는 것은 어렵지 않소.",
  ui_story_5070_50700801_102_dialog_content = "대단하네요! 그럼 불 속도 자유롭게 움직일 수 있는 건가요?",
  ui_story_5070_50700801_103_dialog_content = "아, 여긴 화물창이랑 가까우니까, 종서 씨의 힘만 있으면\n곧바로 화재의 근원지로 갈 수 있을 거예요!",
  ui_story_5070_50700801_104_dialog_content = "기다리게.",
  ui_story_5070_50700801_105_dialog_content = "귀공은 분명 기이한 술법을 지녔으나, 근골은 특출하지 않을 것이오.\n그러니 먼저 안전한 곳으로 돌아가는 게 상책이오.",
  ui_story_5070_50700801_106_dialog_content = "우연히 절호의 기회를 얻었는데, 여기서 포기할 순 없어요.",
  ui_story_5070_50700801_107_dialog_content = "허나 그것이 귀공의 소임은 아니지 않소.",
  ui_story_5070_50700801_108_dialog_content = "귀공은 이국의 사절이라는 막중한 사명을 띠고 있소.\n자신의 안녕을 우선하더라도 책망할 이는 아무도 없을 것이오.",
  ui_story_5070_50700801_109_dialog_content = "헌데 어찌 스스로 위험에 몸을 던진단 말인가.",
  ui_story_5070_50700801_110_dialog_content = "종서 씨가 절 걱정해 주시는 건 알아요. 근데 아직 일어나지도 않은 일을 걱정한다면...",
  ui_story_5070_50700801_111_dialog_content = "전 아무것도 해낼 수 없을 거예요.",
  ui_story_5070_50700801_112_dialog_content = "그리고 방금 저랑 같이 뛰어내린 종서 씨가 그런 말씀을 하시는 건\n설득력이 좀 부족하지 않나요?",
  ui_story_5070_50700801_113_dialog_content = "절 도울 책임이 없는 건 종서 씨도 마찬가지잖아요. 안 그래요?",
  ui_story_5070_50700801_114_dialog_content = "......",
  ui_story_5070_50700801_115_dialog_content = "하하하, 귀공의 말도 일리가 있군.",
  ui_story_5070_50700801_116_dialog_content = "실은 종 모 역시 이렇게 남을 설파하는 입장이 될 날이 올 줄은 몰랐소이다.",
  ui_story_5070_50700801_117_dialog_content = "귀공은 참으로 초탈한 심성을 지녔구려.",
  ui_story_5070_50700801_118_dialog_content = "하면 함께 가도록 하세.",
  ui_story_5070_50700801_119_dialog_content = "그럼 다시 한번 근원지를 확인해 볼게요.",
  ui_story_5070_50700801_120_dialog_content = "(강제 감응!)",
  ui_story_5070_50700801_121_dialog_content = "...잠깐만요. 뭔가 상태가 이상해요. 게다가...",
  ui_story_5070_50700801_122_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_5070_50700801_123_dialog_content = "<size=45>조심하게!</size>",
  ui_story_5070_50700801_124_dialog_content = "<color=#e8d9bb>갑자기 폭발이 일어났고, 주변의 모든 것이 화염에 삼켜졌다.</color>",
  ui_story_5070_50700802_1_dialog_content = "콜록! 콜록콜록... 온통 연기잖아...",
  ui_story_5070_50700802_2_dialog_content = "숨 막혀... 집중이 안 돼... 근데 방금 누가 있었던 것 같은데...",
  ui_story_5070_50700802_3_dialog_content = "......",
  ui_story_5070_50700802_4_dialog_content = "콜록... 당신... 누구야...",
  ui_story_5070_50700802_5_dialog_content = "<color=#e8d9bb>그 순간, 연기 속에서 기이한 빛 한 줄기가 나타났다.</color>",
  ui_story_5070_50700802_6_dialog_content = "PlayerName!",
  ui_story_5070_50700802_7_dialog_content = "조, 종서 씨... 콜록...",
  ui_story_5070_50700802_8_dialog_content = "손을 이리 주게!",
  ui_story_5070_50700802_9_dialog_content = "잠깐만요, 저쪽에...",
  ui_story_5070_50700802_10_dialog_content = "<color=#e8d9bb>이윽고 폭발과 함께 앞쪽의 불길은 더 거세지고 말았다.</color>",
  ui_story_5070_50700802_11_dialog_content = "일단 여기부터 나가도록 하지.",
  ui_story_5070_50700802_12_dialog_content = "종 공! PlayerName 그 사람 괜찮은가요?",
  ui_story_5070_50700802_13_dialog_content = "다들 비켜요! 비켜!",
  ui_story_5070_50700802_14_dialog_content = "의원이 왔으니까 지나가게 해 줘!",
  ui_story_5070_50700901_1_dialog_content = "으음...",
  ui_story_5070_50700901_2_dialog_content = "야옹~",
  ui_story_5070_50700901_3_dialog_content = "...웬 고양이가 여기 있어?",
  ui_story_5070_50700901_4_dialog_content = "아... 너, 리청 옆에 있던 그 고양이지...? 작은꼬리라고 했었나?",
  ui_story_5070_50700901_5_dialog_content = "우냥!",
  ui_story_5070_50700901_6_dialog_content = "네가 왜 여깄어?",
  ui_story_5070_50700901_7_dialog_content = "맞다... 어제 화재는 어떻게 됐지...? 다들 무사한지 봐야 하는데...!",
  ui_story_5070_50700901_8_dialog_content = "우냐앙!",
  ui_story_5070_50700901_9_dialog_content = "으앗... 작은꼬리 너 길 막지 마... 내가 실수로 밟았으면 어쩔 뻔했어.",
  ui_story_5070_50700901_10_dialog_content = "어? 약 좀 가지러 가려고 했더니, 왜 일어났어?",
  ui_story_5070_50700901_11_dialog_content = "얼른 다시 가서 누워!",
  ui_story_5070_50700901_12_dialog_content = "야옹~",
  ui_story_5070_50700901_13_dialog_content = "작은꼬리, 잘했어!",
  ui_story_5070_50700901_14_dialog_content = "역시 PlayerName 너도 종서 형님처럼 손이 많이 가는 환자일 줄 딱 알았다니까.",
  ui_story_5070_50700901_15_dialog_content = "...그럼 네가 작은꼬리한테 나 못 나가게 하라고 시킨 거야?",
  ui_story_5070_50700901_16_dialog_content = "당연하지. 연기 좀 마신 게 무슨 대수라고 생각하면 안 돼.",
  ui_story_5070_50700901_17_dialog_content = "폐 깊숙이 파고들면 큰일이거든.",
  ui_story_5070_50700901_18_dialog_content = "자, 누워 있어.",
  ui_story_5070_50700901_19_dialog_content = "패모 1전 5푼, 과루 1전, 꽃가루, 복령, 귤홍, 길경 각 8푼.",
  ui_story_5070_50700901_20_dialog_content = "그건 뭐야?",
  ui_story_5070_50700901_21_dialog_content = "폐를 씻고 열을 빼는 처방이야.",
  ui_story_5070_50700901_22_dialog_content = "당분간 물 많이 마시고 푹 쉬어. 신선한 공기도 많이 마시고,\n밥은 따듯하고 담백한 것들 위주로 먹어.",
  ui_story_5070_50700901_23_dialog_content = "기침이나 가래가 나오거나 가슴이 답답하면 바로 나한테 말해. 알겠어?",
  ui_story_5070_50700901_24_dialog_content = "뭐야? 왜 그런 표정으로 보는 건데?",
  ui_story_5070_50700901_25_dialog_content = "리청 넌 이럴 땐 정말 든든하네.",
  ui_story_5070_50700901_26_dialog_content = "마치... 음, 용주에서 뭐라고 한댔더라...? 아, 그래! 꼭 명의 같아!",
  ui_story_5070_50700901_27_dialog_content = "진짜?! 크흠... 그, 그거야 당연하지.",
  ui_story_5070_50700901_28_dialog_content = "뭐, 아무튼, 식기 전에 약 먹어.",
  ui_story_5070_50700901_29_dialog_content = "꿀꺽, 꿀꺽... 쓰읍... 뭐, 뭔가 말하기 복잡한 맛이네.",
  ui_story_5070_50700901_30_dialog_content = "복자께서 가라사대 「좋은 약은 입에 쓰다」, 그건 건강해지기 위한 대가라구.",
  ui_story_5070_50700901_31_dialog_content = "...그렇게 맛없어?",
  ui_story_5070_50700901_32_dialog_content = "맛없다는 게 아냐. 그냥 이렇게 맛이 복잡한 건 태어나서 처음 먹어봤거든...",
  ui_story_5070_50700901_33_dialog_content = "좀 익숙하지 않을 뿐이야.",
  ui_story_5070_50700901_34_dialog_content = "휴, 이래서 젊은 사람들은 어쩔 수 없다니까.",
  ui_story_5070_50700901_35_dialog_content = "자, 과일청 줄게. 약 다 먹고 나서 먹으면 쓴맛이 좀 가실 거야.",
  ui_story_5070_50700901_36_dialog_content = "근데 남은 건 그거 하나뿐이야. 배에 탈 때 한 봉지만 몰래 챙긴 거거든.",
  ui_story_5070_50700901_37_dialog_content = "고마워, 리청. 넌 정말 친절하구나.",
  ui_story_5070_50700901_38_dialog_content = "어쩔 수 없지. 난 명의인걸!",
  ui_story_5070_50700901_39_dialog_content = "그럼 푹 쉬어. 난 다른 사람들도 보러 가야 하니까.",
  ui_story_5070_50700901_40_dialog_content = "또 다친 사람이 있어?",
  ui_story_5070_50700901_41_dialog_content = "일어나지 마. 어제 화재에선 네가 제일 중상이었어. 다른 사람 걱정할 때가 아냐.",
  ui_story_5070_50700901_42_dialog_content = "괜찮아, 다들 별일 없으니까.",
  ui_story_5070_50700901_43_dialog_content = "그냥 혹시 모르니까, 열을 가라앉히고 독기를 제거하는 약을 전부 처방했거든.",
  ui_story_5070_50700901_44_dialog_content = "참, 다른 사람들은...",
  ui_story_5070_50700901_45_dialog_content = "네가 자는 동안 벌써 여러 사람이 널 보고 갔어. 이제 너도 일어났으니까 불러와도 되겠네.",
  ui_story_5070_50700901_46_dialog_content = "아, 괜찮아, 안 그래도 돼. 다들 무사하면 됐어. 굳이 안 불러도...",
  ui_story_5070_50700901_47_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5070_50700901_48_dialog_content = "그렇게 부끄러워하실 게 뭐가 있어요~",
  ui_story_5070_50700901_49_dialog_content = "으앗──!",
  ui_story_5070_50700901_50_dialog_content = "단당 씨?",
  ui_story_5070_50700901_51_dialog_content = "선극 님, 그렇게 전하를 함부로 미시면 어떡합니까.",
  ui_story_5070_50700901_52_dialog_content = "휴, 구 소저도 참, 너무 과보호 아냐? 긴장 좀 풀어.\n전하는 고귀한 분이지만 그렇다고 도자기 인형은 아니잖아?",
  ui_story_5070_50700901_53_dialog_content = "...선극 씨? 구 씨? 왜 다들...",
  ui_story_5070_50700901_54_dialog_content = "당연히 어제의 일등 공신을 보러 온 거지.",
  ui_story_5070_50700901_55_dialog_content = "크게 다치진 않아서 다행이야.\n만약 그랬으면 내가 어떻게 사과할지 참 곤란했을 테니까.",
  ui_story_5070_50700901_56_dialog_content = "선극 씨가 사과할 필요는 없잖아. 그때 바닥이 무너질 줄 누가 알았겠어.",
  ui_story_5070_50700901_57_dialog_content = "게다가 다들 무사하다는 건 선극 씨 기관 덕분에 불을 껐다는 거잖아...",
  ui_story_5070_50700901_58_dialog_content = "음, 말도 잘하는 거 보면 확실히 문제는 없어 보이네.",
  ui_story_5070_50700901_59_dialog_content = "어떠신가요? 공주 전하, 직접 눈으로 PlayerName의 건강한 모습을 보시는 게...",
  ui_story_5070_50700901_60_dialog_content = "문 너머에서 몰래 훔쳐보는 것보다 훨씬 낫죠?",
  ui_story_5070_50700901_61_dialog_content = "...필시 선기경이 잘못 본 게야.",
  ui_story_5070_50700901_62_dialog_content = "PlayerName 공자는 중요한 사절이 아니더냐.\n하여 공자의 안위를 염려하는 것도 응당 내 소임인 게지.",
  ui_story_5070_50700901_63_dialog_content = "그, 그러니 내 구태여 훔쳐볼 까닭이 무어란 말이냐.",
  ui_story_5070_50700901_64_dialog_content = "예예, 그러시겠죠. 분명히 어제 연기 때문에 제 눈이 침침해서 제대로 못 봤나 보네요.",
  ui_story_5070_50700901_65_dialog_content = "그럼 공주 전하는 계속해서 소임에 충실히 PlayerName 공자를 염려해 주시와요~",
  ui_story_5070_50700901_66_dialog_content = "무, 무슨...",
  ui_story_5070_50700901_67_dialog_content = "괜찮아요, 단당 씨. 저 아주 멀쩡해요. 전혀 걱정할 필요 없어요.",
  ui_story_5070_50700901_68_dialog_content = "딱히 곤란한 것도 없고... 음... 약 맛이 참 뭐라 말하기 뭣한 거 말고는...",
  ui_story_5070_50700901_69_dialog_content = "약 말이더냐? 그거라면 나도 어찌할 방도가 없겠구나.",
  ui_story_5070_50700901_70_dialog_content = "몸이 회복된 후에는 약보다 식이요법이 더 좋은 법이다.",
  ui_story_5070_50700901_71_dialog_content = "마침 리청도 여기 있으니, 내 모두에게 입에 잘 맞을 약선을 만들어 줄까 하는데, 어떻느냐?",
  ui_story_5070_50700901_72_dialog_content = "맛있는 거?! 그거 좋죠!",
  ui_story_5070_50700901_73_dialog_content = "약선 만드는 법이라면 저도 꽤 알아요. 출항 전에 식재료도 잔뜩 사뒀구요.",
  ui_story_5070_50700901_74_dialog_content = "연근은 혈액순환이 잘 되고, 동과는 수분 보충과 미용에 좋아요.\n복령뿌리죽은 심신은 안정시키고...",
  ui_story_5070_50700901_75_dialog_content = "아무튼 이것저것 만들 수 있어요!",
  ui_story_5070_50700901_76_dialog_content = "......",
  ui_story_5070_50700901_77_dialog_content = "선극 씨는 왜 안 먹어? ...선극 씨?",
  ui_story_5070_50700901_78_dialog_content = "음? 뭐 도와줘?",
  ui_story_5070_50700901_79_dialog_content = "아니, 그게 아니라 선극 씨가 말도 없이 뭔가 계속 생각하는 것 같길래.",
  ui_story_5070_50700901_80_dialog_content = "그렇게 티가 났어?",
  ui_story_5070_50700901_81_dialog_content = "아무래도 내 수행도 아직 부족했던 모양이네.\n언제 기회가 되면 표정 유지하는 가면이나 좀 만들어 봐야겠어.",
  ui_story_5070_50700901_82_dialog_content = "으음, 사실 어제 일 생각 중이었거든.",
  ui_story_5070_50700901_83_dialog_content = "종 공이 연기 속에서 당신을 구해오셨을 때...",
  ui_story_5070_50700901_84_dialog_content = "당신은 계속 「화염」, 그리고 「누군가가 있다」는 말을 했어.",
  ui_story_5070_50700901_85_dialog_content = "대체 거기서 뭘 본 거야?",
  ui_story_5070_50700901_86_dialog_content = "정확히 말하자면 본 게 아니라 감응한 거야.",
  ui_story_5070_50700901_87_dialog_content = "그 화물창 안에 뭔가 엄청 이상한 게 있었어.\n불 같으면서도 불의 열기는 전혀 안 느껴졌거든.",
  ui_story_5070_50700901_88_dialog_content = "근데 열기는 없으면서, 정작 주변의 모든 불길을 합친 것보다\n더 밀도가 높고 강한 느낌이었어.",
  ui_story_5070_50700901_89_dialog_content = "마치... 태양을 그대로 압축한 것처럼 말이야.",
  ui_story_5070_50700901_90_dialog_content = "...내가 말하고도 이상한 설명이지만.",
  ui_story_5070_50700901_91_dialog_content = "아무튼 난 왠지 벼락은 그냥 우연한 계기고,\n그 물건이 진짜 화재의 근원지 아니었을까 싶어.",
  ui_story_5070_50700901_92_dialog_content = "그리고 분명히 누군가 있긴 했는데 자세히 보진 못했어.\n근데 그 사람, 계속 화물창 근처에 서 있었거든...",
  ui_story_5070_50700901_93_dialog_content = "아무리 생각해도 뭔가 이상했어.",
  ui_story_5070_50700901_94_dialog_content = "알겠어.",
  ui_story_5070_50700901_95_dialog_content = "그래도 앞으로는 그렇게 경솔하게 굴면 안 돼.",
  ui_story_5070_50700901_96_dialog_content = "멋대로 뭔가 감응해서 다가가는 건 위험해.",
  ui_story_5070_50700901_97_dialog_content = "정말 문제가 생겨버리면 내가 미처 도울 틈도 없을 테니까...",
  ui_story_5070_50700901_98_dialog_content = "미안... 앞으로 조심할게.",
  ui_story_5070_50700901_99_dialog_content = "그럼 난 먼저 갈게.",
  ui_story_5070_50700901_100_dialog_content = "잠깐만.",
  ui_story_5070_50700901_101_dialog_content = "내가 자는 동안 또 뭔가 안 좋은 일 있었어?",
  ui_story_5070_50700901_102_dialog_content = "......",
  ui_story_5070_50700901_103_dialog_content = "...휴, 역시 그 가면, 시간 날 때 빨리 만드는 게 좋겠어.",
  ui_story_5070_50700901_104_dialog_content = "무사히 용주 공방으로 돌아가는 게 먼저겠지만.",
  ui_story_5070_50700901_105_dialog_content = "설마... 항해에 문제가 생긴 거야?",
  ui_story_5070_50700901_106_dialog_content = "바다 사람들 사이엔 이런 말이 있어.",
  ui_story_5070_50700901_X106_dialog_content = "「사공이 바다를 알고자 하거든 밤에는 달을 보고, 낮에는 해를 보면 된다.\n흐리고 어둡거든 자침을 보고, 바늘이 흐트러지거든 속히 떠날지어다.」",
  ui_story_5070_50700901_107_dialog_content = "별이나 해를 본다는 건 전에 선극 씨가 말한 별자리로 항로를 판단하는 거 얘기지?",
  ui_story_5070_50700901_108_dialog_content = "맞아, 그리고 별이나 달이 안 보일 땐 나침반 같은 기계로 방향을 가늠하는 거지.",
  ui_story_5070_50700901_109_dialog_content = "그런데 만약 기계까지 못 쓰게 된다면, 방향을 판단할 방법은 없어지는 거야.",
  ui_story_5070_50700901_110_dialog_content = "그럼 얼른 그 해역을 떠나지 않으면, 바다 위에서 길을 잃고 말겠지.",
  ui_story_5070_50700901_111_dialog_content = "어제 소동이 끝난 뒤에 난 폭풍우 속에서 방향을 찾으려고 모든 수단을 동원했어.",
  ui_story_5070_50700901_112_dialog_content = "...다 안 됐던 거야?",
  ui_story_5070_50700901_113_dialog_content = "<color=#e8d9bb>선극은 가볍게 고개를 끄덕였다.</color>",
  ui_story_5070_50700901_114_dialog_content = "지금까지도 상황은 해결이 안 됐어.",
  ui_story_5070_50700901_115_dialog_content = "신풍호가 올바른 항로로 가고 있다면 이런 일이 일어날 리가 없거든.",
  ui_story_5070_50700901_116_dialog_content = "지금 우리가 있는 원양 수역은 완전한 해도가 없어.\n날씨가 좋아져도 태양으로 방향을 판단할 수 없을 거야.",
  ui_story_5070_50700901_117_dialog_content = "다시 말해서 지금...",
  ui_story_5070_50700901_118_dialog_content = "신풍호는 이미 항로를 벗어나 버린 거야.",
  ui_story_5070_50700902_1_dialog_content = "방향도 잃은 데다가 암귀의 습격에도 대응해야만 해...\n정말 다사다난한 항해가 돼버렸잖아.",
  ui_story_5070_50700902_2_dialog_content = "일단 위치를 확인할 방법부터 서둘러 마련해야겠어.",
  ui_story_5070_50700902_3_dialog_content = "그랬구나... 근데 그거랑 기관 수룡을 들고나오는 거랑 무슨 상관인데?",
  ui_story_5070_50700902_4_dialog_content = "우린 기관을 제작하고 기능을 부여하지만,\n그 기관의 쓰임새가 꼭 한 가지만 있는 건 아냐.",
  ui_story_5070_50700902_5_dialog_content = "<color=#e8d9bb>굉음과 함께 바닷물이 황동관을 지나 미리 준비되어 있던 통 속으로 쏟아졌다.</color>",
  ui_story_5070_50700902_6_dialog_content = "봐, 바닷물만 끌어온 게 아니라 이렇게 새우랑 게도 잡았잖아.",
  ui_story_5070_50700902_7_dialog_content = "비록 하나의 바다지만, 해역이 다르면 그곳에 사는 생물도 달라.",
  ui_story_5070_50700902_8_dialog_content = "특정 해역을 대표할 만한 생물이 잡힌다면...",
  ui_story_5070_50700902_9_dialog_content = "해도의 생물 분포 기록을 바탕으로 대략적인 위치를 알 수 있을 거야.",
  ui_story_5070_50700902_10_dialog_content = "그런 관점으로도 생각할 수 있는 거였구나!",
  ui_story_5070_50700902_11_dialog_content = "그럼 뭐 특별한 거 잡힌 게 있어?",
  ui_story_5070_50700902_12_dialog_content = "아쉽지만 다 어디에나 있는 생선이나 새우야.\n나중에 단당 님께 드려서 약선으로 만들면 되겠어.",
  ui_story_5070_50700902_13_dialog_content = "그리고 미리 말해두는데, 이런 일에는 위험도 따르기 마련이야.",
  ui_story_5070_50700902_14_dialog_content = "어? 선원들도 매일 물고기를 잡아서 우리한테 주고 있잖아. 뭐가 위험한데?",
  ui_story_5070_50700902_15_dialog_content = "사실 방금 하던 얘기는 거기서 끝이 아니거든.",
  ui_story_5070_50700902_16_dialog_content = "기관은 본래의 기능 외의 일도 많이 할 수 있지만,\n엄밀히 말하면 그걸 위해서 설계된 건 아니야.",
  ui_story_5070_50700902_17_dialog_content = "그러니까 늘 예상 밖의 결과가 발생할 수도 있는 거야...",
  ui_story_5070_50700902_18_dialog_content = "우리가 봤던 불게도 그렇잖아. 장인의 용접을 도울 땐 녀석은 든든한 조수가 돼.",
  ui_story_5070_50700902_19_dialog_content = "하지만 불게한테 고기를 구우라고 하면 화력을 잘 조절할 수 없어.",
  ui_story_5070_50700902_20_dialog_content = "석탄처럼 타버린 고기가 어떤 맛인지 알아?",
  ui_story_5070_50700902_21_dialog_content = "평생 몰랐으면 좋겠어...",
  ui_story_5070_50700902_22_dialog_content = "게다가 불게로 고기를 구워야 하는 건 또 무슨 상황인데?",
  ui_story_5070_50700902_23_dialog_content = "지금처럼 용수 기관으로 고기 잡는 상황이겠지.",
  ui_story_5070_50700902_24_dialog_content = "어쩔 수 없이 임기응변이 필요한 상황은 늘 있기 마련이니까.",
  ui_story_5070_50700902_25_dialog_content = "난 용주 사람들 생각은 잘 모르겠지만...",
  ui_story_5070_50700902_26_dialog_content = "불게로 고기 굽는 건 임기응변이 아니지 않을까?",
  ui_story_5070_50700902_27_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5070_50700902_28_dialog_content = "뭔가 부딪힌 것 같은데?",
  ui_story_5070_50700902_29_dialog_content = "기관 수룡을 멈춰.",
  ui_story_5070_50700902_30_dialog_content = "물을 너무 퍼 올려서 뭔가 큰 녀석을 유인해 버린 것 같아.",
  ui_story_5070_50700902_31_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5070_50700902_32_dialog_content = "배, 배가 기울고 있다! 다들 꽉 잡아!",
  ui_story_5070_50700902_33_dialog_content = "(겨, 겨우 잡았네...)",
  ui_story_5070_50700902_34_dialog_content = "(갑판에서 바람이라도 쐬려고 나왔다가 이런 일을 당할 줄이야.)",
  ui_story_5070_50700902_35_dialog_content = "(다행히 난간에 붙어 있어서 망정이지... 으음? 설마 그 점괘가... 으악!)",
  ui_story_5070_50700902_36_dialog_content = "<color=#e8d9bb>콰앙!</color>",
  ui_story_5070_50700902_37_dialog_content = "점점 더 많이 기울고 있어. 이대로는 아무것도 못 해.",
  ui_story_5070_50700902_38_dialog_content = "다들 배가 뜬 쪽으로 모여! 균형을 유지해!",
  ui_story_5070_50700902_39_dialog_content = "내가 불게로 동력로의 세기를 높여볼게. 선체가 안정되면 바로 가속해서 벗어나는 거야.",
  ui_story_5070_50700902_40_dialog_content = "해냈어! 물속에 보이던 그림자를 뿌리쳤어!",
  ui_story_5070_50700902_41_dialog_content = "불게한테 여러 번 공격을 받았었는데, 정작 이번엔 불게 덕분에 살았잖아.",
  ui_story_5070_50700902_42_dialog_content = "말했지? 기관은 죄가 없어. 선도 악도 없고 말이야.",
  ui_story_5070_50700902_43_dialog_content = "사람을 구하느냐, 해치느냐는 모두 기관을 쓰는 자에게 달린 거야.",
  ui_story_5070_50700902_44_dialog_content = "그럼 내가 불게한테 느끼는 「공포의 거대 게」라는 인상도 좀 바꿔야 될지도 모르겠네...",
  ui_story_5070_50700902_45_dialog_content = "그나저나 신풍호도 이렇게 빠른 속도로 항해하는 건 처음 아냐?\n계속 이대로 갈 순 없는 거야?",
  ui_story_5070_50700902_46_dialog_content = "세상일이 그렇게 호락호락하진 않거든.",
  ui_story_5070_50700902_47_dialog_content = "지금 억지로 동력로의 출력을 높이고 있는 건 불게의 뱃속에 쌓아둔 화능술 덕분이야.",
  ui_story_5070_50700902_48_dialog_content = "제때 보충하지 않으면 금방 고갈될 거고, 그땐...",
  ui_story_5070_50700902_49_dialog_content = "선극 님! 동력로 쪽 선원의 보고입니다. 불게들이 전부 움직임을 멈췄습니다!",
  ui_story_5070_50700902_50_dialog_content = "...저렇게 된다 이거지?",
  ui_story_5070_50700902_51_dialog_content = "...예상보다 빨랐네.",
  ui_story_5070_50700902_52_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5070_50700902_53_dialog_content = "(강제 감응!)",
  ui_story_5070_50700902_54_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5070_50700902_55_dialog_content = "효과가 있나...?",
  ui_story_5070_50700902_56_dialog_content = "<color=#e8d9bb>쿠웅!</color>",
  ui_story_5070_50700902_57_dialog_content = "좀 멈춰 봐! 우린 음식도 아니고 장난감도 아냐!",
  ui_story_5070_50700902_58_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5070_50700902_59_dialog_content = "안 되겠어. 잠깐 멈추게 만들 순 있지만, 신풍호가 녀석을 못 따돌리면 결국 따라잡혀.",
  ui_story_5070_50700902_60_dialog_content = "게다가, 저 생물... 실제로는 수면에서 보이는 모습 이상으로 엄청나게 커...",
  ui_story_5070_50700902_61_dialog_content = "구체적으로 몇 배 정도?",
  ui_story_5070_50700902_62_dialog_content = "뭐?",
  ui_story_5070_50700902_63_dialog_content = "수면에서 보이는 크기는 눈으로 짐작할 수 있어.",
  ui_story_5070_50700902_X63_dialog_content = "거기에 PlayerName 당신 감응 능력으로 배수를 알면\n실제 크기를 산출할 수 있을 거야.",
  ui_story_5070_50700902_64_dialog_content = "신풍호의 중량과 충격의 경사각에서 상대가 내는 힘의 작용 범위를 역산하면...",
  ui_story_5070_50700902_65_dialog_content = "물속에 있는 게 뭔지 알아낼 수 있어!",
  ui_story_5070_50700902_66_dialog_content = "PlayerName, 몇 분만 더 붙잡아 둘 수 있을까?\n선실에 물건을 가지러 가야겠어. 어쩌면 녀석을 떼어낼 수 있을지도 몰라.",
  ui_story_5070_50700902_67_dialog_content = "응, 맡겨 줘!",
  ui_story_5070_50700902_68_dialog_content = "(강제 감응!)",
  ui_story_5070_50700902_69_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5070_50700902_70_dialog_content = "(강제 감응!)",
  ui_story_5070_50700902_71_dialog_content = "<color=#e8d9bb>쿠웅!</color>",
  ui_story_5070_50700902_72_dialog_content = "(으윽... 벌써 몇 번째냐고... 지금 나랑 노는 줄 아는 건가?\n선극 씨는 언제 오는 거야...)",
  ui_story_5070_50700902_73_dialog_content = "<color=#e8d9bb>쾅!</color>",
  ui_story_5070_50700902_74_dialog_content = "(강제 감응...!)",
  ui_story_5070_50700902_75_dialog_content = "PlayerName, 다녀왔어!",
  ui_story_5070_50700902_76_dialog_content = "살았다──!",
  ui_story_5070_50700902_77_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5070_50700902_78_dialog_content = "(지금까지보다 더 강렬한 충격이 전해지자, 나는 그대로 공중에 떠올라 버렸다.)",
  ui_story_5070_50700902_79_dialog_content = "내 우산 잡아!",
  ui_story_5070_50700902_80_dialog_content = "(안 돼! 지금 집중력을 분산시키면 저 괴물을 못 멈춰...!)",
  ui_story_5070_50700902_81_dialog_content = "선극 씨! 손에 든 걸 나한테 줘!",
  ui_story_5070_50700902_82_dialog_content = "?!",
  ui_story_5070_50700902_83_dialog_content = "당신 대체 얼마나 간이 큰 사람인 거야...? 잘 받아!",
  ui_story_5070_50700902_84_dialog_content = "(공중에 있는 내가 더 멀리 던질 수 있어!)",
  ui_story_5070_50700902_85_dialog_content = "장난감 줄 테니까 그만 쫓아 와!",
  ui_story_5070_50700902_86_dialog_content = "<color=#e8d9bb>풍덩──</color>",
  ui_story_5070_50700902_87_dialog_content = "<color=#e8d9bb>당신은 선극에게 받은 돌을 바닷속에 던져넣었다.</color>",
  ui_story_5070_50700902_88_dialog_content = "(바다괴물이 방향을 튼 게 느껴져. 우산을 펴고 날 받아내려는\n선극 씨 모습도 본 것 같아...)",
  ui_story_5070_50700902_89_dialog_content = "(...늦었나... 뭐, 괜찮아. 저 아래에는... 믿을 수 있는 사람이 더 있으니까!)",
  ui_story_5070_50700902_90_dialog_content = "「단멸의 불길!」",
  ui_story_5070_50700902_91_dialog_content = "<color=#e8d9bb>새빨간 불길이 하늘을 찌르며 타오르자, 동력로는 다시 굉음과 함께 전속력으로 가동했고,\n신풍호의 속도도 다시 빨라졌다.</color>",
  ui_story_5070_50700902_92_dialog_content = "(그리고 나는 조용하고 잔잔한 불 속으로 떨어졌다.)",
  ui_story_5070_50700902_93_dialog_content = "휴... 이걸로 확실하게 뿌리쳤네요... 드디어 끝난 건가...",
  ui_story_5070_50700902_94_dialog_content = "PlayerName.",
  ui_story_5070_50700902_95_dialog_content = "용감히 정진하는 귀공의 용기에는 종 모도 감복했소.",
  ui_story_5070_50700902_96_dialog_content = "허나 조금 전 행동은 너무나도 위험했소. 무모함이 지나쳤다 할 수 있을 것이오.",
  ui_story_5070_50700902_97_dialog_content = "(진짜 엄격한 분위기네...)",
  ui_story_5070_50700902_98_dialog_content = "다들 걱정하게 만들어서 미안해요... 그치만 저도 확신이 있었는걸요.",
  ui_story_5070_50700902_99_dialog_content = "종서 씨도 있는 걸 봤으니까요.",
  ui_story_5070_50700902_100_dialog_content = "고마워요.",
  ui_story_5070_50700902_101_dialog_content = "...되었소. 종 모보다 귀공이 감사해야 할 것은 선기경이니 말이오.",
  ui_story_5070_50700902_102_dialog_content = "선기경이 개조해 준 이륜거가 아니었다면, 이 종 모도 흔들리는 배 위에서\n자유로이 움직일 수 없었을 것이오.",
  ui_story_5070_50700902_103_dialog_content = "PlayerName!",
  ui_story_5070_50700902_104_dialog_content = "역시 당신이라면 분명히 괜찮을 거라고 생각했어. 좋은 사람은 하늘이 돕는 법이거든.",
  ui_story_5070_50700902_105_dialog_content = "아하하, 그렇게 믿어준다니 고마워.\n그나저나 돌멩이로 어떻게 저 괴물을 따돌린 거야?",
  ui_story_5070_50700902_106_dialog_content = "저건 그냥 돌이 아니라 발광석이거든. 주위가 어두울수록 밝게 빛나는 거야.",
  ui_story_5070_50700902_107_dialog_content = "아까 그 해수에 대한 기록은 많지 않아. 그저 심해에 서식한다는 정도밖에 없어.",
  ui_story_5070_50700902_108_dialog_content = "하지만 어두운 심해에 사는 생물들은 대부분 빛나는 물건에 관심을 보이기 마련이야.",
  ui_story_5070_50700902_109_dialog_content = "그래서 발광석으로 해수의 주의를 끌 수 있다고 생각했어.",
  ui_story_5070_50700902_110_dialog_content = "다행히 예상대로였고.",
  ui_story_5070_50700902_111_dialog_content = "여러분, 무사하신가요.",
  ui_story_5070_50700902_112_dialog_content = "다들 괜찮아. 잘못하면 해수의 동력원이 될 뻔했지만 말이야.",
  ui_story_5070_50700902_113_dialog_content = "항해가 이렇게까지 힘든 거였구나...",
  ui_story_5070_50700902_114_dialog_content = "하늘엔 저런 게 없어서 정말 다행이야. 아니면 나도 스카이워커도 위험했을 테니까.",
  ui_story_5070_50700902_115_dialog_content = "아하하, 그래도 이 위험을 넘겼으니까, 앞으로는 당분간 안전할 거야.",
  ui_story_5070_50700902_116_dialog_content = "그렇게 큰 해수는 바다에서도 흔한 게 아니거든.",
  ui_story_5070_50700902_117_dialog_content = "적어도 그 녀석 영역을 벗어나기 전까진 다른 녀석이 나타나진 않을 거야.",
  ui_story_5070_50700902_118_dialog_content = "그럼 이제 기관 수룡을 다시 써도 괜찮을까?",
  ui_story_5070_50700902_119_dialog_content = "응, 최대출력으로도 문제없어.",
  ui_story_5070_50700902_120_dialog_content = "좋아, 지금 일거리가 없는 사람들을 전부 불러줘.\n이제부터 물고기를 최대한 많이 잡아둬야 하니까.",
  ui_story_5070_50700902_121_dialog_content = "이 정도 왔으면 선상의 식량도 한번 보급할 때가 됐어.",
  ui_story_5070_50700902_122_dialog_content = "아, 알겠습니다... 지금 바로 데려옵죠.",
  ui_story_5070_50700902_123_dialog_content = "어이쿠.",
  ui_story_5070_50700902_124_dialog_content = "아, 죄송합니다. 절대 고의는 아니었습니다...",
  ui_story_5070_50700902_125_dialog_content = "괜찮아요? 아니에요, 저도 신경 못 썼는걸요.",
  ui_story_5070_50700902_126_dialog_content = "근데 그건 뭐죠? 냄새가 좋은데요?",
  ui_story_5070_50700902_127_dialog_content = "아, 이, 이건... 미끼입니다. 선장님이 낚시를 하라고 하셔서...",
  ui_story_5070_50700902_128_dialog_content = "아, 그렇구나. 그렇게 냄새가 좋으면 분명히 물고기가 잘 잡히겠네요.",
  ui_story_5070_50700902_129_dialog_content = "...어라? 어디 갔지?",
  ui_story_5070_50700902_130_dialog_content = "선장님! 여기 좀 보십쇼! 잔뜩 잡혔습니다!",
  ui_story_5070_50700902_131_dialog_content = "PlayerName? 뭐 해?",
  ui_story_5070_50700902_132_dialog_content = "방금... 손 씨는?",
  ui_story_5070_50700902_133_dialog_content = "......",
  ui_story_5070_50700902_134_dialog_content = "뭐, 신경 쓸 거 없어.",
  ui_story_5070_50700902_135_dialog_content = "<size=28>미끼만 있다면 아무리 잘 숨더라도 결국엔 머리를 내밀게 될 테니까.</size>",
  ui_story_5070_50700902_136_dialog_content = "응? 뭐라고 했어?",
  ui_story_5070_50700902_137_dialog_content = "아무것도 아냐~ 그럼 우리도 가서 구경할까?",
  ui_story_5070_50700902_138_dialog_content = "그래... 어라? 근데 웬 나무판자들이 이렇게 잔뜩 낚인 거야?",
  ui_story_5070_50700902_139_dialog_content = "이것들은 침몰선의 잔해일세.",
  ui_story_5070_50700902_140_dialog_content = "허나 목재, 도료, 부식의 상태가 모두 다르지.\n한눈에 보아도 같은 배가 아님을 알 수 있소.",
  ui_story_5070_50700902_141_dialog_content = "아마도 이 근방에서 많은 배가 침몰했을 것이오.",
  ui_story_5070_50700902_142_dialog_content = "...어쩌면 배의 무덤일지도 모르죠.",
  ui_story_5070_50701001_1_dialog_content = "<color=#e8d9bb>풍덩!</color>",
  ui_story_5070_50701001_2_dialog_content = "월백 씨?!",
  ui_story_5070_50701001_3_dialog_content = "지금 월백 씨가 그냥 바다에 뛰어든 거 아니에요?!",
  ui_story_5070_50701001_4_dialog_content = "염려 말거라. 수영 실력이라면 이 뱃사람들 모두가 달려들어도\n월백 한 사람을 못 당해내니 말이다.",
  ui_story_5070_50701001_5_dialog_content = "우리는 승객으로 이 배에 탑승한 것이니, 선장을 믿고 기다려 보자꾸나.",
  ui_story_5070_50701001_6_dialog_content = "(바다에는 여러 위험이 도사리고 있어. 암초, 소용돌이, 사나운 해수...)",
  ui_story_5070_50701001_7_dialog_content = "(하지만 그것들 모두 한 가지 공통점이 있어.\n바로 여러 해역에서 수많은 배를 수장시켰다는 점이겠지.)",
  ui_story_5070_50701001_8_dialog_content = "(배가 침몰하면, 잔해들은 해류에 이리저리 떠밀리다가,\n결국 해저 깊은 곳에 모여 배의 무덤을 형성해.)",
  ui_story_5070_50701001_9_dialog_content = "(여기인가.)",
  ui_story_5070_50701001_10_dialog_content = "(내가 운항하는 배가 이 무덤에 들어서는 날이 올 줄이야.)",
  ui_story_5070_50701001_11_dialog_content = "(저기 쌓여 있는 부서진 용골들은 그 위에 기생하는 산호와 해초들에\n조금씩 침식당하다 썩어 사라지겠지.)",
  ui_story_5070_50701001_12_dialog_content = "(마치 바다가 배를 위해 장례를 치러 주는 것처럼...)",
  ui_story_5070_50701001_13_dialog_content = "(...으음? 저 배는...)",
  ui_story_5070_50701001_14_dialog_content = "기다리는 동안 선기경과 귀공에게 부탁할 일이 하나 있소.\n내 대신 배의 잔해를 건져 줄 수 있겠는가.",
  ui_story_5070_50701001_15_dialog_content = "몇몇 잔해는 눈에 익어 보이는구려.",
  ui_story_5070_50701001_16_dialog_content = "제 눈에는 다 똑같은 나무 조각으로 보이는걸요.",
  ui_story_5070_50701001_17_dialog_content = "이 세상의 모든 사물은 자세히 실펴 보면 저마다 다른 소식을 일러 주느니라.",
  ui_story_5070_50701001_18_dialog_content = "종 공에게 비할 바는 못 된다마는, 내게도 꽤 많은 것들이 보이는구나.",
  ui_story_5070_50701001_19_dialog_content = "보거라, 이 조각에는 배의 이름이 새겨져 있다.",
  ui_story_5070_50701001_20_dialog_content = "그리고 이 조각의 동그란 구멍은... 「보수공」이라는 것이야.",
  ui_story_5070_50701001_21_dialog_content = "동그란 모양으로 부서진 게 아니고요?",
  ui_story_5070_50701001_22_dialog_content = "아니다, 이는 용골을 조립할 때 일부러 파낸 것이다.",
  ui_story_5070_50701001_23_dialog_content = "안에는 엽전이나 구리거울처럼 복을 불러온다 여겨지는 물건을 넣곤 하지.",
  ui_story_5070_50701001_24_dialog_content = "그리하여 험난한 바다를 밝게 비추어, 항해가 안전하길 기원하는 게다.",
  ui_story_5070_50701001_25_dialog_content = "그러한 의미가 담겨 있을진대, 끝내 이곳에서 잔해가 된 모습을 보니...\n조금은 얄궂은지고.",
  ui_story_5070_50701001_26_dialog_content = "건져 올린 잔해 조각이 많아질수록 점점 더 여기가 위험하게 느껴지네요...",
  ui_story_5070_50701001_27_dialog_content = "종서 씨, 표정이 왜 그러세요? ...혹시 뭔가 알아내신 건가요?",
  ui_story_5070_50701001_28_dialog_content = "이 중에는 해적의 배가 있소이다.",
  ui_story_5070_50701001_29_dialog_content = "해적이요?!",
  ui_story_5070_50701001_30_dialog_content = "이 종 모, 해적과는 인연이 적지 않으니 잘못 보지는 않았을 것이오.",
  ui_story_5070_50701001_31_dialog_content = "허나, 해적들은 사시사철 바다 위를 방황하는 자들이고,\n이토록 위험한 해역에서는 보통 사람들보다 더욱 경계하였을 터이건만.",
  ui_story_5070_50701001_32_dialog_content = "바람에 쓸려 왔거나, 무언가에 쫓기기라도 한 것인지 이런 곳에서 보게 되었구려.",
  ui_story_5070_50701001_33_dialog_content = "그 추측도 어째 좀 무서운데요...\n암귀랑 폭풍, 그리고 바다 괴수만 해도 이미 머리가 아픈데...",
  ui_story_5070_50701001_34_dialog_content = "이젠 해적선을 파괴한 게 뭔지, 그리고 그게 우릴 위협하진 않을지까지\n걱정해야 하는 건가요?",
  ui_story_5070_50701001_35_dialog_content = "<color=#e8d9bb>촤악──</color>",
  ui_story_5070_50701001_36_dialog_content = "월백 씨예요! 월백 씨가 올라왔어요!",
  ui_story_5070_50701001_37_dialog_content = "여기가 어디인지 알아냈어요.",
  ui_story_5070_50701001_38_dialog_content = "이 아래엔 몇 년 전 조난을 당했던 원양어선 한 척이 가라앉아 있어요.",
  ui_story_5070_50701001_39_dialog_content = "그 어선의 항로를 토대로 추측해 보면, 여긴 아마 원양과 용주 근해의 접경 수역일 거예요.",
  ui_story_5070_50701001_40_dialog_content = "그 말인즉슨...",
  ui_story_5070_50701001_41_dialog_content = "맞아요. 우린 지금 용주에서 멀지 않은 곳에 있어요.",
  ui_story_5070_50701001_42_dialog_content = "그거 진짜 다행이네요!",
  ui_story_5070_50701001_43_dialog_content = "그래도 아직 안심할 순 없어.",
  ui_story_5070_50701001_44_dialog_content = "여긴 바다에서도 유명한 죽음의 땅이야. 이 일대의 정보가 나와 있는 해도는 없어.\n그리고 여긴 신풍호의 기존 항로에도 포함돼 있지 않아.",
  ui_story_5070_50701001_45_dialog_content = "그래서 대략적인 위치를 알게 됐더라도, 배의 운항 방향을 정확히 판단하는 건 불가능해.",
  ui_story_5070_50701001_46_dialog_content = "게다가 배의 식량도 얼마 남지 않았어. 이제 더는 지체할 시간이 없어.",
  ui_story_5070_50701001_47_dialog_content = "그럼 종서 씨랑 선극 씨한테 부탁해서 동력로의 화력을 최대로 높이고,\n단숨에 이 일대를 빠져나가면 어떨까요?",
  ui_story_5070_50701001_48_dialog_content = "무리야. 이 해역 일대 곳곳에는 소용돌이가 있어.\n그랬다간 자칫하면 물밑에 있는 배의 무덤이 우리 종착지가 될 거야.",
  ui_story_5070_50701001_49_dialog_content = "그 두 사람이 있더라도 우리가 지금 궁지에 몰린 사실은 변하지 않아. 대신...",
  ui_story_5070_50701001_50_dialog_content = "대신...?",
  ui_story_5070_50701001_51_dialog_content = "신풍호가 항로를 이탈했다는 사실을 가장 먼저 발견하고,\n대책을 세워 둔 사람이 있다면 얘기가 다르지.",
  ui_story_5070_50701001_52_dialog_content = "그걸 가장 먼저 발견한 사람이라면... 선극 씨 말인가요?",
  ui_story_5070_50701001_53_dialog_content = "......",
  ui_story_5070_50701001_54_dialog_content = "아이참, 다들 그런 눈으로 보시면 곤란해요.",
  ui_story_5070_50701001_55_dialog_content = "저한테 방법이 하나 있는 건 맞아요. 하지만...",
  ui_story_5070_50701001_56_dialog_content = "그건 목숨을 건 도박이나 다름없거든요.",
  ui_story_5070_50701001_57_dialog_content = "지금 우린 위험한 상황에 처해 있지만, 다행히도 신풍호에 의지해서\n조금씩 나아갈 방향을 찾아가고 있어요.",
  ui_story_5070_50701001_58_dialog_content = "하지만 제 방법을 사용했다가 실패한다면, 이 신풍호마저 송두리째 잃게 될 거예요.",
  ui_story_5070_50701001_59_dialog_content = "그럼 우리 모두 자연스레 물고기 밥이 되겠죠.",
  ui_story_5070_50701001_60_dialog_content = "그러니 도저히 어쩔 수 없는 상황이 아니라면,\n그런 큰 위험이 있는 방법을 권하고 싶진 않네요.",
  ui_story_5070_50701001_61_dialog_content = "선장님! 선장님! 큰일입니다! 전방에 안개가 끼기 시작했습니다!",
  ui_story_5070_50701001_62_dialog_content = "주변이 점점 보이지 않습니다. 이를 어찌하면 좋겠습니까?",
  ui_story_5070_50701001_63_dialog_content = "하필이면 이 해역에서 안개가 짙어지다니, 눈을 감은 채 외줄 타기를 하는 격이네.",
  ui_story_5070_50701001_64_dialog_content = "선극 소저, 지금이 바로 그 「도저히 어쩔 수 없는 상황」이야.",
  ui_story_5070_50701001_65_dialog_content = "...좋아.",
  ui_story_5070_50701001_66_dialog_content = "처음 신풍호에 승선할 때, 난 화물창에 특별한 물건을 하나 보관해 뒀어.",
  ui_story_5070_50701001_67_dialog_content = "그건 모든 기관을 조종할 수 있고, 힘을 공급해 줄 수 있어.",
  ui_story_5070_50701001_68_dialog_content = "불게, 수룡, 그리고 심지어 신풍호의 동력원인 기관로까지...",
  ui_story_5070_50701001_69_dialog_content = "그걸 구동한다면 이 모든 것들이 전에 없던 효율을 낼 수 있어.",
  ui_story_5070_50701001_70_dialog_content = "하지만 그건 본디 다루기가 힘든 데다가, 불안정하기까지 해.",
  ui_story_5070_50701001_71_dialog_content = "기록에 따르면 수차례 진행됐던 시험 운전에선 힘을 너무 과도하게 공급한 나머지...",
  ui_story_5070_50701001_72_dialog_content = "기관의 부품들이 힘을 감당하지 못하고 자폭했다고 해.",
  ui_story_5070_50701001_73_dialog_content = "그러니까 정말 그걸 사용해야 한다면, 우선 내가 물속에서 시험 작동을 해 봐야겠어.",
  ui_story_5070_50701001_74_dialog_content = "그리고 신풍호도 최소한 그게 작동할 때 발생하는 충격을\n감당할 수 있을 정도까지 보수와 개조를 진행해야 해.",
  ui_story_5070_50701001_75_dialog_content = "그렇지 않으면 이 방법은 난관을 돌파할 희망이 아니라,\n우리 모두의 저승행을 재촉할 부적이 될 테니까.",
  ui_story_5070_50701001_76_dialog_content = "조금 이따가 내가 신풍호에 보관 중인 부품 목록을 줄게.\n손을 봐야 할 부분들이 있다면 얼마든지 진행하도록 해.",
  ui_story_5070_50701001_77_dialog_content = "선원들에게도 당신 지시를 따르라고 전해둘 테니까.",
  ui_story_5070_50701001_78_dialog_content = "종 모의 화능술이 미약하게나마 도움이 될지도 모르오.",
  ui_story_5070_50701001_79_dialog_content = "하면 나는 방금 잡은 물고기들을 정리하마.\n오늘은 모두가 생선에 질리지 않을 새 요리법을 써 보아야겠구나.",
  ui_story_5070_50701001_80_dialog_content = "나도... 뭔가 도울 일이 있을까?",
  ui_story_5070_50701001_81_dialog_content = "PlayerName, 난 화물창에 물건 찾으러 갈 거야.",
  ui_story_5070_50701001_82_dialog_content = "당신은 나 대신 꼬맹이한테 가서 열독을 막을 약 좀 얻어다 줄 수 있을까?",
  ui_story_5070_50701001_83_dialog_content = "그러니까... 지금 선극이 배에 화염정을 데리고 탔단 소리야?!",
  ui_story_5070_50701001_84_dialog_content = "어쩐지 배에서 계속 화염정 냄새가 나길래, 내 코가 이상해진 줄 알았다구.",
  ui_story_5070_50701001_85_dialog_content = "역시 그 녀석 짓이었구나? 화염정이라니... 너무 위험하잖아...",
  ui_story_5070_50701001_86_dialog_content = "복존자께서 가르쳐 주신 적 있어.\n그 태고의 영물이 남긴 유산은 옛적엔 음양을 정하고 밤낮을 나눌 수 있었대!",
  ui_story_5070_50701001_87_dialog_content = "뭐, 됐어. 이제 와서 배에서 내리라고 할 수도 없는 노릇이니까.",
  ui_story_5070_50701001_88_dialog_content = "여기 약 받아. 그리고 그 녀석한텐 절대 이 배를 터트리지 말라고 전해줘.",
  ui_story_5070_50701001_89_dialog_content = "선극 씨, 약 받아 왔어.",
  ui_story_5070_50701001_90_dialog_content = "근데 선극 씨가 아까 특별한 무언가라고 했던 그건 대체 뭐야?",
  ui_story_5070_50701001_91_dialog_content = "선극 씨 얘길 리청한테 말해줬더니 듣자마자 엄청 호들갑을 떨더라고.",
  ui_story_5070_50701001_92_dialog_content = "아까 다른 사람들도 뭔가 아는 눈치던데, 나만 뭐가 뭔지 하나도 모르겠는 거야?",
  ui_story_5070_50701001_93_dialog_content = "아하하, 그 얘긴 오히려 PlayerName 당신이 할 말이 아닐걸?",
  ui_story_5070_50701001_94_dialog_content = "이 배에 있는 사람 중에서 그걸 가장 잘 이해할 수 있는 사람은\n어쩌면 나보다 당신일지도 모르거든.",
  ui_story_5070_50701001_95_dialog_content = "뭐? 내가?",
  ui_story_5070_50701001_96_dialog_content = "이따 내가 꺼냈을 때 한 번 보면 금방 알게 될 거야.",
  ui_story_5070_50701001_97_dialog_content = "꺼낸다고? 어디서?",
  ui_story_5070_50701001_98_dialog_content = "아, 그나저나 전부터 물어보고 싶었는데,\n화물창에 왜... 나무로 만든 소가 잔뜩 있는 거야?",
  ui_story_5070_50701001_99_dialog_content = "그건 목우유마라고 해. 용주에서 가장 흔히 볼 수 있는 기관 중 하나야.\n아주 오래전부터 전해져 내려왔고 말이야.",
  ui_story_5070_50701001_100_dialog_content = "주로 화물을 운송할 때 사용하는 건데, 난 그 안에 짐을 넣어 다니는 것도 꽤 편하더라고.",
  ui_story_5070_50701001_101_dialog_content = "이렇게 열기만 하면 물건을 쉽게 꺼낼 수 있어.",
  ui_story_5070_50701001_102_dialog_content = "안은 공간이 꽤 넓은데? 조금 끼긴 하겠지만 한 사람이 누울 정돈 되겠어.",
  ui_story_5070_50701001_103_dialog_content = "한번 해 볼래?",
  ui_story_5070_50701001_104_dialog_content = "아니야! 됐어! 난 화물이 되고 싶은 생각은 없다고.",
  ui_story_5070_50701001_105_dialog_content = "하하, 그럴 것 같았어.",
  ui_story_5070_50701001_106_dialog_content = "자, 그럼 오늘의 주인공을 만나 보실까?",
  ui_story_5070_50701001_107_dialog_content = "이 작은 게?",
  ui_story_5070_50701001_108_dialog_content = "이걸 얕보면 곤란해.",
  ui_story_5070_50701001_109_dialog_content = "내가 소속된 유파는 「건운종」이라고 하는데,\n업나라는 물론이고 용주에서도 손꼽히는 기관술의 종문이거든.",
  ui_story_5070_50701001_110_dialog_content = "수천수백 년 동안 기술을 이어오고 있고, 종문에서 보유하고 있는 보물도 수없이 많아.",
  ui_story_5070_50701001_111_dialog_content = "하지만 그 많은 보물을 전부 더한다 해도, 이것보다 귀한 건 하나도 없을걸.",
  ui_story_5070_50701001_112_dialog_content = "내가 바다 건너 아스트라 대륙까지 갔던 가장 중요한 목적은...",
  ui_story_5070_50701001_113_dialog_content = "바로 수년 전 이역에서 유실된 이 귀한 보물을 찾기 위해서였어.",
  ui_story_5070_50701001_114_dialog_content = "이 보물은 「촉음화」라고 해.",
  ui_story_5070_50701001_115_dialog_content = "아스트라 대륙 사람들의 방식대로 말하자면, 이건... 아주 귀중한 고대 유물이야.",
  ui_story_5070_50701001_116_dialog_content = "고대 유물?!",
  ui_story_5070_50701001_117_dialog_content = "이게 어떤 힘이 있는지 보고 싶어?",
  ui_story_5070_50701001_118_dialog_content = "신풍호에서 시험하기엔 좀 위험하니까, 조각배를 빌려서 좀 떨어진 곳에서 해 보자.",
  ui_story_5070_50701001_119_dialog_content = "아득한 과거에 만물을 호령했던, 진짜 하늘의 작품을 한번 감상해 보자고.",
  ui_story_5070_50701002_1_dialog_content = "역시 고대의 보물답네. 예상보다 훨씬 강력하잖아.",
  ui_story_5070_50701002_2_dialog_content = "PlayerName 당신도 감응 능력으로 봤겠지? 어땠어?",
  ui_story_5070_50701002_3_dialog_content = "...정말 놀라웠어.",
  ui_story_5070_50701002_4_dialog_content = "루미나를 동력으로 움직이는 수많은 기관수들을 가동한 것도 모자라서...",
  ui_story_5070_50701002_5_dialog_content = "주변 일대의 모든 수분을 증발시켜서 일대를 진공 상태로 만들어 버렸잖아.",
  ui_story_5070_50701002_6_dialog_content = "게다가 감응으로 느낀 건데, 그건 다른 불꽃들보다 더 응축돼 있어서, 마치...",
  ui_story_5070_50701002_7_dialog_content = "태양을 그대로 압축한 것처럼 말이지?",
  ui_story_5070_50701002_8_dialog_content = "맞아... 아니, 잠깐만, 그거 내가 했던 말이잖아!",
  ui_story_5070_50701002_9_dialog_content = "...설마... 그날 배에서 폭발을 일으켰던 게... 그 촉음화였어?!",
  ui_story_5070_50701002_10_dialog_content = "아이참, 들켜버렸네.",
  ui_story_5070_50701002_11_dialog_content = "선극 씨가 감응해 봐도 된다고 했잖아! 이번엔 전부 선극 씨가 시킨 대로만 했어!",
  ui_story_5070_50701002_12_dialog_content = "직접 보는 게 듣는 것보다 훨씬 낫거든~ 당신도 그렇게 생각하지 않아?",
  ui_story_5070_50701002_13_dialog_content = "...리청이 아까 그렇게 열을 낸 이유가 다 있었네.",
  ui_story_5070_50701002_14_dialog_content = "배에 그렇게 위험한 게 있을 거라고 누가 상상이나 했겠냐고.",
  ui_story_5070_50701002_15_dialog_content = "잘 봉인해서 가져온 거니까, 이치에 따르면 전혀 위험하지 않아.",
  ui_story_5070_50701002_16_dialog_content = "불이 났던 그날은... 누가 고의로 봉인을 풀었던 거야.",
  ui_story_5070_50701002_17_dialog_content = "난 이걸 배에 몰래 가지고 왔어.",
  ui_story_5070_50701002_18_dialog_content = "내가 인화성, 폭발성 물질이라고 주의를 줬던 목 선장조차 이 물건의 진짜 정체는 모른다고.",
  ui_story_5070_50701002_19_dialog_content = "그런데 누군가 이 물건의 존재를 미리 알고, 접근하려고 했던 거야.",
  ui_story_5070_50701002_20_dialog_content = "아... 내가 전에 본 것 같다는 그 사람...!",
  ui_story_5070_50701002_21_dialog_content = "아마 그렇겠지.",
  ui_story_5070_50701002_22_dialog_content = "그럼... 얼른 다른 사람들한테도 알려야 하는 거 아냐?",
  ui_story_5070_50701002_23_dialog_content = "마침 촉음화의 시험도 성공했겠다, 신풍호도 여기서 금방 나갈 수 있을 거잖아.",
  ui_story_5070_50701002_24_dialog_content = "그럼 지금 바로 그 범인을 잡아서...",
  ui_story_5070_50701002_25_dialog_content = "난 성공했다고 한 적 없어.",
  ui_story_5070_50701002_26_dialog_content = "뭐? 그치만 기관수들이 다 문제없이 작동했잖아?",
  ui_story_5070_50701002_27_dialog_content = "촉음화가 동력원으로서 지닌 구동력은 의심의 여지도 없지만,\n그렇게 가동했던 기관수들이 지금은 어떻게 됐어?",
  ui_story_5070_50701002_28_dialog_content = "...전부 조각나서 바다로 떨어졌지.",
  ui_story_5070_50701002_29_dialog_content = "기관수가 그렇게 큰 편도 아니었고, 내가 어느 정도는 핵심 부품을\n제어할 수 있는 상황에서도 이런 일이 벌어졌어.",
  ui_story_5070_50701002_30_dialog_content = "신풍호의 선체 강도라면, 지금 이 배에 있는 모든 부품 재고를 써서 보강하더라도...",
  ui_story_5070_50701002_31_dialog_content = "촉음화의 최대 출력을 감당하는 건 어려울지도 몰라.",
  ui_story_5070_50701002_32_dialog_content = "그럼 선극 씨한테도 아무런 방법이 없는 거야?",
  ui_story_5070_50701002_33_dialog_content = "...그렇진 않아.",
  ui_story_5070_50701002_34_dialog_content = "대신 그 전에 PlayerName 당신한테 부탁할 게 하나 있어.",
  ui_story_5070_50701002_35_dialog_content = "시험 가동에 실패한 것도, 누군가 촉음화를 노리고 있다는 것도 일단은 비밀로 해 줘.",
  ui_story_5070_50701002_36_dialog_content = "그거야 가능하지만... 그럼 우린 이제 어떡해?",
  ui_story_5070_50701002_37_dialog_content = "기다려야지.",
  ui_story_5070_50701002_38_dialog_content = "<color=#e8d9bb>다음 날</color>",
  ui_story_5070_50701002_39_dialog_content = "다들 와서 도면 한 장씩 받아 가. 표시된 위치로 가서 일 시작하면 돼.",
  ui_story_5070_50701002_40_dialog_content = "이게 무슨 도면인데요?",
  ui_story_5070_50701002_41_dialog_content = "이 도면은...",
  ui_story_5070_50701002_42_dialog_content = "휴, 내가 이날 이때까지 배를 타면서, 이런 건 살다 살다 처음 보는군...",
  ui_story_5070_50701002_43_dialog_content = "갑판에 있는 커다란 구멍을 수리하지 않는다는 건 그렇다 쳐도,\n그걸 일부러 더 크게 만들겠다고?",
  ui_story_5070_50701002_44_dialog_content = "신풍호의 중추까지 드러나게 생겼는데, 일을 이런 식으로 하는 경우가 어디 있어?\n...자넨 어떻게 생각하나?",
  ui_story_5070_50701002_45_dialog_content = "저...전 잘 모르겠는데요...",
  ui_story_5070_50701002_46_dialog_content = "뭘 신경을 그리 쓰는가? 우리보다 선극 님이 어련히 잘 아시겠지.",
  ui_story_5070_50701002_47_dialog_content = "얼른 일이나 끝내자고. 다 하고 나면 분명히 여기서 나갈 수 있을 거야.",
  ui_story_5070_50701002_48_dialog_content = "<color=#e8d9bb>셋째 날</color>",
  ui_story_5070_50701002_49_dialog_content = "고기 잡으러 가야 하니까 몇 명은 날 따라와.",
  ui_story_5070_50701002_50_dialog_content = "으, 벌써 며칠째 생선만 먹고 있잖아.\n엊그제부턴 조미료도 다 떨어지는 바람에 맛이... 참...",
  ui_story_5070_50701002_51_dialog_content = "개조 작업이 끝날 때까지만 더 버티자고.",
  ui_story_5070_50701002_52_dialog_content = "<color=#e8d9bb>다섯째 날</color>",
  ui_story_5070_50701002_53_dialog_content = "고기 잡는 곳 안개가 점점 짙어져서 이러다간 고기도 못 잡게 생겼어.",
  ui_story_5070_50701002_54_dialog_content = "개조 작업은 다 끝난 거 아니었나? 선극 님은 왜 아무 말씀도 없는 건지 원...",
  ui_story_5070_50701002_55_dialog_content = "쉿... 자네만 알고 있어... 손 씨가 그러던데, 우리가 한 개조 작업은 다 헛수고래.",
  ui_story_5070_50701002_56_dialog_content = "선극 님이 매일 길을 찾겠다고 조각배를 타고 나가시는데,\n사실은 그게 다 어떻게 해야 할지 몰라서 그러는 거래!",
  ui_story_5070_50701002_57_dialog_content = "그게 무슨 소리인가?! 손 씨는 또 왜 그런 소리를 하고 다녀?!\n선장님 귀에 들어가기라도 했다간...",
  ui_story_5070_50701002_58_dialog_content = "앗! PlayerName 대인! PlayerName 대인!",
  ui_story_5070_50701002_59_dialog_content = "며칠간 계속 선극 님이랑 배를 타고 나가지 않으셨습니까?\n저희가 어떻게 이 해역에서 나갈지 뭐 좀 들으신 거 없습니까?",
  ui_story_5070_50701002_60_dialog_content = "아, 그게... 방법은 있긴 한데, 지금은 이 말밖에 못 하겠네요.\n저기... 전 선극 씨한테 물건 좀 갖다줘야 해서 먼저 실례할게요!",
  ui_story_5070_50701002_61_dialog_content = "휴우...",
  ui_story_5070_50701002_62_dialog_content = "PlayerName, 이거 좀 봐.\n네가 얘기해 준 콜로서스랑 비슷한 구조로 모형을 만들어 봤어.",
  ui_story_5070_50701002_63_dialog_content = "응? 표정 보니까 오기 전에 또 선원들이 귀찮게 굴었구나?",
  ui_story_5070_50701002_64_dialog_content = "하하... 벌써 여기서 며칠이나 있었으니까. 다들 빨리 나가고 싶어서 예민해진 것 같아.",
  ui_story_5070_50701002_65_dialog_content = "이 모형... 음, 어째 콜로서스보단 날개 달린 신풍호처럼 생겼는데? 어디 보자...",
  ui_story_5070_50701002_66_dialog_content = "PlayerName, 당신 나한테 정말 뭐 물어볼 거 없어?",
  ui_story_5070_50701002_67_dialog_content = "물어볼 거라니?",
  ui_story_5070_50701002_68_dialog_content = "왜 이유도 설명 안 하고 당신한테 비밀을 지키라고 했는지.",
  ui_story_5070_50701002_69_dialog_content = "다른 사람들한테는 이것저것 개조하라고 시켜 놓고,\n왜 정작 자기는 하루 종일 조각배에 앉아서 사람들 문제를 외면하는지.",
  ui_story_5070_50701002_70_dialog_content = "이젠 나 자신조차 내가 허장성세를 부리는 건 아닌지 의심스러울 지경인데.",
  ui_story_5070_50701002_71_dialog_content = "왜 PlayerName 당신은 날 그렇게나 믿어 주는 거야?",
  ui_story_5070_50701002_72_dialog_content = "난 선극 씨를 믿는 게 아냐.",
  ui_story_5070_50701002_73_dialog_content = "역시 그렇겠지...",
  ui_story_5070_50701002_74_dialog_content = "기관술을 믿는 거지.",
  ui_story_5070_50701002_75_dialog_content = "...뭐?",
  ui_story_5070_50701002_76_dialog_content = "그때 갑자기 나타난 기관수들을 상대하는 건 확실히 막막한 일이었어.",
  ui_story_5070_50701002_77_dialog_content = "그치만 우리가 처음 만났을 땐, 구리 잠자리가 내 편지를 잡아줬잖아.",
  ui_story_5070_50701002_78_dialog_content = "그리고 불게는 동력로를 가동해 주고, 수룡은 불을 꺼 줬고...",
  ui_story_5070_50701002_79_dialog_content = "그렇게 난 어려움이 생길 때마다 몇 번이고 기관들의 도움을 받았어.",
  ui_story_5070_50701002_80_dialog_content = "선극 씨가 그랬었지? 기관술은 변화무쌍하거나 만능인 기술이 아니라고.",
  ui_story_5070_50701002_81_dialog_content = "난 기관술을 믿어. 그리고 선극 씨는 기관술에 대해 절대로 거짓말을 하지 않아.",
  ui_story_5070_50701002_82_dialog_content = "그러니까 난 선극 씨가 우릴 무사히 용주에 데려가 줄 방법이 있다는 것도 믿어.",
  ui_story_5070_50701002_83_dialog_content = "그랬구나.",
  ui_story_5070_50701002_84_dialog_content = "그거 정말 전혀 반박할 수가 없는 논점이네.",
  ui_story_5070_50701002_85_dialog_content = "PlayerName 당신이 그렇게까지 말했는데...",
  ui_story_5070_50701002_86_dialog_content = "기관술이 어디까지 해낼 수 있는지 보여주지 않으면,\n나도 기교사로서 직무 태만이겠지?",
  ui_story_5070_50701002_87_dialog_content = "응, 기대하고 있어.\n근데 솔직히 나도 아까 선극 씨가 말한 것들이 안 궁금한 건 아니야.",
  ui_story_5070_50701002_88_dialog_content = "선극 씨... 대체 뭘 기다리고 있는 거야?",
  ui_story_5070_50701002_89_dialog_content = "...사실...",
  ui_story_5070_50701002_90_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5070_50701002_91_dialog_content = "저거 신풍호에서 나는 소리야? 왜 갑자기 나팔을 분 거지?",
  ui_story_5070_50701002_92_dialog_content = "바다에서 배끼리 연락할 때 쓰는 신호야.",
  ui_story_5070_50701002_93_dialog_content = "그럼 다른 배가 나타났다는 거야?!",
  ui_story_5070_50701002_94_dialog_content = "<color=#e8d9bb>얼마 전</color>",
  ui_story_5070_50701002_95_dialog_content = "구, 월백, 어서 이리 와 보거라.",
  ui_story_5070_50701002_96_dialog_content = "저 너머에 보이는 것은 배가 아니더냐?",
  ui_story_5070_50701002_97_dialog_content = "전하, 난간에 너무 가까이 붙어 계시면 안 됩니다. 뒤로 조금 물러나 주십시오.",
  ui_story_5070_50701002_98_dialog_content = "구야, 지금 그게 중한 것이 아니지 않느냐.",
  ui_story_5070_50701002_99_dialog_content = "어느 때라도 전하의 안위보다 중한 것은 없습니다. 부디 조심하여 주십시오.",
  ui_story_5070_50701002_100_dialog_content = "갑판 위의 모습은 잘 보이지 않지만, 상선으로 보이는 배 한 척이\n확실히 이쪽으로 오고 있군요.",
  ui_story_5070_50701002_101_dialog_content = "이 해역에서 다른 배와 마주치게 될 줄은 몰랐는데 말이지요.",
  ui_story_5070_50701002_102_dialog_content = "연락을 취할 생각입니까? 상대의 물자가 충분한지 알 수 없지 않습니까.\n만약 그렇지 않다면...",
  ui_story_5070_50701002_103_dialog_content = "좌우간 지금은 피하기엔 너무 늦었어요.",
  ui_story_5070_50701002_104_dialog_content = "나팔을 불어 상대의 반응부터 확인해 보기로 해요.",
  ui_story_5070_50701002_105_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5070_50701002_106_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5070_50701002_107_dialog_content = "반응을 보였어!",
  ui_story_5070_50701002_108_dialog_content = "저쪽도 우리처럼 여기 발이 묶인 걸까?\n잘됐네, 같이 여기서 빠져나갈 방법을 찾으면 되잖아.",
  ui_story_5070_50701002_109_dialog_content = "음식이나 물을 교환할 수 있을지도 몰라.",
  ui_story_5070_50701002_110_dialog_content = "그럼 얼른 신풍호로 돌아가자. 할 말 있으면 빨리하고.",
  ui_story_5070_50701002_111_dialog_content = "저쪽 배가 보여. 저 배도 신풍호 쪽으로 접근하고 있어.",
  ui_story_5070_50701002_112_dialog_content = "어...? 저 배... 속도가 좀 빠른 것 같지 않아?",
  ui_story_5070_50701002_113_dialog_content = "속도를 줄이기는커녕, 점점 빨라지는데?!",
  ui_story_5070_50701002_114_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_5070_50701002_115_dialog_content = "배가... 신풍호를 들이받았잖아?!",
  ui_story_5070_50701002_116_dialog_content = "아니...",
  ui_story_5070_50701002_117_dialog_content = "저건 해적선이야!",
  ui_story_5070_50701002_118_dialog_content = "PlayerName, 서두르자! 신풍호가 위험해!",
  ui_story_5070_50701101_1_dialog_content = "이 오만방자한 소인배들이 감히 구를...!",
  ui_story_5070_50701101_2_dialog_content = "멈추세요!",
  ui_story_5070_50701101_3_dialog_content = "<color=#e8d9bb>화르륵!</color>",
  ui_story_5070_50701101_4_dialog_content = "<color=#e8d9bb>공격은 단당의 발치 쪽 갑판에 명중해, 갑판을 불태우고 커다란 구멍을 만들었다.</color>",
  ui_story_5070_50701101_5_dialog_content = "......",
  ui_story_5070_50701101_6_dialog_content = "공주님, 소인 외람된 줄은 아오나 감히 조언 한마디 하겠습니다.",
  ui_story_5070_50701101_7_dialog_content = "비록 일시의 구설로 마음은 통쾌할지 몰라도,\n바다에서는 조심스러운 이가 오래 누비는 법입니다.",
  ui_story_5070_50701101_8_dialog_content = "단당 씨가 공격당한 것 같아! 빨리 올라가야 해!",
  ui_story_5070_50701101_9_dialog_content = "잠깐만, 저쪽은 우리 신분을 알고 있어.\n그러니까 사람들한테 진짜로 무슨 짓을 하진 못할 거야.",
  ui_story_5070_50701101_10_dialog_content = "하지만 우린 저쪽에 대해 아는 게 없어. 이대로 올라가면 곧바로 잡힐 뿐이야.",
  ui_story_5070_50701101_11_dialog_content = "일단 올라가지 말고 여기서 상황을 지켜보자.",
  ui_story_5070_50701101_12_dialog_content = "음... 아까 단당 씨한테 말한 그 사람, 목소리가 왠지 좀 익숙했어.",
  ui_story_5070_50701101_13_dialog_content = "손 씨야.",
  ui_story_5070_50701101_14_dialog_content = "손 씨?!",
  ui_story_5070_50701101_15_dialog_content = "쉿.",
  ui_story_5070_50701101_16_dialog_content = "계속 들어 보자.",
  ui_story_5070_50701101_17_dialog_content = "당신, 진짜 손 씨가 아니구나.",
  ui_story_5070_50701101_18_dialog_content = "하, 이건 그저 껍데기일 뿐이야.",
  ui_story_5070_50701101_19_dialog_content = "허나 너희 눈에는 그렇게밖에 보이지 않겠지.",
  ui_story_5070_50701101_20_dialog_content = "어, 어떻게 해적이랑 결탁할 수가 있는 거냐!",
  ui_story_5070_50701101_21_dialog_content = "린 가문이 우리한테 베푼 은혜도 잊은 것이냐! 이 배은망덕한 배신자가...",
  ui_story_5070_50701101_22_dialog_content = "얌전히 있어!",
  ui_story_5070_50701101_23_dialog_content = "저 아래 구 소저와 저승길 동무가 되고 싶지 않다면 가만히 있는 게 좋을걸.",
  ui_story_5070_50701101_24_dialog_content = "이 배에서 무예가 가장 출중한 이도 한발 앞서 가버렸잖아?",
  ui_story_5070_50701101_25_dialog_content = "발악의 여지가 없는 건 너희가 봐도 알겠지.",
  ui_story_5070_50701101_26_dialog_content = "모두 네놈이 비열한 술수를 부린 탓이 아니더냐!",
  ui_story_5070_50701101_27_dialog_content = "그 괴이한 빛이 없었거든 구가 너희 같은 불한당 따위에게 애먹었을 성싶으냐!",
  ui_story_5070_50701101_28_dialog_content = "불한당? 전하, 말을 신중히 하셔야지요.",
  ui_story_5070_50701101_29_dialog_content = "저것은 이 신풍호에 필적하는... 아니, 이것보다 훨씬 더 훌륭한 작품이니까요!",
  ui_story_5070_50701101_30_dialog_content = "흥! 허튼소리는 잘도 하는구나.",
  ui_story_5070_50701101_31_dialog_content = "고작 네놈들 배에 숨겨 두었다 기습이나 꾀하는 것을 보면,\n필경 네놈들처럼 시답잖은 물건이겠지.",
  ui_story_5070_50701101_32_dialog_content = "(그래, 공주 전하께선 고의로 저자를 자극하고 계셔.)",
  ui_story_5070_50701101_33_dialog_content = "(구 소저가 돌아오기 전까지 최대한 많은 정보를 알아내야 해.)",
  ui_story_5070_50701101_34_dialog_content = "게다가 당신 부하들이 배에 오르자마자 한 짓이라곤 물건을 훔치고,\n사람들을 붙잡은 것뿐이잖아.",
  ui_story_5070_50701101_35_dialog_content = "무리 지어 고작 몸이 불편한 사람과 어린아이나 괴롭히는 겁쟁이들이라니.",
  ui_story_5070_50701101_36_dialog_content = "그럼 지금부터 양동작전을 써 보자.",
  ui_story_5070_50701101_37_dialog_content = "저 위험한 빛을 내뿜는 물건은 아마 출력이 상당히 높은 기관일 거야.",
  ui_story_5070_50701101_38_dialog_content = "내가 가서 확인해 봐야겠어.",
  ui_story_5070_50701101_39_dialog_content = "그럼 난?",
  ui_story_5070_50701101_40_dialog_content = "당신은 이 조각배에 남아서 계속 신풍호의 상황을 엿들어 줘.",
  ui_story_5070_50701101_41_dialog_content = "안 들키게 잘 숨어. 그럼 나 먼저...",
  ui_story_5070_50701101_42_dialog_content = "그게 무슨 양동작전이야?",
  ui_story_5070_50701101_43_dialog_content = "?",
  ui_story_5070_50701101_44_dialog_content = "이건 그냥 날 안전한 데 두고, 선극 씨는 혼자 위험을 무릅쓰는 거잖아.",
  ui_story_5070_50701101_45_dialog_content = "하지만...",
  ui_story_5070_50701101_46_dialog_content = "시간이 없어.",
  ui_story_5070_50701101_47_dialog_content = "난 신풍호로 돌아갈게. 내가 선극 씨나 다른 사람들처럼 싸울 순 없지만...",
  ui_story_5070_50701101_48_dialog_content = "올라가면 내가 도움이 될 만한 게 분명히 있을 거야.",
  ui_story_5070_50701101_49_dialog_content = "만약에 들킨다 해도, 대신 선극 씨한테 시간을 벌어줄 수 있을지도 모르잖아.",
  ui_story_5070_50701101_50_dialog_content = "이래야 양동작전이지.",
  ui_story_5070_50701101_51_dialog_content = "그럼... 내가 그렇겐 못 하겠다고 하면?",
  ui_story_5070_50701101_52_dialog_content = "그럼 선극 씨가 간 뒤에 나 혼자 몰래 올라가지 뭐.",
  ui_story_5070_50701101_53_dialog_content = "항상 제 발로 위험에 몸을 던지는 게 너희 아이테르의 습성은 아니겠지?",
  ui_story_5070_50701101_54_dialog_content = "그럼 누구든지 앞에서 막아주고, 혼자 뭐든 해결하려고 하는 게 기교사의 습성이야?",
  ui_story_5070_50701101_55_dialog_content = "...아무래도 우린 피차일반인 모양이네.",
  ui_story_5070_50701101_56_dialog_content = "PlayerName 당신은 날 믿어 줬지만...",
  ui_story_5070_50701101_57_dialog_content = "난 PlayerName 당신을 믿어 주지 못했어. 그건 확실히 공평한 처사가 아냐.",
  ui_story_5070_50701101_58_dialog_content = "그럼... 성공을 빌게.",
  ui_story_5070_50701102_1_dialog_content = "(강제 감응! 잊고 있던 걸 생각해 내 봐!)",
  ui_story_5070_50701102_2_dialog_content = "아! 그러고 보니까 두목이 아직 나한테 돈도 안 줬잖아? 가서 말 좀 해 봐야겠어...",
  ui_story_5070_50701102_3_dialog_content = "<color=#e8d9bb>뚜벅, 뚜벅, 뚜벅...</color>",
  ui_story_5070_50701102_4_dialog_content = "(좋아, 이 용주 해적들은 감응 능력에 대해 잘 모르고, 경험해 본 적도 없어...)",
  ui_story_5070_50701102_5_dialog_content = "(이런 식으로 슬쩍 감응해서 다른 곳으로 가라는 암시를 주면 되겠어...)",
  ui_story_5070_50701102_6_dialog_content = "뭐야, 입구 쪽 녀석은 어디 갔어? 순찰 안 돌고 뭐 하는 거야?",
  ui_story_5070_50701102_7_dialog_content = "우리 임무만 지장 없으면 됐지, 신경 써서 뭐 해?",
  ui_story_5070_50701102_8_dialog_content = "게다가 고작 앉은뱅이랑 꼬맹이 하나 지키는 일이잖아.\n철창에 가둬 두기까지 했는데 뭘 그렇게 긴장하고 그래?",
  ui_story_5070_50701102_9_dialog_content = "(해적들이 엄청 많네! 저기 기관 철창에 갇혀 있는 건... 종서 씨랑 리청이야!)",
  ui_story_5070_50701102_10_dialog_content = "(응? 리청 쟤 뭐 하는 거야?)",
  ui_story_5070_50701102_11_dialog_content = "(킁킁, 킁킁.)",
  ui_story_5070_50701102_12_dialog_content = "(이 냄새... PlayerName 냄새야!)",
  ui_story_5070_50701102_13_dialog_content = "(여기야! 여길 봐! 그래! 눈 마주쳤다!)",
  ui_story_5070_50701102_14_dialog_content = "야오옹~",
  ui_story_5070_50701102_15_dialog_content = "너 뭐 하냐? 고양이 소리는 왜 내?",
  ui_story_5070_50701102_16_dialog_content = "심심해서 그래. 아니면 산책 좀 하게 내보내 주든가.",
  ui_story_5070_50701102_17_dialog_content = "(왜 저러는 거지?)",
  ui_story_5070_50701102_18_dialog_content = "야오옹~",
  ui_story_5070_50701102_19_dialog_content = "(아, 작은꼬리다! 그리고 종서 씨 옆에는... 일심, 일몽, 일낙이라고 했었나?)",
  ui_story_5070_50701102_20_dialog_content = "(다들 어디서 나타난 거야?)",
  ui_story_5070_50701102_21_dialog_content = "방금 입구 쪽에 뭔가 움직이지 않았어?",
  ui_story_5070_50701102_22_dialog_content = "있긴 뭐가 있어. 착각이겠지.",
  ui_story_5070_50701102_23_dialog_content = "아깐 저 앉은뱅이 어디서 본 것 같다더니, 이젠 문 쪽에 뭐가 있다질 않나,\n너 오늘 왜 그러냐?",
  ui_story_5070_50701102_24_dialog_content = "가서 보고 와야겠어.",
  ui_story_5070_50701102_25_dialog_content = "(!!!)",
  ui_story_5070_50701102_26_dialog_content = "(숨을 시간이 없어! 어떻게든 해 보는 수밖에!)",
  ui_story_5070_50701102_27_dialog_content = "(조금만 시간을 벌어 줘! 부탁해!)",
  ui_story_5070_50701102_28_dialog_content = "야옹!",
  ui_story_5070_50701102_29_dialog_content = "뭐야?!",
  ui_story_5070_50701102_30_dialog_content = "웬 들고양이야?! 저리 꺼져! 쓰읍... 이게 감히 사람을 물어?!",
  ui_story_5070_50701102_31_dialog_content = "(지금이야! 방 안에 있는 모든 사람을...)",
  ui_story_5070_50701102_32_dialog_content = "(강제 감응으로 자극하는 거야!)",
  ui_story_5070_50701102_33_dialog_content = "으윽, 왜 갑자기 머리가 아픈 거지?!",
  ui_story_5070_50701102_34_dialog_content = "고, 고양이가 내 얼굴을 긁었어!",
  ui_story_5070_50701102_35_dialog_content = "PlayerName! 일단 종서 형님부터 구해 줘!",
  ui_story_5070_50701102_36_dialog_content = "야오옹~",
  ui_story_5070_50701102_37_dialog_content = "열쇠를 물어왔구나? 고마워, 작은꼬리.",
  ui_story_5070_50701102_38_dialog_content = "종서 씨, 조금만 기다리세요. 금방 열어 드릴게요.",
  ui_story_5070_50701102_39_dialog_content = "고맙소, 허나 종 모는 무사하니 조급해할 필요는 없소.",
  ui_story_5070_50701102_40_dialog_content = "전 지금 조급해서 미치겠거든요?! PlayerName 넌 너무 느려! 내가 할게.",
  ui_story_5070_50701102_41_dialog_content = "리청?! 너 어떻게 나온 거야?!",
  ui_story_5070_50701102_42_dialog_content = "철창 틈이 이렇게 넓잖아, 몸만 돌리면 바로 나오지.",
  ui_story_5070_50701102_43_dialog_content = "그거 보통 사람들도 할 수 있는 건가...?",
  ui_story_5070_50701102_44_dialog_content = "당연히 못 하지. 근데 난 보통 사람이 아니거든.",
  ui_story_5070_50701102_45_dialog_content = "그럼?!",
  ui_story_5070_50701102_46_dialog_content = "내가 말 안 했었나?",
  ui_story_5070_50701102_47_dialog_content = "난 고양이야.",
  ui_story_5070_50701102_48_dialog_content = "?!",
  ui_story_5070_50701102_49_dialog_content = "정확히는 고양이형 수요령이지. 그리고 저기 작은꼬리는 내 친형이야.",
  ui_story_5070_50701102_50_dialog_content = "혀, 형이라고...?",
  ui_story_5070_50701102_51_dialog_content = "PlayerName? 왜 멍때리고 있어?",
  ui_story_5070_50701102_52_dialog_content = "아스트라 대륙에는 수요령이 존재하지 않으니, 놀라는 것도 당연하지 않겠느냐.",
  ui_story_5070_50701102_53_dialog_content = "종서 씨...",
  ui_story_5070_50701102_54_dialog_content = "왜 그러는가?",
  ui_story_5070_50701102_55_dialog_content = "종서 씨 옆에도 고양이가 세 마리 있잖아요... 설마 종서 씨는... 아니죠?",
  ui_story_5070_50701102_56_dialog_content = "갑자기 고양이로 변신하진 않으실 거죠?",
  ui_story_5070_50701102_57_dialog_content = "하하하, 종 모는 그저 보통 사람일 뿐이오. 실망한 것은 아닌지 모르겠구려.",
  ui_story_5070_50701102_58_dialog_content = "아, 아니에요! 종서 씨가 그냥 믿음직한 보통 어른이라서 오히려 다행인걸요...",
  ui_story_5070_50701102_59_dialog_content = "윽... 이, 이 자식들...",
  ui_story_5070_50701102_60_dialog_content = "PlayerName, 쟤들 정신이 들었나 봐.",
  ui_story_5070_50701102_61_dialog_content = "게다가 녀석들 말고 입구 쪽에서도 사람들이 오고 있어.\n아무래도 갑판 쪽에서 온 것 같아.",
  ui_story_5070_50701102_62_dialog_content = "놈들을 포위해라!",
  ui_story_5070_50701102_63_dialog_content = "앉은뱅이 빼고는 싸울 수도 없는 놈들이야. 저 앉은뱅이도 대단한 건 화능술뿐이라고.",
  ui_story_5070_50701102_64_dialog_content = "그러니 불만 못 쓰게 만들면 아무 쓸모도 없어!",
  ui_story_5070_50701102_65_dialog_content = "이 자식들!",
  ui_story_5070_50701102_66_dialog_content = "종서 씨, 저랑 리청이 방법을 생각해 볼 테니까, 종서 씨는 최대한 조심하세요!",
  ui_story_5070_50701102_67_dialog_content = "어? PlayerName 너 아직도 모르고 있었구나? 사실...",
  ui_story_5070_50701102_68_dialog_content = "귀공의 호의는 감사히 받겠소.",
  ui_story_5070_50701102_69_dialog_content = "귀공을 보니 린 가문의 가주가 떠오르는구려.\n분명 유약하면서도 오히려 자주 귀공처럼 이 종 모를 지키려 했었지...",
  ui_story_5070_50701102_70_dialog_content = "허나 종 모는 저런 이들을 오랜 세월 동안 겪어 보았소.\n어쩌면 이곳에 사로잡힌 것 또한 운명의 안배일지도 모르오.",
  ui_story_5070_50701102_71_dialog_content = "이는 필시 과거의 빚을 이 해적들에게 갚아주라는 하늘의 뜻일 것이오.",
  ui_story_5070_50701102_72_dialog_content = "그러니 저들은 종 모에게 맡기고, 귀공은 잠시 기다려 주지 않겠는가.",
  ui_story_5070_50701102_73_dialog_content = "좋아요. 그럼 전 옆에서 최대한 도울게요...",
  ui_story_5070_50701102_74_dialog_content = "괜찮소. 귀공이 지닌 기묘한 능력은 작화군주나 선기경과 더 합이 맞을 것이오.",
  ui_story_5070_50701102_75_dialog_content = "이 종 모가 아는 전법은 하나뿐이고, 필요한 전법 또한 하나뿐이오.",
  ui_story_5070_50701102_76_dialog_content = "도움을 주고 싶거든, 저들이 가져갔던 검을 종 모에게 건네주시오.",
  ui_story_5070_50701102_77_dialog_content = "네! 이거 맞죠? ...뭐야, 엄청 무겁네요!",
  ui_story_5070_50701102_78_dialog_content = "고맙소.",
  ui_story_5070_50701102_79_dialog_content = "(...검을 손에 쥔 순간, 왠지 종서 씨의 눈빛이 변한 것 같아.)",
  ui_story_5070_50701102_80_dialog_content = "하하, 저 앉은뱅이가 지금 뭐라는 거냐? 혼자서 우릴 상대하겠다고?",
  ui_story_5070_50701102_81_dialog_content = "분수도...",
  ui_story_5070_50701102_82_dialog_content = "<color=#e8d9bb>스윽!</color>",
  ui_story_5070_50701102_83_dialog_content = "모르...는...",
  ui_story_5070_50701102_84_dialog_content = "<color=#e8d9bb>거만한 미소가 얼굴에서 미처 사라지기도 전에, 해적의 몸이 먼저 땅으로 엎어졌다.</color>",
  ui_story_5070_50701102_85_dialog_content = "저, 저놈... 방금 뭘 한 거야?!",
  ui_story_5070_50701102_86_dialog_content = "당황하지 마! 그냥 검 뽑는 게 좀 빠를 뿐이야! 사람은 우리가 더 많으니까... 크억!",
  ui_story_5070_50701102_87_dialog_content = "그런 형편없는 칭찬을 하느니 그대로 엎어져 있는 편이 내게 이로울 것이다.",
  ui_story_5070_50701102_88_dialog_content = "뭐야?! 누가 불만 못 쓰게 하면 괜찮을 거랬어?!",
  ui_story_5070_50701102_89_dialog_content = "저놈... 불 같은 건 쓰지도 않잖아!",
  ui_story_5070_50701102_90_dialog_content = "저 해적들, 종서 씨한테 완전히 기세가 꺾여 버렸는데?",
  ui_story_5070_50701102_91_dialog_content = "당연하지, 우리 형님이 어떤 분이신데.",
  ui_story_5070_50701102_92_dialog_content = "주...죽어라!",
  ui_story_5070_50701102_93_dialog_content = "종서 씨! 뒤에 조심해요!",
  ui_story_5070_50701102_94_dialog_content = "<color=#e8d9bb>스윽!</color>",
  ui_story_5070_50701102_95_dialog_content = "크악──!",
  ui_story_5070_50701102_96_dialog_content = "괜한 걱정이었나 봐... 종서 씨 검이 내 말보다 더 빨랐잖아.",
  ui_story_5070_50701102_97_dialog_content = "잘 봐. 이륜거에 앉아 계실 수밖에 없지만, 저런 오합지졸은 형님한테는 상대도 안 된다구.",
  ui_story_5070_50701102_98_dialog_content = "해난은 나의 두 다리를 부수었다.",
  ui_story_5070_50701102_99_dialog_content = "<color=#e8d9bb>스윽!</color>",
  ui_story_5070_50701102_100_dialog_content = "하면 너희도 어디 나의 불길을 막아 보아라.",
  ui_story_5070_50701102_101_dialog_content = "<color=#e8d9bb>스윽!</color>",
  ui_story_5070_50701102_102_dialog_content = "내게 한 팔과 검 한 자루가 남아 있는 한.",
  ui_story_5070_50701102_103_dialog_content = "<color=#e8d9bb>스윽!</color>",
  ui_story_5070_50701102_104_dialog_content = "나는 여전히 검을 휘두르고, 적을 벨 수 있다.",
  ui_story_5070_50701102_105_dialog_content = "내가 아는 전법은 오직 그것뿐이다.",
  ui_story_5070_50701102_106_dialog_content = "괴, 괴물이다...!",
  ui_story_5070_50701102_107_dialog_content = "수년 전에는 너희들에게 자주 그리 불리곤 했지.",
  ui_story_5070_50701102_108_dialog_content = "...잠깐만, 설마...",
  ui_story_5070_50701102_109_dialog_content = "...기억났어!",
  ui_story_5070_50701102_110_dialog_content = "붉은 머리... 장포를 입은 남자...",
  ui_story_5070_50701102_111_dialog_content = "검 한 자루로... 홀로 한 배의 해적을 평정하고...",
  ui_story_5070_50701102_112_dialog_content = "제나라 근해를 주름잡던 해적을 거의 괴멸시켰던...",
  ui_story_5070_50701102_113_dialog_content = "앙경 조정의 황제가 직접 임명했다는 그... 평야대장군...!",
  ui_story_5070_50701102_114_dialog_content = "모두 옛일일 뿐이다.",
  ui_story_5070_50701102_115_dialog_content = "<color=#e8d9bb>스윽──</color>",
  ui_story_5070_50701102_116_dialog_content = "<color=#e8d9bb>마지막 적이 바닥에 쓰러졌다.</color>",
  ui_story_5070_50701102_117_dialog_content = "작금의 종 모는 일개 낭인일 뿐.",
  ui_story_5070_50701102_118_dialog_content = "아니면 젊은이에게 조금이나마 힘이 되는 어른이라 하여도 무방하겠지.",
  ui_story_5070_50701201_1_dialog_content = "<color=#e8d9bb>같은 시간, 적의 배</color>",
  ui_story_5070_50701201_2_dialog_content = "(이 배의 구조... 신풍호랑 똑같잖아?)",
  ui_story_5070_50701201_3_dialog_content = "<color=#e8d9bb>지이잉──</color>",
  ui_story_5070_50701201_4_dialog_content = "!",
  ui_story_5070_50701201_5_dialog_content = "올라오자마자 이런 큰 선물이라니, 너무 과분하잖아?",
  ui_story_5070_50701201_6_dialog_content = "형태는 전갈 꼬리인데, 발사하는 건 암기의 독침이 아니라...",
  ui_story_5070_50701201_7_dialog_content = "아스트라 사람들이 잘 쓰는 광력 집속탄인가.",
  ui_story_5070_50701201_8_dialog_content = "끼이익!",
  ui_story_5070_50701201_9_dialog_content = "꼬리는 총포, 집게는 칼날, 몸통에는 두꺼운 금속 갑옷까지...",
  ui_story_5070_50701201_10_dialog_content = "「천기제사!」",
  ui_story_5070_50701201_11_dialog_content = "<color=#e8d9bb>띵──</color>",
  ui_story_5070_50701201_12_dialog_content = "소리는 금속 같은데, 재질은 옥처럼 가볍구나.",
  ui_story_5070_50701201_13_dialog_content = "이런 공격을 받고도 흠집이 없는 걸 보면, 확실히 희귀하고 좋은 재료를 쓴 것 같네.",
  ui_story_5070_50701201_14_dialog_content = "이거 정말...",
  ui_story_5070_50701201_15_dialog_content = "끼릭, 끼릭, 끼릭...",
  ui_story_5070_50701201_16_dialog_content = "이 녀석, 연료 소모량도 적지 않겠지?",
  ui_story_5070_50701201_17_dialog_content = "그런데 꽤 오래 상대했는데도, 공격 빈도나 강도가 줄지도 않고 오히려 더 강해졌잖아?",
  ui_story_5070_50701201_18_dialog_content = "내부의 구동 중추가 썩 뛰어난 모양이네. 천하에 몇 없는 수준이겠어.",
  ui_story_5070_50701201_19_dialog_content = "음, 이런 우연이 다 있네. 마침 신풍호에도 그런 게 하나 있었거든.",
  ui_story_5070_50701201_20_dialog_content = "혹시 내가 이 녀석을 분해하면, 안에 든 핵심 부품이...",
  ui_story_5070_50701201_21_dialog_content = "촉음화랑 똑같이 생겼으려나?",
  ui_story_5070_50701201_22_dialog_content = "어디 분해할 수나 있겠어?",
  ui_story_5070_50701201_23_dialog_content = "이제야 모습을 드러낼 마음이 생겼구나?",
  ui_story_5070_50701201_24_dialog_content = "손 씨라는 가짜 신분, 그리고는 저런 못생긴 덩치.",
  ui_story_5070_50701201_25_dialog_content = "난 또 어디 숨지 않으면 아무것도 못 하는 사람인 줄 알았지 뭐야.",
  ui_story_5070_50701201_26_dialog_content = "하, 너와 말다툼할 생각 따윈 없어.",
  ui_story_5070_50701201_27_dialog_content = "패자의 독설은 무능함의 상징일 뿐이니까.",
  ui_story_5070_50701201_28_dialog_content = "패자? 반대로 말한 거 아냐?",
  ui_story_5070_50701201_29_dialog_content = "자기가 남보다 못하단 걸 인정하고, 자기가 패배자라고 믿으니까...",
  ui_story_5070_50701201_30_dialog_content = "조급해져서 갖은 궁리로 남의 걸 빼앗으려고 하는 거잖아?",
  ui_story_5070_50701201_31_dialog_content = "처음엔 불게의 설계도를 훔쳤지.",
  ui_story_5070_50701201_32_dialog_content = "그다음엔 몰래 기관 부품을 빼돌리고, 해적을 데려다 린 가문 상선을 약탈했어.",
  ui_story_5070_50701201_33_dialog_content = "그리고 이번엔 했던 대로 똑같이 촉음화를 훔쳐서, 저런 얼치기 따위에 쓰고 말이야.",
  ui_story_5070_50701201_34_dialog_content = "이쯤에서 한 가지 물어볼 게 있어.",
  ui_story_5070_50701201_35_dialog_content = "뭐지?",
  ui_story_5070_50701201_36_dialog_content = "우리 건운종은 늘 정정당당하게 기술로 명성을 얻어 왔어.",
  ui_story_5070_50701201_37_dialog_content = "그런데 언제 그런 하찮은 도둑질을 가르쳤을까?",
  ui_story_5070_50701201_38_dialog_content = "하...",
  ui_story_5070_50701201_39_dialog_content = "날 알아봤구나.",
  ui_story_5070_50701201_40_dialog_content = "하지만 넌 늘 기관술만 생각했으니까, 내 얼굴까지 기억하고 있을진 모르겠네.",
  ui_story_5070_50701201_41_dialog_content = "오랜만이야, 선극... 사매.",
  ui_story_5070_50701201_42_dialog_content = "호련.",
  ui_story_5070_50701201_43_dialog_content = "이젠 사저라고 부르지도 않는구나. 저명하신 선기경 나리는 역시 예전과는 참 달라졌어.",
  ui_story_5070_50701201_44_dialog_content = "진작 파문됐으니까, 사저는 아니지.",
  ui_story_5070_50701201_45_dialog_content = "흥, 멋대로 지껄이는 것도 이제 마지막이니까, 사저로서 용서해 줄게.",
  ui_story_5070_50701201_46_dialog_content = "어려서부턴 순탄한 길만 걸어 온 종문의 천재가,\n버림받은 제자의 작품에 속수무책으로 당하는 기분은...",
  ui_story_5070_50701201_47_dialog_content = "확실히 좀 괴로울 테니까.",
  ui_story_5070_50701201_48_dialog_content = "뭐, 괜찮아. 넌 옛정 같은 건 생각하지 않겠지만, 난 아니거든.",
  ui_story_5070_50701201_49_dialog_content = "종문에서 함께 자란 정을 봐서, 네가 얌전히 패배만 인정한다면 보내줄 수 있어.",
  ui_story_5070_50701201_50_dialog_content = "사매는 아직 몰라... 이제 곧 종횡가의 시대가 찾아올 거야!",
  ui_story_5070_50701201_51_dialog_content = "앞으로 8대 제후국의 정세는 급변할 거야.\n그래도 너 같은 인재는 어디든 갈 곳이 있을 거잖아?",
  ui_story_5070_50701201_52_dialog_content = "그럼 발 아래 이 배는 사저가 마지막으로 주는 작별 선물이라고 생각해 두렴. 어떠니?",
  ui_story_5070_50701201_53_dialog_content = "역시나.",
  ui_story_5070_50701201_54_dialog_content = "촉음화뿐만 아니라, 신풍호도 노리고 있었어.",
  ui_story_5070_50701201_55_dialog_content = "당신이 날 살려보낼 거라고 내가 믿을 것 같아?",
  ui_story_5070_50701201_56_dialog_content = "역시 사매의 혜안은 속일 수가 없구나.",
  ui_story_5070_50701201_57_dialog_content = "이 배가 신풍호를 모방해서 만들었다는 건 딱 보면 뻔하거든.\n다만 여러 부분에서 형태만 갖추었을 뿐, 진짜와는 비교할 수 없어.",
  ui_story_5070_50701201_58_dialog_content = "신풍호의 핵심 부품은 여러 명가에서 힘을 합쳐 만든 거니까,\n나 혼자 모방하는 건 역시 어려운 일이잖아.",
  ui_story_5070_50701201_59_dialog_content = "사실 내 원래 임무는 신풍호의 설계도를 손에 넣는 거였어.",
  ui_story_5070_50701201_60_dialog_content = "그런데 신풍호 자체를 손에 넣을 기회가 찾아왔는데, 이렇게 기쁜 일이 또 어디 있겠니?",
  ui_story_5070_50701201_61_dialog_content = "지금의 신풍호는 사매의 기상천외한 발상 덕분에 엉망으로 개조됐지만...",
  ui_story_5070_50701201_62_dialog_content = "그 정도 뒷수습은 이 사저가 얼마든지 해 줄 수 있어.",
  ui_story_5070_50701201_63_dialog_content = "(임무라...)",
  ui_story_5070_50701201_64_dialog_content = "지하 감옥에서 말본새 고약한 녀석들과 잡담이나 하는 것보다는\n지금 일이 훨씬 더 즐거우니까.",
  ui_story_5070_50701201_65_dialog_content = "일전의 린 가문 상선을 탈취한 것도 당신 짓이야?",
  ui_story_5070_50701201_66_dialog_content = "상황 파악이 빠르네.",
  ui_story_5070_50701201_67_dialog_content = "이 역용술과 언성을 모사하는 술법만 있으면...",
  ui_story_5070_50701201_68_dialog_content = "승객이나 선원으로 변장해서 항해에 나서고,\n배의 방어를 안에서부터 와해시키는 건 쉬운 일이거든.",
  ui_story_5070_50701201_69_dialog_content = "원래는 신풍호도 그렇게 손에 넣으려고 쌍사성에서 공을 들여 준비하고 있었어...",
  ui_story_5070_50701201_70_dialog_content = "그러다 그 선창에 아주 특별한 게 숨겨져 있단 걸 발견했지 뭐니?",
  ui_story_5070_50701201_71_dialog_content = "우리 사매가 그 전설의 촉음화를 찾아냈을 줄은 누가 알았겠어?",
  ui_story_5070_50701201_72_dialog_content = "마침 내가 여러 문파의 장점을 집대성한 기관수의 정점을 만들고도\n적합한 동력원이 없던 차에 말이야.",
  ui_story_5070_50701201_73_dialog_content = "이렇게나 공교롭다니, 그야말로 모두 날 위해 준비된 게 아니겠어?",
  ui_story_5070_50701201_74_dialog_content = "하아...",
  ui_story_5070_50701201_75_dialog_content = "...그 한숨, 뭐야?",
  ui_story_5070_50701201_76_dialog_content = "그때나 지금이나 정말 달라진 게 없구나.",
  ui_story_5070_50701201_77_dialog_content = "상황이 이 지경이 됐는데, 아직도 종문의 천재니 뭐니 기교사의 위세를 부릴 생각이야?",
  ui_story_5070_50701201_78_dialog_content = "아직도 현실을 모르겠어? 사매.",
  ui_story_5070_50701201_79_dialog_content = "아무리 너라도 내 기관수, 내 최고의 걸작엔 조금의 흠집도 못 내!",
  ui_story_5070_50701201_80_dialog_content = "「내」 기관수?",
  ui_story_5070_50701201_81_dialog_content = "베껴온 도면, 훔쳐온 부품, 다른 건 아무것도 고려하지 않고\n그저 강한 부품들만 덕지덕지 꿰맞춘 누더기.",
  ui_story_5070_50701201_82_dialog_content = "당신 작품이라면서 정작 이 기관수 어디에 「당신」이 있는 건데?",
  ui_story_5070_50701201_83_dialog_content = "어째서 너까지 종문의 고지식한 놈들처럼 말하는 거야?",
  ui_story_5070_50701201_84_dialog_content = "기관술은 기술일 뿐이야. 중요한 건 강한 기관이지, 다른 건 신경 쓸 필요도 없다고.",
  ui_story_5070_50701201_85_dialog_content = "그 녀석들도 이제 완벽해진 내 「비채」를 보면 머리를 조아릴 수밖에 없을걸!",
  ui_story_5070_50701201_86_dialog_content = "그러니까 사부님이 당신은 처음부터 끝까지 기관술이 뭔지 모른다고 하신 거야.",
  ui_story_5070_50701201_87_dialog_content = "사부님들이 이 광경을 보셨으면, 당신을 두 번, 세 번 파문하지 못해서 아쉬워하셨을걸.",
  ui_story_5070_50701201_88_dialog_content = "...역시 너랑 쓸데없이 떠들지 말 걸 그랬어.",
  ui_story_5070_50701201_89_dialog_content = "비채, 가서 뭉개버려. 기관수가 진정 가져야 할 힘이 무엇인지 똑똑히 가르쳐 줘!",
  ui_story_5070_50701201_90_dialog_content = "신풍호에 있던 해적들은 이제 거의 다 쓰러트린 것 같네요. 다들 괜찮아요?",
  ui_story_5070_50701201_91_dialog_content = "대부분 무사해. 선원 몇 명이 부상을 입었고, 승객 몇 명이 사라지긴 했지만.",
  ui_story_5070_50701201_92_dialog_content = "구가 상처를 입고 물에 빠진 뒤로 아직 돌아오질 않았다...",
  ui_story_5070_50701201_93_dialog_content = "...전하! 무사하십니까!",
  ui_story_5070_50701201_94_dialog_content = "구야! 네가 외려 내 걱정을 하면 어쩌자는 게야... 많이 다치진 않았느냐?",
  ui_story_5070_50701201_95_dialog_content = "실수로 물을 조금 삼켰을 뿐입니다.",
  ui_story_5070_50701201_96_dialog_content = "이런 시기에 전하의 곁을 지키지 못해 호위로서 면목이 없습니다.\n실책에 대한 벌은 달게 받겠습니다.",
  ui_story_5070_50701201_97_dialog_content = "실없는 소리 말거라.\n애당초에 거뜬히 피했을 것을 내 염려를 하다 그리된 것이 아니더냐...",
  ui_story_5070_50701201_98_dialog_content = "내 어찌 널 벌한단 말이냐. 리청, 어서 구의 상태를 봐 주거라...",
  ui_story_5070_50701201_99_dialog_content = "감사합니다, 전하.",
  ui_story_5070_50701201_100_dialog_content = "휴, 구도 돌아왔으니 이제 자리에 없는 이는 선기경뿐인가...",
  ui_story_5070_50701201_101_dialog_content = "선극 씨는 아마 맞은편의 저 배에 있을 거예요.",
  ui_story_5070_50701201_102_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5070_50701201_103_dialog_content = "또 저 기묘한 빛이로구나...",
  ui_story_5070_50701201_104_dialog_content = "저도 볼래요!",
  ui_story_5070_50701201_105_dialog_content = "저 녀석 지금 뭐랑 싸우고 있는 거야?! 반격을 해야지 왜 피하기만 하는 건데?",
  ui_story_5070_50701201_106_dialog_content = "도저히 못 봐주겠네. 종서 형님, 우리도 도와주러 가요!",
  ui_story_5070_50701201_107_dialog_content = "이런 위급한 상황에서 도와주고 나면 앞으로는 저한테 꼬맹이란 소리는 못 하겠죠!",
  ui_story_5070_50701201_108_dialog_content = "어쩌면 필요하지 않을 수도 있다.",
  ui_story_5070_50701201_109_dialog_content = "네? 설마 저 녀석이 형님한테도 뭐 밉보인 거 있어요? 진짜로 안 도와주시려고요?",
  ui_story_5070_50701201_110_dialog_content = "내 말은 선기경이 고전하고 있지 않다는 뜻이다.",
  ui_story_5070_50701201_111_dialog_content = "종서 씨 말씀대로야. 그저 피하기 급급한 것처럼 보이진 않거든.",
  ui_story_5070_50701201_112_dialog_content = "아무래도 상대의 공격을 이용해서 주변을 파괴하고 있는 것 같아.",
  ui_story_5070_50701201_113_dialog_content = "저 기관수가 서 있는 곳을 부수는 거지!",
  ui_story_5070_50701201_114_dialog_content = "근데 왜 그래야 되는데?",
  ui_story_5070_50701201_115_dialog_content = "그건 나도 잘... 아니지, 왠지 알 것 같아.",
  ui_story_5070_50701201_116_dialog_content = "신풍호의 선체 강도라면, 지금 이 배에 있는 모든 부품 재고를 써서 보강하더라도...",
  ui_story_5070_50701201_117_dialog_content = "촉음화의 최대 출력을 감당하는 건 어려울지도 몰라.",
  ui_story_5070_50701201_118_dialog_content = "갑판에 있는 커다란 구멍을 수리하지 않는다는 건 그렇다 쳐도,\n그걸 일부러 더 크게 만들겠다고?",
  ui_story_5070_50701201_119_dialog_content = "신풍호의 중추까지 드러나게 생겼는데, 일을 이런 식으로 하는 경우가 어디 있어?\n...자넨 어떻게 생각하나?",
  ui_story_5070_50701201_120_dialog_content = "시험 가동에 실패한 것도, 누군가 촉음화를 노리고 있다는 것도 일단은 비밀로 해 줘.",
  ui_story_5070_50701201_121_dialog_content = "그거야 가능하지만... 그럼 우린 이제 어떡해?",
  ui_story_5070_50701201_122_dialog_content = "기다려야지.",
  ui_story_5070_50701201_123_dialog_content = "(...아니겠지?)",
  ui_story_5070_50701201_124_dialog_content = "(내 생각이 맞다면... 선극 씨는 나한테 다시는 무모하다고 하면 안 될 것 같은데?)",
  ui_story_5070_50701201_125_dialog_content = "(이 배에서 가장 간이 큰 사람은 바로 선극 씨니까!)",
  ui_story_5070_50701201_126_dialog_content = "PlayerName, 어딜 보는 거야? 갑판의 커다란 구멍에 뭐가 있어?",
  ui_story_5070_50701201_127_dialog_content = "지금은 없지.",
  ui_story_5070_50701201_128_dialog_content = "근데 이제 곧 생길 거야.",
  ui_story_5070_50701201_129_dialog_content = "여러분! 저 좀 도와주세요!",
  ui_story_5070_50701201_130_dialog_content = "우리가 저 기관수를 신풍호로 유인해야 돼요!",
  ui_story_5070_50701201_131_dialog_content = "「뇌광의 기철!」",
  ui_story_5070_50701201_132_dialog_content = "소용없다고 했잖아.",
  ui_story_5070_50701201_133_dialog_content = "비채의 모든 부품은 내가 천하 곳곳을 다니면서 찾은 최고의 설계로 만든 거니까.",
  ui_story_5070_50701201_134_dialog_content = "네 공격은 아무 의미 없는 헛수고야!",
  ui_story_5070_50701201_135_dialog_content = "(그거야 모르지.)",
  ui_story_5070_50701201_136_dialog_content = "?!",
  ui_story_5070_50701201_137_dialog_content = "PlayerName? 이쪽에 감응할 정신이 있는 걸 보면 일이 잘 풀렸나 봐?",
  ui_story_5070_50701201_138_dialog_content = "(하하... 종서 씨 덕분에 살았어. 그 얘긴 일단 나중에 하자.)",
  ui_story_5070_50701201_139_dialog_content = "(방금 둘이 하는 얘기 들었어. 그날 그 폭발은 거기 가짜 손 씨가 벌인 짓이구나?)",
  ui_story_5070_50701201_140_dialog_content = "(물건을 훔치다 벼락을 맞다니, 용주에선 그런 걸 「인과응보」라고 하지?)",
  ui_story_5070_50701201_141_dialog_content = "(근데 그 사람은 아직도 운명이 자기 편이라고 생각하는 거야?\n난 벼락 맞을 운명 같은 건 사양하고 싶은데.)",
  ui_story_5070_50701201_142_dialog_content = "하, 그러게 말이야~",
  ui_story_5070_50701201_143_dialog_content = "저 기관수 너무 못생긴 거 아냐? 꿈틀거리는 걸 보니까 입맛이 뚝 떨어졌잖아.",
  ui_story_5070_50701201_144_dialog_content = "내 필경 시답잖을 것이라 하지 않았느냐. 역시 내 말이 맞았던 게야.",
  ui_story_5070_50701201_145_dialog_content = "...신풍호의 위상이 저런 흉물과 비교당할 정도로 땅에 떨어지는 날이 올 줄은 몰랐네요.",
  ui_story_5070_50701201_146_dialog_content = "...입 다물어!",
  ui_story_5070_50701201_147_dialog_content = "비채! 신풍호로 간다! 저 사리 분별도 못하는 것들을 모조리 없애버려!",
  ui_story_5070_50701202_1_dialog_content = "내... 최강의 기관수가... 어째서...",
  ui_story_5070_50701202_2_dialog_content = "이 녀석들...!",
  ui_story_5070_50701202_3_dialog_content = "왜, 더 싸우려고? 당신은 싸움엔 영 소질이 없었던 걸로 기억하는데.",
  ui_story_5070_50701202_4_dialog_content = "하... 하하, 아하하하!",
  ui_story_5070_50701202_5_dialog_content = "기뻐하긴 일러! 사매, 비채의 동력원이 뭐였는지 잊은 거니?!",
  ui_story_5070_50701202_6_dialog_content = "기관에 무궁무진한 힘을 선사해 주는 진짜 하늘의 선물, 촉음화라고!",
  ui_story_5070_50701202_7_dialog_content = "비채! 일어서! 아직 안 끝났잖아!",
  ui_story_5070_50701202_8_dialog_content = "다들 조심해! 저 커다란 녀석이 또 움직이기 시작했어!",
  ui_story_5070_50701202_9_dialog_content = "계속할 작정인가... 전하, 물러나 주십시오.",
  ui_story_5070_50701202_10_dialog_content = "너무 빨리 기뻐한 건 내가 아니라 당신이야.",
  ui_story_5070_50701202_11_dialog_content = "또 그런 눈으로... 날 그런 식으로 내려다보지 말란 말이야! 난...!",
  ui_story_5070_50701202_12_dialog_content = "PlayerName! 움직임을 막아! 잠깐이면 돼!",
  ui_story_5070_50701202_13_dialog_content = "(강제 감응!)",
  ui_story_5070_50701202_14_dialog_content = "으윽!",
  ui_story_5070_50701202_15_dialog_content = "저 사람 머리를 잠깐 어지럽게 만들 거예요! 모두 그 틈에 저 기관수를 밀어 넣어요!",
  ui_story_5070_50701202_16_dialog_content = "어...어디로? 설마 갑판 위에 있는 저 구멍 말하는 건 아니지?",
  ui_story_5070_50701202_17_dialog_content = "그건 평범한 구멍이 아냐.",
  ui_story_5070_50701202_18_dialog_content = "내가 녀석을 위해 미리 준비한 특등석이라고.",
  ui_story_5070_50701202_19_dialog_content = "하나, 둘, 셋!",
  ui_story_5070_50701202_20_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5070_50701202_21_dialog_content = "진짜 무거운 녀석이네. 그래도 어떻게든 들어갔어!",
  ui_story_5070_50701202_22_dialog_content = "이제부턴 나한테 맡겨.",
  ui_story_5070_50701202_23_dialog_content = "조금만 개조하면 녀석이랑 신풍호의 동력로를 연결할 수 있어.",
  ui_story_5070_50701202_24_dialog_content = "으윽... 뭐, 뭘 하려는 거야...?!",
  ui_story_5070_50701202_25_dialog_content = "내가 신풍호를 위해 그린 개조 설계도, 변장해 있을 때 봤을 거잖아?",
  ui_story_5070_50701202_26_dialog_content = "뭐...? 웃기지 마... 그, 그건 애초에 실현 불가능한 설계잖아!",
  ui_story_5070_50701202_27_dialog_content = "그런 구조로 신풍호만 한 선체를 지탱하겠다니...",
  ui_story_5070_50701202_28_dialog_content = "촉음화처럼 특별한 동력원의 최대 출력이 필요한 일을...",
  ui_story_5070_50701202_29_dialog_content = "신풍호에 쓰인 자재만 가지고 버틸 수 있을 것 같아?!",
  ui_story_5070_50701202_30_dialog_content = "맞아, 신풍호의 자재만 있었다면 내 구상도 터무니없는 망상에 불과했을 거야.",
  ui_story_5070_50701202_31_dialog_content = "그런데 당신이 최강의 기관수를 만들겠답시고...",
  ui_story_5070_50701202_32_dialog_content = "촉음화의 최대 출력을 견딜 정도로 훌륭한 소재들을 써 줬잖아?",
  ui_story_5070_50701202_33_dialog_content = "잠깐만... 설마 너... 미쳤어?! 그게 가능할 리가...",
  ui_story_5070_50701202_34_dialog_content = "그러니까 내가 말했잖아. 정해진 설계에만 얽매이는 당신은 기관술을 전혀 모른다고.",
  ui_story_5070_50701202_35_dialog_content = "천변만화의 조화로 만 가지 어려움을 이겨낼 수 있고,\n재료만 있다면 기관술은 무한한 가능성을 자아낼 수 있어.",
  ui_story_5070_50701202_36_dialog_content = "대체 둘 다 뭔 소리를 하는 거야?",
  ui_story_5070_50701202_37_dialog_content = "얌전히 앉아 있어, 꼬맹아. 이제 곧 알게 될 테니까.",
  ui_story_5070_50701202_38_dialog_content = "딱 한 번만 볼 수 있는 호화 기관술 공연이야. 오감을 활짝 열고 제대로 느껴 봐.",
  ui_story_5070_50701202_39_dialog_content = "비채를 새 동력원으로 삼아서 촉음화의 힘을 안정적으로 걸러낼 거야.",
  ui_story_5070_50701202_X39_dialog_content = "그리고 신풍호를...",
  ui_story_5070_50701202_40_dialog_content = "잠깐 날아오르게 만드는 거지!",
  ui_story_5070_50701202_41_dialog_content = "<color=#e8d9bb>뿌우우──</color>",
  ui_story_5070_50701202_42_dialog_content = "<color=#e8d9bb>아직 움직일 수 있는 사람들은 잠시 선원들 대신 선극의 지휘에 따라 움직였다.</color>",
  ui_story_5070_50701202_43_dialog_content = "<color=#e8d9bb>그리고 나팔 소리와 함께, 개조를 거친 신풍호의 기관들을 일제히 가동했다.</color>",
  ui_story_5070_50701202_44_dialog_content = "<color=#e8d9bb>선체가 진동하고, 선내의 기관들이 충돌하며 뻗어나가자,\n빛의 힘이 선체 양옆으로 펼쳐져 거대한 날개와 같은 형상을 이루었다.</color>",
  ui_story_5070_50701202_45_dialog_content = "PlayerName! 부탁할게!",
  ui_story_5070_50701202_46_dialog_content = "(강제 감응!)",
  ui_story_5070_50701202_47_dialog_content = "(촉음화에 감응해서 힘을 최대치로 끌어내는 거야! 그리고...)",
  ui_story_5070_50701202_48_dialog_content = "(신풍호, 가동!)",
  ui_story_5070_50701202_49_dialog_content = "이건 말도 안 돼... 불가능하다고...!",
  ui_story_5070_50701202_50_dialog_content = "빌어먹을... 요행일 뿐이야! 우린... 아직 끝나지 않았어!",
  ui_story_5070_50701202_51_dialog_content = "<color=#e8d9bb>풍덩!</color>",
  ui_story_5070_50701202_52_dialog_content = "저 여자 지금 바다로 뛰어들었어!",
  ui_story_5070_50701202_53_dialog_content = "됐어, 신경 안 써도 돼.",
  ui_story_5070_50701202_54_dialog_content = "배의 날개가 버틸 수 있는 시간은 한정돼 있으니까,\n어떻게든 단번에 이 일대를 빠져나가야 해.",
  ui_story_5070_50701202_55_dialog_content = "<color=#e8d9bb>끼긱, 끼기기긱──</color>",
  ui_story_5070_50701202_56_dialog_content = "(신풍호가 날아오른 지 얼마 되지 않아, 기관들이 부하를 견디지 못하는 소리가 들려왔다.)",
  ui_story_5070_50701202_57_dialog_content = "(마지막으로 전속력을 내기 시작하자, 두꺼웠던 빛의 날개도\n공중에서 점점 옅어지기 시작했다.)",
  ui_story_5070_50701202_58_dialog_content = "(하지만 이 정도면 이미 충분하다.)",
  ui_story_5070_50701202_59_dialog_content = "태양, 잔잔한 바람, 고요한 수면... 드디어 빠져나왔어!",
  ui_story_5070_50701202_60_dialog_content = "<color=#e8d9bb>철썩──!</color>",
  ui_story_5070_50701202_61_dialog_content = "<color=#e8d9bb>신풍호는 수면 위로 세차게 떨어졌다.</color>",
  ui_story_5070_50701202_62_dialog_content = "<color=#e8d9bb>하지만 이번에는 소용돌이와 암류가 아닌, 평온한 바다에 둘러싸여 있었다.</color>",
  ui_story_5070_50701202_63_dialog_content = "우리가 해냈어!",
  ui_story_5070_50701202_64_dialog_content = "선극 씨! 진짜 최고야! 대단해!",
  ui_story_5070_50701202_65_dialog_content = "대단한 건 기관술이지.",
  ui_story_5070_50701202_66_dialog_content = "뭐, 그래도 이번엔 나도 뻔뻔하게 칭찬 좀 받아볼게.",
  ui_story_5070_50701202_67_dialog_content = "그나저나 잠깐이긴 했지만 신풍호가 하늘을 날았잖아?",
  ui_story_5070_50701202_68_dialog_content = "그럼 선극 씨도 이번만큼은 명실상부한 신풍호의 조종사였던 거네.",
  ui_story_5070_50701202_69_dialog_content = "...그러게.",
  ui_story_5070_50701202_70_dialog_content = "이 느낌, 아마 평생 잊을 수 없을 거야.",
  ui_story_5070_50701202_71_dialog_content = "(그 해역을 지난 후, 선극 씨는 별자리판 같은 기계들을 활용해\n신풍호를 빠르게 기존 항로로 되돌려 놓았다.)",
  ui_story_5070_50701202_72_dialog_content = "(그리고 다음 날, 우리는 멀지 않은 바다 위에서 호련이 탔던 배의 잔해를 발견했다.)",
  ui_story_5070_50701202_73_dialog_content = "자신이 해친 린 가문의 상선처럼, 저 배가 가라앉는 것 또한 인과응보인 것이겠지.",
  ui_story_5070_50701202_74_dialog_content = "허나 저자나 그 배후 같은 존재들은 그리 쉽게 죽지도, 쉽사리 포기하지도 않을 것이오.",
  ui_story_5070_50701202_75_dialog_content = "앞으로 저들이 또 어떤 음모를 획책할지 모르오.",
  ui_story_5070_50701202_76_dialog_content = "모든 일에는 대처할 방법이 있는걸요.\n어떤 적이 공격해 온들, 그 공격에 대응할 기관이 있을 테니까요.",
  ui_story_5070_50701202_77_dialog_content = "없다면 새로 하나 만들면 되죠.",
  ui_story_5070_50701202_78_dialog_content = "저 호련이란 사람은 선극 씨의 사저였던 거지?",
  ui_story_5070_50701202_79_dialog_content = "파문당했다곤 하지만 한때 거대 종문의 제자였던 사람이잖아.",
  ui_story_5070_50701202_80_dialog_content = "비채 같은 것도 만들어 냈고, 보통 사람보다 훨씬 강했어.",
  ui_story_5070_50701202_81_dialog_content = "근데 어쩌다가 남한테 고용돼서 해적이 됐던 걸까?",
  ui_story_5070_50701202_82_dialog_content = "짚이는 게 하나 있긴 해.",
  ui_story_5070_50701202_83_dialog_content = "하지만 그걸 추적했을 때 벌어질 결과가 좋은 쪽일지, 아니면 나쁜 쪽일지 잘 모르겠어.",
  ui_story_5070_50701202_84_dialog_content = "호련은 많은 기관술의 기교를 배웠지만, 시종일관 기관술이 뭔지는 이해하지 못했어.",
  ui_story_5070_50701202_85_dialog_content = "그건 백 년의 기예와 천 년의 결심으로 탄생한 것들이니까.",
  ui_story_5070_50701202_86_dialog_content = "음모를 꾸미고, 남의 것을 훔치는 사람은 얻을 수도 없고, 이해할 수도 없는 거야.",
  ui_story_5070_50701202_87_dialog_content = "선기경, 그대가 말한 것들을 내 전부 가지고 와 보았다.",
  ui_story_5070_50701202_88_dialog_content = "허나 배에서 곡절이 많았던 탓에, 숙부와 나누었던 서신은 이것들밖에 남지 않았구나.",
  ui_story_5070_50701202_89_dialog_content = "헌데 어찌하여 이 서신들이 필요한 것이냐?",
  ui_story_5070_50701202_90_dialog_content = "음... 그건 확인해 봐야 말씀드릴 수 있을 것 같네요.",
  ui_story_5070_50701202_91_dialog_content = "참, 구 소저는 좀 어떤가요?",
  ui_story_5070_50701202_92_dialog_content = "그래도 잊지 않고 마음을 써 주는 게로구나.",
  ui_story_5070_50701202_93_dialog_content = "이미 리청이 진맥을 해 보았다. 며칠 요양하면 금방 회복될 게야..",
  ui_story_5070_50701202_94_dialog_content = "(무거웠던 분위기는 다시 평범하고 일상적인 이야기를 나누던 때로 돌아와 있었다.)",
  ui_story_5070_50701202_95_dialog_content = "(하지만 난 선극 씨가 그 편지들을 조심스럽게 챙기는 것을 보았지만...)",
  ui_story_5070_50701202_X95_dialog_content = "(결국 끝까지 「편지를 달라고 한 이유」에 대해서는 듣지 못했다.)",
  ui_story_5070_50701301_1_dialog_content = "(배에서 지낸 마지막 이틀은 정말 순식간에 지나갔다.)",
  ui_story_5070_50701301_2_dialog_content = "(너무나도 많은 위기와 전투를 겪은 우린 이미 몸도 마음도 지쳐 있었다.)",
  ui_story_5070_50701301_3_dialog_content = "(다행인 것은 배의 수리를 마치고 얼마 되지 않아서...\n눈앞에 용주가 보이기 시작했다는 것이었다.)",
  ui_story_5070_50701301_4_dialog_content = "이번 항해는 참 다사다난했지만, 그래도 무사히 돌아올 수 있었습니다.",
  ui_story_5070_50701301_5_dialog_content = "신풍호가 입항을 마치면, 이번 여정도 정식으로 끝이 나겠군요.",
  ui_story_5070_50701301_6_dialog_content = "신풍호를 대표해 지금까지 함께 힘써 주신 여러분께 감사드립니다.",
