  ui_story_5070_50701301_9_dialog_content = "전하, 방금 전갈을 받았습니다.\n전하를 궁으로 모실 제나라 사자가 항구에서 기다리고 있다고 합니다.",
  ui_story_5070_50701301_10_dialog_content = "바다 건너 교역의 물꼬를 트고, 정보도 가지고 돌아왔으니,\n응당 서둘러 돌아가 아뢰어야겠지.",
  ui_story_5070_50701301_11_dialog_content = "아마 한동안은 여러 연회에 두루 참석하게 생겼구나.",
