  ui_story_5070_50701301_40_dialog_content = "임무를 마치고 먼 길에서 돌아왔으니, 가족들에게 안부 인사를 전해야 하지 않겠느냐.",
  ui_story_5070_50701301_41_dialog_content = "예, 전하께서 무사하신 것을 아시면 필경 모두 기뻐하실 겁니다.",
