  ui_story_5070_50701301_60_dialog_content = "이번 여정은 폭풍과 암귀도 모자라서 해적까지 만날 줄은 정말 꿈에도 몰랐습니다.",
  ui_story_5070_50701301_61_dialog_content = "그나마 일전에 이번 여행의 운을 점쳐 두어서 참으로 다행이었지요.",
